// Zirvə — qrammatika izahları, SADƏ format (Fuad: «rahat yolla, nümunələr altda ayrıca»).
// Hər qayda: h = başlıq, t = 3–5 sadə cümlə (izah, nümunəsiz), tbl = kiçik cədvəl, ex = nümunələr [ingiliscə, azərbaycanca], no = səhv forma (xəbərdarlıq).
const GRAM_EXPL = {
g01: [
 {h:"1. Hər ingilis cümləsində fel olmalıdır",
  t:"Azərbaycanca «yorğunam», «evdədir», «tələbəyik» deyirik: «-am, -dır, -ik» sözün sonuna şəkilçi kimi yapışır. İngiliscə belə şəkilçi yoxdur, onun yerinə ayrıca söz yazılır: am, is və ya are. Bu söz «olmaq» felidir (ingiliscə be). Onu atsan, cümlə yarımçıq qalır, çünki ingilis cümləsində mütləq fel olmalıdır. Ona görə «Mən yorğunam» ingiliscə üç sözdür: I + am + tired.",
  ex:[["I am tired.","Mən yorğunam."],["She is at home.","O evdədir."],["They are students.","Onlar tələbədir."],["My sister is a nurse.","Bacım tibb bacısıdır."]],
  no:"I tired. / She at home. — səhvdir (am / is yoxdur)"},
 {h:"2. am, is, are — hansını seçim?",
  t:"Seçim cümlədə «kim» (və ya «nə») haqqında danışdığından asılıdır. I (mən) ilə həmişə am işlənir. Bir adam, bir əşya və ya bir yer haqqında danışanda — he, she, it, Baku, my son, this tea — is işlənir. İki və daha çox adam və ya şey haqqında, həmçinin you (sən / siz) ilə are işlənir. İki ad and ilə birləşəndə onlar artıq «çox» sayılır, ona görə Murad and I ilə are gəlir.",
  tbl:[["I","am"],["he / she / it, bir ad, bir əşya","is"],["we / you / they, iki və daha çox","are"]],
  ex:[["Baku is a big city.","Bakı böyük şəhərdir."],["My parents are at work now.","Valideynlərim indi işdədir."],["Murad and I are colleagues.","Murad və mən iş yoldaşıyıq."],["You are my best friend.","Sən mənim ən yaxın dostumsan."]],
  no:"My parents is at work. / Murad and I am… — səhvdir"},
 {h:"3. am / is / are nə vaxt lazımdır: necə? harada? kim?",
  t:"Cümlədə iş-hərəkət yoxdursa, am / is / are işlənir. Yəni kiminsə NECƏ olduğunu (yorğun, hazır, ac), HARADA olduğunu (evdə, işdə) və ya KİM olduğunu (həkim, tələbə) deyirik. Azərbaycanca belə cümlələrdə fel görünmür («Hazırsan?»), ona görə çoxları ingiliscə də feli atır və ya səhvən do işlədir. Yadda saxla: «necə?» sualına cavab verən sözlərlə (ready, tired, hungry, happy, late) do yox, am / is / are işlənir. Əksinə, iş bildirən fel sadə formadadırsa (work, live, go), onun yanına am / is / are qoyulmur; am / is / are + -ing forması ayrıca mövzudur (g03).",
  tbl:[["necə?","I am tired. Are you ready?"],["harada?","We are at home. Where is your office?"],["kim? nə?","He is a doctor. It is a big city."]],
  ex:[["Are you ready?","Hazırsan?"],["I'm hungry.","Acmışam."],["He is a driver.","O sürücüdür."],["My office is in the city centre.","Ofisim şəhər mərkəzindədir."]],
  no:"Do you ready? / I am work here. — səhvdir"},
 {h:"4. Yaş: I am 25 (have yox)",
  t:"Azərbaycanca «25 yaşım var» deyirik, ona görə çoxları ingiliscə have işlədir. İngiliscə isə yaş «sahib olmaq» kimi yox, «olmaq» kimi deyilir: «mən 25-əm». Ona görə yaşda həmişə am / is / are işlənir. Rəqəmdən sonra years old yazmaq da olar, yazmamaq da, amma tək years yazılmır. Yaşı soruşanda How old + am / is / are işlənir.",
  ex:[["I'm 25. / I'm 25 years old.","Mənim 25 yaşım var."],["My son is seven years old.","Oğlumun yeddi yaşı var."],["How old is your daughter?","Qızın neçə yaşındadır?"],["How old are you?","Neçə yaşın var?"]],
  no:"I have 25 years. / I am 25 years. / How old has your daughter? — səhvdir"},
 {h:"5. Keçmiş: was / were",
  t:"«İdim, idi, idik» demək üçün am / is / are keçmiş formaya keçir. am və is → was, are → were olur. Seçim qaydası eynidir: I və bir adam / bir əşya üçün was; we, you, they və çox şey üçün were. Dünən, keçən il, uşaq olanda kimi keçmiş vaxtlarda bu sözlər işlənir.",
  tbl:[["I / he / she / it, bir ad","was"],["we / you / they, iki və daha çox","were"]],
  ex:[["I was very tired yesterday.","Dünən çox yorğun idim."],["We were at home last night.","Dünən axşam evdə idik."],["The weather was nice yesterday.","Dünən hava gözəl idi."],["My grandparents were teachers.","Babamla nənəm müəllim idilər."]],
  no:"We was very tired. / I were at home. — səhvdir"},
 {h:"6. Sual: am / is / are qabağa keçir",
  t:"Azərbaycanca sualı çox vaxt səs tonu ilə veririk, sözlərin yeri dəyişmir. İngiliscə isə sözlərin yeri dəyişir: am / is / are (keçmişdə was / were) «kim»-dən əvvələ, cümlənin başına keçir. Burada do / does / did lazım deyil — heç bir söz əlavə olunmur. Sual sözü varsa (where, how old), o, ən əvvəldə durur, sonra is / are gəlir.",
  tbl:[["She is at home.","Is she at home?"],["They were at the meeting.","Were they at the meeting?"],["Your office is … .","Where is your office?"]],
  ex:[["Are you a student?","Tələbəsən?"],["Is she a doctor?","O həkimdir?"],["Were you at work yesterday?","Dünən işdə idin?"],["Where is your office?","Ofisin haradadır?"]],
  no:"Do you are a student? / Did you were at work? — səhvdir"},
 {h:"7. İnkar: am / is / are + not",
  t:"«Deyiləm, deyil, deyildi» demək üçün am / is / are / was / were sözündən dərhal sonra not yazılır. Danışıqda not qısalır: isn't, aren't, wasn't, weren't. am not isə qısalmır, onun yerinə I'm not deyilir. Burada da do / does / did işlənmir, çünki cümlədə artıq am / is / are var.",
  tbl:[["am not","I'm not"],["is not","isn't"],["are not","aren't"],["was not / were not","wasn't / weren't"]],
  ex:[["I'm not hungry.","Ac deyiləm."],["She isn't at home.","O evdə deyil."],["We aren't ready.","Hazır deyilik."],["My brother wasn't at home yesterday.","Qardaşım dünən evdə deyildi."]],
  no:"I amn't hungry. / We not ready. / She doesn't at home. — səhvdir"},
 {h:"8. have / has — «var» (sahiblik)",
  t:"Bir şeyin kiminsə olduğunu demək üçün have işlənir: «mənim maşınım var» = I have a car. Azərbaycanca «var» sözü sonda gəlir, ingiliscə have isə «kim»-dən dərhal sonra gəlir. he, she, it, bir ad və ya bir əşya ilə have yox, has işlənir. Keçmişdə hamı üçün eyni söz işlənir: had («var idi»).",
  tbl:[["I / you / we / they, iki və daha çox","have"],["he / she / it, bir ad, bir əşya","has"],["keçmiş, hamı","had"]],
  ex:[["I have two children.","İki uşağım var."],["Elvin has a big car.","Elvinin böyük maşını var."],["The hotel has a nice garden.","Otelin gözəl bağı var."],["We had a dog when I was a child.","Uşaq olanda itimiz var idi."]],
  no:"She have a car. / I has a car. — səhvdir"},
 {h:"9. Əsas qayda: do / does / did nə vaxt lazımdır?",
  t:"Bu, mövzunun ən vacib qaydasıdır. Cümlədə am / is / are / was / were VARSA, sual və inkar üçün başqa söz lazım deyil: onları qabağa keçiririk və ya not əlavə edirik. Cümlədə am / is / are / was / were YOXDURSA, sual və inkar üçün mütləq do / does / did lazımdır. Bu qayda istisnasız bütün fellərə aiddir — fel hansı olursa olsun (work, go, have…), am / is / are yoxdursa, do / does / did gəlir. Bir cümlədə ikisi birlikdə işlənmir: ya am / is / are, ya da do.",
  tbl:[["Cümlədə am / is / are / was / were var","do lazım deyil: Are you tired? She isn't here."],["Cümlədə am / is / are / was / were yoxdur","do / does / did lazımdır: Do you work? She doesn't work."]],
  ex:[["You are tired. → Are you tired?","Yorğunsan? (am/is/are var — do yoxdur)"],["You work here. → Do you work here?","Burada işləyirsən? (am/is/are yoxdur — do gəlir)"],["She is a student. → Is she a student?","O tələbədir?"],["She lives in Ganja. → Does she live in Ganja?","O Gəncədə yaşayır?"]],
  no:"Is she work in a bank? / Do you tired? / Are you live here? — səhvdir"},
 {h:"10. do, does, yoxsa did?",
  t:"Hansını seçəcəyin iki şeydən asılıdır: zamandan və «kim»-dən. İndiki zamanda I, you, we, they və çox adam ilə do (inkarı don't) işlənir. İndiki zamanda he, she, it və bir ad ilə does (inkarı doesn't) işlənir. Keçmişdə isə «kim» kim olursa olsun, hamı üçün did (inkarı didn't) işlənir.",
  tbl:[["indi: I / you / we / they, çox adam","do / don't"],["indi: he / she / it, bir ad","does / doesn't"],["keçmiş: hamı","did / didn't"]],
  ex:[["Do your parents live in Baku?","Valideynlərin Bakıda yaşayır?"],["Does she speak English?","O ingiliscə danışır?"],["I don't understand this word.","Bu sözü başa düşmürəm."],["They didn't come to the party last night.","Onlar dünən axşam məclisə gəlmədilər."]],
  no:"She don't like coffee. / Do she speak English? — səhvdir"},
 {h:"11. does / did gəldisə, əsas fel sadə qalır",
  t:"Təsdiq cümləsində he / she / it ilə feldə -s olur: she works, he lives. Keçmişdə fel keçmiş formaya keçir: went, saw, played. Sual və inkarda isə bu -s does sözünə, keçmiş forma da did sözünə «köçür». Ona görə əsas fel sadə formaya qayıdır: work, live, go, see. -s və keçmiş forma cümlədə iki dəfə yazılmır.",
  tbl:[["She works.","Does she work? / She doesn't work."],["He went.","Did he go? / He didn't go."],["He has a car.","Does he have a car? / He doesn't have a car."]],
  ex:[["He likes fish. → He doesn't like fish.","O balığı sevmir."],["Your brother has a car. → Does your brother have a car?","Qardaşının maşını var?"],["Nigar went to the party. → Nigar didn't go to the party.","Nigar məclisə getmədi."],["You saw the film. → Did you see the film?","Filmə baxdın?"]],
  no:"Does he works? / She doesn't likes / Did you went? — səhvdir"},
 {h:"12. have ilə sual və inkar",
  t:"have «var» mənasında adi feldir, am / is / are deyil. Ona görə 9-cu qayda burada da işləyir: sual və inkar do / does / did ilə qurulur. he / she / it ilə does gəldiyi üçün has sadə formaya qayıdır: does … have, doesn't have. Danışıqda (xüsusən Britaniyada) have got də işlənir: Have you got…? I haven't got… — bu formada do lazım deyil. İkisini qarışdırma: ya Do you have…?, ya da Have you got…?",
  tbl:[["do ilə","Do you have a pen? I don't have a bike."],["have got ilə","Have you got a pen? I haven't got a bike."]],
  ex:[["Do you have any questions? / Have you got any questions?","Sualın var?"],["He doesn't have a car.","Onun maşını yoxdur."],["Do your parents have a car?","Valideynlərinin maşını var?"],["We didn't have time yesterday.","Dünən vaxtımız yox idi."]],
  no:"He don't have a car. / Does she has a car? / Do you have got a pen? — səhvdir"},
 {h:"13. Sual sözü ilə sual: Where do you live?",
  t:"Sual sözü (where — harada, what time — saat neçədə, why — niyə, how old — neçə yaş) həmişə ən əvvəldə durur. Ondan sonra adi sualın sırası gəlir. Cümlədə am / is / are yoxdursa: sual sözü + do / does / did + kim + fel. am / is / are varsa: sual sözü + am / is / are + kim. Azərbaycanca «Harada yaşayırsan?» qısa görünür, amma ingiliscə sual sözündən sonra do / is atılmır.",
  tbl:[["sual sözü + do / does / did + kim + fel","Where do you work?"],["sual sözü + am / is / are + kim","Where is your office?"]],
  ex:[["Where do they work?","Onlar harada işləyirlər?"],["What time does the bank open?","Bank saat neçədə açılır?"],["Why did she leave early yesterday?","O dünən niyə tez getdi?"],["How old is your son?","Oğlun neçə yaşındadır?"]],
  no:"Where you live? / What time the shop opens? — səhvdir"},
 {h:"14. Qısa formalar: I'm, isn't, don't, didn't",
  t:"Danışıqda və adi yazıda iki söz birləşib qısalır, düşən hərfin yerinə apostrof (') qoyulur. Qısa və tam forma eyni mənanı verir, ikisi də düzdür. Tapşırıqda cavab yazanda hər ikisini işlədə bilərsən. Yalnız rəsmi yazıda (məsələn, IELTS essesində) tam forma yazılır.",
  tbl:[["I am / you are / he is / they are","I'm / you're / he's / they're"],["is not / are not","isn't / aren't"],["was not / were not","wasn't / weren't"],["do not / does not / did not","don't / doesn't / didn't"],["have not / has not","haven't / hasn't"]],
  ex:[["I'm not hungry. = I am not hungry.","Ac deyiləm."],["She doesn't eat meat.","O ət yemir."],["We weren't at home.","Biz evdə deyildik."],["They didn't come.","Onlar gəlmədilər."]],
  no:"Im not / dont / does'nt — səhvdir (apostrof düşən hərfin yerinə qoyulur)"}
],
g02: [
 {h:"1. Əsas sıra: kim + fel + nəyi",
  t:"İngilis cümləsinin əsas sırası belədir: əvvəl kim (işi görən, buna subyekt deyilir), sonra fel (nə edir), sonra nəyi (işin obyekti). Azərbaycanca fel adətən cümlənin sonunda olur: «Mən çay içirəm». İngiliscə isə fel ikinci yerdədir, «kim»-dən dərhal sonra gəlir. Azərbaycanca sözün rolunu şəkilçi göstərir («çayı», «kitabı»), ingiliscə şəkilçi yoxdur — rolu sözün YERİ göstərir. Ona görə bu sıranı dəyişmək olmaz.",
  tbl:[["kim (subyekt)","I / My mother / Kamran"],["fel (nə edir)","drink / reads / has"],["nəyi (obyekt)","tea / books / a new car"]],
  ex:[["I drink tea.","Mən çay içirəm."],["My mother reads books.","Anam kitab oxuyur."],["Kamran has a new car.","Kamranın yeni maşını var."],["My father opened the window.","Atam pəncərəni açdı."]],
  no:"I tea drink. / My mother books reads. — səhvdir"},
 {h:"2. «Kim» cümlədə mütləq yazılır",
  t:"Azərbaycanca «gəlirəm», «yorğunuq» deyəndə «mən», «biz» sözlərini atırıq, çünki şəkilçi (-əm, -uq) kimin olduğunu göstərir. İngilis felində belə şəkilçi yoxdur, ona görə «kim» sözü (I, we, she…) həmişə yazılmalıdır. Hava və vaxt haqqında danışanda «kim» olmasa belə, onun yerinə it qoyulur. «Kim»-siz ingilis cümləsi səhv sayılır.",
  ex:[["I'm coming.","Gəlirəm."],["We are tired.","Yorğunuq."],["It is cold today.","Bu gün soyuqdur."],["She works in a bank.","Bankda işləyir."]],
  no:"Am coming. / Is cold today. — səhvdir"},
 {h:"3. Fel ilə «nəyi» arasına söz girmir",
  t:"«Nəyi» (obyekt) feldən DƏRHAL sonra gəlir. Fel ilə obyektin arasına vaxt, yer və ya tezlik sözü qoymaq olmaz. Azərbaycanca «Hər gün anasına zəng edir» deyirik və «hər gün» ortada durur. İngiliscə isə əvvəl fel və obyekt birlikdə gəlir (calls his mother), every day isə onlardan sonra. Bu, ingilis dilinin çox ciddi qaydasıdır.",
  ex:[["He calls his mother every day.","O hər gün anasına zəng edir."],["I study English every day.","Hər gün ingiliscə oxuyuram."],["She speaks English very well.","O ingiliscə çox yaxşı danışır."],["We watch films at home.","Evdə film izləyirik."]],
  no:"He calls every day his mother. / She speaks very well English. — səhvdir"},
 {h:"4. Cümlənin sonu: əvvəl yer, sonra vaxt",
  t:"Cümlədə «harada» və «nə vaxt» varsa, ikisi də adətən «nəyi»-dən sonra, cümlənin sonunda gəlir. Onların öz sırası var: əvvəl yer (harada?), sonra vaxt (nə vaxt?). Azərbaycanca çox vaxt əksinədir: «dünən stansiyada» — əvvəl vaxt, sonra yer. Ona görə ingiliscə yazanda bu sıranı yadda saxla: kim → fel → nəyi → harada → nə vaxt.",
  tbl:[["kim + fel","She bought"],["nəyi","a laptop"],["harada","in the city centre"],["nə vaxt","last week"]],
  ex:[["She bought a laptop in the city centre last week.","Keçən həftə şəhər mərkəzində noutbuk aldı."],["They met at the station last week.","Keçən həftə stansiyada görüşdülər."],["I was at home yesterday.","Dünən evdə idim."],["We watched a film at home last night.","Dünən axşam evdə film izlədik."]],
  no:"We watched last night at home a film. — səhvdir"},
 {h:"5. Vaxt sözü cümlənin əvvəlinə keçə bilər",
  t:"Vaxtı (yesterday, last week, every morning) vurğulamaq istəsən, onu cümlənin ən əvvəlinə, «kim»-dən qabağa qoya bilərsən. Bundan sonra qalan sıra dəyişmir: kim → fel → nəyi → harada. Amma vaxt sözü «kim» ilə felin arasına və ya fel ilə «nəyi»-nin arasına girə bilməz. Deməli, vaxt üçün iki yer var: ya ən əvvəl, ya da ən sonda.",
  ex:[["Yesterday I saw Leyla in the park.","Dünən parkda Leylanı gördüm."],["I saw Leyla in the park yesterday.","Dünən parkda Leylanı gördüm."],["Every morning my father goes to work.","Atam hər səhər işə gedir."],["Last week they met at the station.","Keçən həftə stansiyada görüşdülər."]],
  no:"I yesterday saw Leyla. / I saw yesterday Leyla. — səhvdir"},
 {h:"6. always, usually, often — əsas feldən əvvəl",
  t:"always (həmişə), usually (adətən), often (tez-tez), sometimes (bəzən), never (heç vaxt) bir işi nə qədər tez-tez etdiyini göstərir. Bu sözlərə tezlik sözləri deyilir. Onlar adətən cümlənin sonuna yox, ortasına gəlir: «kim» ilə iş bildirən felin arasına. Azərbaycanca da «Mən adətən piyada gedirəm» deyirik, yəni sıra demək olar ki eynidir. never özü inkardır, ona görə onunla don't / doesn't işlənmir.",
  tbl:[["always","həmişə (100%)"],["usually","adətən"],["often","tez-tez"],["sometimes","bəzən"],["never","heç vaxt (0%)"]],
  ex:[["I usually walk to work.","Adətən işə piyada gedirəm."],["She often visits her grandmother.","O tez-tez nənəsinə baş çəkir."],["He always gets up early.","O həmişə tez durur."],["I never drink coffee.","Heç vaxt qəhvə içmirəm."]],
  no:"I go always to work. / I don't never drink coffee. — səhvdir"},
 {h:"7. am / is / are / was / were varsa — tezlik sözü onlardan SONRA",
  t:"Cümlədə iş bildirən fel yoxdursa və am / is / are / was / were varsa, tezlik sözü onlardan SONRA gəlir. Sıra belədir: kim → am / is / are → always → qalanı. Bu, 6-cı qaydanın yeganə fərqli halıdır və çox səhv edilir. Yadda saxlamaq üçün: «iş felindən ƏVVƏL, am / is / are-dən SONRA».",
  tbl:[["iş feli var","She always goes … (always + fel)"],["am / is / are var","She is always … (is + always)"]],
  ex:[["She is always late.","O həmişə gecikir."],["They are usually busy on Mondays.","Bazar ertələri onlar adətən məşğul olurlar."],["I'm never hungry in the morning.","Səhərlər heç vaxt ac olmuram."],["My father is always tired.","Atam həmişə yorğun olur."]],
  no:"She always is late. / I never am hungry. — səhvdir"},
 {h:"8. Köməkçi söz varsa: don't usually, Do you often…?",
  t:"Cümlədə köməkçi söz (do, does, did, can) varsa, tezlik sözü köməkçi ilə əsas felin ARASINA gəlir. İnkarda: I don't usually… Sualda: Do you often…? Sual sözü ilə: What do you usually do…? Tezlik sözü yenə də əsas feldən dərhal əvvəl durur, sadəcə qabağında köməkçi olur.",
  ex:[["I don't usually eat breakfast.","Adətən səhər yeməyi yemirəm."],["Do you often go to the cinema?","Tez-tez kinoya gedirsən?"],["What do you usually do at the weekend?","Həftəsonu adətən nə edirsən?"],["I can never remember his name.","Onun adını heç vaxt yadda saxlaya bilmirəm."]],
  no:"Do often you go to the cinema? — səhvdir"},
 {h:"9. every day, twice a week — cümlənin sonunda",
  t:"Bir neçə sözdən ibarət vaxt və tezlik ifadələri — every day (hər gün), twice a week (həftədə iki dəfə), three times a week, on Sundays (bazar günləri) — ortaya, feldən əvvələ girmir. Onlar cümlənin SONUNDA, vurğu üçün isə ən əvvəlində gəlir. Bu, tək sözlərdən (always, usually) fərqlidir: tək söz ortaya gəlir, uzun ifadə kənara. Cümlədə yer də varsa, yenə əvvəl yer, sonra bu ifadə gəlir.",
  tbl:[["tək söz: always, usually, often, sometimes, never","ortada, feldən əvvəl"],["ifadə: every day, twice a week, on Sundays","sonda (və ya ən əvvəldə)"]],
  ex:[["I go to the gym twice a week.","Həftədə iki dəfə idman zalına gedirəm."],["I cook three times a week.","Həftədə üç dəfə yemək bişirirəm."],["We go to the park on Sundays.","Bazar günləri parka gedirik."],["Every morning I drink tea.","Hər səhər çay içirəm."]],
  no:"I twice a week go to the gym. / She every day goes to work. — səhvdir"},
 {h:"10. Sual: do / does / did «kim»-dən əvvəl",
  t:"Sualda sıra dəyişir: köməkçi söz (do, does, did) «kim»-dən əvvələ keçir, əsas fel isə «kim»-dən sonra qalır. Sual sözü (where, what time, why) varsa, o, hamıdan əvvəl gəlir. Əsas fel heç vaxt «kim»-dən əvvələ keçmir, «nəyi» də yenə feldən sonra qalır. Sıranı yadda saxla: sual sözü → do / does / did → kim → fel → qalanı.",
  tbl:[["sual sözü","Where / What time"],["do / does / did","does"],["kim","your sister / the bus"],["fel + qalanı","work? / leave?"]],
  ex:[["Do you like music?","Musiqini sevirsən?"],["Where does your sister work?","Bacın harada işləyir?"],["What time does the bus leave?","Avtobus saat neçədə yola düşür?"],["What did you buy yesterday?","Dünən nə aldın?"]],
  no:"Where you work? / Where does work your sister? / Do you music like? — səhvdir"},
 {h:"11. Sual: am / is / are «kim»-dən əvvəl",
  t:"Cümlədə am / is / are (was / were) varsa, sualda do işlənmir — am / is / are özü «kim»-dən əvvələ keçir. -ing ilə cümlələrdə də (you are doing) eyni qayda işləyir: are qabağa keçir. Sual sözü varsa, yenə ən əvvəldə durur. Ən çox edilən səhv sual sözündən sonra adi cümlənin sırasını saxlamaqdır.",
  ex:[["Is she at home?","O evdədir?"],["What are you doing?","Nə edirsən?"],["Where is the station?","Stansiya haradadır?"],["Why were you late?","Niyə gecikdin?"]],
  no:"What you are doing? / Where the station is? — səhvdir"},
 {h:"12. İki obyekt: give me the book = give the book to me",
  t:"Bəzi fellərdən sonra iki şey gəlir: kimə və nəyi. Bu, «vermək, göndərmək, göstərmək, gətirmək» mənalı fellərdə olur: give, send, show, bring. Belə cümlədə iki sıra mümkündür. Birinci yol: kimə + nəyi — burada to yazılmır. İkinci yol: nəyi + to + kimə — to yalnız «kimə» sonda olanda gəlir.",
  tbl:[["kimə + nəyi","Give me the book."],["nəyi + to + kimə","Give the book to me."]],
  ex:[["Give me the keys, please.","Açarları mənə ver, zəhmət olmasa."],["I sent my brother a message. = I sent a message to my brother.","Qardaşıma mesaj göndərdim."],["She showed us her photos. = She showed her photos to us.","O bizə şəkillərini göstərdi."],["He gave his wife some flowers.","O həyat yoldaşına gül verdi."]],
  no:"Give to me the book. / Give the book me. — səhvdir"},
 {h:"13. Sifət isimdən əvvəl gəlir və cəm olmur",
  t:"Sifət «necə?» sualına cavab verən sözdür: new, red, careful, big. İsimlə birlikdə gələndə sifət həmişə isimdən QABAQ durur — Azərbaycanca da belədir: «yeni maşın» = a new car. a / an, the, my varsa, sifət onlarla isim arasına girir: a red car, my new phone. İsim cəm olanda sifət dəyişmir, -s almır: two new cars. Sifət am / is / are-dən sonra da gələ bilər: The car is red.",
  ex:[["She has a red car.","Onun qırmızı maşını var."],["He is a careful driver.","O ehtiyatlı sürücüdür."],["She bought two new chairs.","O iki yeni stul aldı."],["My new phone is very good.","Yeni telefonum çox yaxşıdır."]],
  no:"a car red / a driver careful / two news chairs — səhvdir"}
],
g03: [
 {h:"1. İki «indiki zaman» var",
  t:"Azərbaycanca «işləyirəm» həm «hər gün işləyirəm», həm də «indi işləyirəm» deməkdir. İngiliscə bunlar iki ayrı formadır. Adətən, həmişə olan iş üçün Present Simple, indi gedən iş üçün Present Continuous işlənir.",
  tbl:[["Present Simple","I work — adətən, hər gün"],["Present Continuous","I am working — indi, bu anda"]],
  ex:[["I work in a bank.","Bankda işləyirəm (bu mənim işimdir)."],["I am working now.","İndi işləyirəm (bu anda)."]]},
 {h:"2. Present Simple — vərdiş və fakt",
  t:"Present Simple üç halda işlənir. Birincisi, təkrarlanan iş və vərdiş: hər gün, hər həftə, adətən etdiyin şey. İkincisi, uzun müddət dəyişməyən vəziyyət: harada yaşayırsan, harada işləyirsən. Üçüncüsü, həmişə doğru olan fakt. Forma sadədir: fel lüğətdəki kimi qalır, yalnız he / she / it ilə -s artırılır (3-cü qayda).",
  ex:[["I drink tea every morning.","Hər səhər çay içirəm."],["They live in Sumgait.","Onlar Sumqayıtda yaşayırlar."],["Water boils at 100 degrees.","Su 100 dərəcədə qaynayır."]]},
 {h:"3. he / she / it — feldə -s",
  t:"Bir nəfər və ya bir əşya haqqında danışanda (o, bu) feldə -s olur. s, sh, ch, x, o ilə bitən fellərə -es artırılır. Samit + y ilə bitəndə y → ies olur. have → has.",
  tbl:[["work","works"],["go / watch / fix","goes / watches / fixes"],["study","studies"],["have","has"]],
  ex:[["She works in a hospital.","O xəstəxanada işləyir."],["He watches the news every evening.","O hər axşam xəbərlərə baxır."]],
  no:"She work / He gos — səhvdir"},
 {h:"4. Present Simple-də sual və inkar",
  t:"Bu, g01-dəki əsas qaydadır: cümlədə am / is / are yoxdursa, bütün fellərdə sual və inkar do / does ilə qurulur. I, you, we, they ilə do / don't, he, she, it ilə does / doesn't işlənir. does gələndə -s ona keçir, əsas feldən isə düşür. Sual sözü varsa, ən əvvəldə durur: sual sözü + do / does + kim + fel.",
  tbl:[["I / you / we / they","Do you work? I don't work."],["he / she / it","Does she work? She doesn't work."]],
  ex:[["Do you speak Russian?","Rusca danışırsan?"],["She doesn't eat meat.","O ət yemir."],["What time does the bank open?","Bank saat neçədə açılır?"]],
  no:"She doesn't eats — səhvdir"},
 {h:"5. Present Continuous — indi, bu anda",
  t:"Present Continuous danışdığın anda gedən və hələ bitməmiş iş üçün işlənir. Forma iki hissədən ibarətdir: am / is / are + fel + -ing. am / is / are «kim»-ə görə seçilir (g01) və atılmır. Azərbaycanca «edirəm, gedir» formasına uyğundur, amma ingiliscə bu forma yalnız «indi» mənasında işlənir.",
  tbl:[["I","am working"],["he / she / it","is working"],["we / you / they","are working"]],
  ex:[["Look! It is raining.","Bax! Yağış yağır."],["She is talking on the phone.","O telefonla danışır."]]},
 {h:"6. -ing necə yazılır",
  t:"Çox vaxt felə sadəcə -ing artırılır. Fel səssiz e ilə bitirsə (make, write), e düşür. Bir hecalı fel «samit + sait + samit» ilə bitirsə (sit, swim, run), son hərf ikiləşir. ie ilə bitən fellərdə ie → y olur: lie → lying. Bu qaydalar yalnız yazıya aiddir, oxunuş dəyişmir.",
  tbl:[["read","reading"],["make / write","making / writing"],["sit / swim / run","sitting / swimming / running"],["lie / die","lying / dying"]],
  ex:[["He is writing a letter.","O məktub yazır."],["The children are swimming.","Uşaqlar üzürlər."]]},
 {h:"7. Present Continuous-da sual və inkar — do yoxdur",
  t:"Present Continuous cümləsində artıq am / is / are var. g01-dəki qaydaya görə, am / is / are varsa, do / does lazım deyil. Sualda am / is / are «kim»-dən əvvələ keçir, inkarda ondan sonra not gəlir. Fel -ing formasında yerində qalır.",
  ex:[["Are you listening?","Qulaq asırsan?"],["He isn't working today.","O bu gün işləmir."],["What are you doing?","Nə edirsən?"]],
  no:"Do you working? / What do you doing? — səhvdir"},
 {h:"8. Continuous — «bu günlərdə», müvəqqəti",
  t:"Continuous yalnız «tam bu saniyə» üçün deyil. İş danışdığın anda getməsə də, bu günlərdə, bu həftə, bu il davam edirsə və müvəqqətidirsə, yenə Continuous işlənir. Müqayisə et: «Bankda işləyirəm» daimi işdir — Present Simple; «Bu həftə evdən işləyirəm» müvəqqətidir — Continuous. Bu halın siqnal sözləri: these days, this week, this month, at the moment.",
  ex:[["I'm reading a very good book these days.","Bu günlərdə çox yaxşı kitab oxuyuram."],["We are working from home this week.","Bu həftə evdən işləyirik."],["My brother is looking for a new job.","Qardaşım yeni iş axtarır (bu günlərdə)."]]},
 {h:"9. Hansını seçim? Siqnal sözlər",
  t:"Hansı formanı seçəcəyini bilmək üçün cümlədəki vaxt sözlərinə bax. «Nə qədər tez-tez?» sualına cavab verən sözlər (always, usually, every day) Present Simple istəyir. «İndi» mənalı sözlər (now, at the moment, today, Look!, Listen!) Present Continuous istəyir. Vaxt sözü olmasa da qayda eynidir: vərdiş və fakt — Simple, indi gedən iş — Continuous.",
  tbl:[["always, usually, often, never, every day, on Mondays","Present Simple"],["now, right now, at the moment, today, this week, Look!, Listen!","Present Continuous"]],
  ex:[["I usually walk to work, but today I'm taking a taxi.","Adətən işə piyada gedirəm, amma bu gün taksiyə minirəm."],["She usually drinks tea, but now she's drinking coffee.","O adətən çay içir, amma indi qəhvə içir."],["Listen! Somebody is singing.","Qulaq as! Kimsə oxuyur."]]},
 {h:"10. «Hal» bildirən fellər -ing almır",
  t:"Bəzi fellər iş-hərəkət yox, fikir, hiss, istək və ya sahiblik bildirir. Belə fellər «indi» mənasında da -ing almır, Present Simple-də qalır. Bu fellər bunlardır: know, understand, believe, remember, mean, like, love, hate, prefer, want, need, belong, seem. Azərbaycanca «bilirəm», «istəyirəm» deyirik və «indi» mənası var, amma ingiliscə yenə I know, I want deyilir.",
  ex:[["I know the answer.","Cavabı bilirəm."],["Do you understand me?","Məni başa düşürsən?"],["She wants a new phone.","O yeni telefon istəyir."]],
  no:"I am knowing / She is wanting — səhvdir"},
 {h:"11. have: «sahibəm» və «edirəm»",
  t:"have iki mənada işlənir. «Sahib olmaq, var» mənasında have -ing almır: indi olsa da, Present Simple qalır. Amma have yemək, içmək, duş, istirahət mənasında (have breakfast, have a shower, have lunch, have a good time) «etmək» deməkdir. Bu mənada have adi iş feli kimidir və -ing ala bilər.",
  ex:[["She has two children.","Onun iki uşağı var."],["He's having breakfast now.","O indi səhər yeməyi yeyir."],["We're having a great time here.","Burada çox gözəl vaxt keçiririk."]],
  no:"She is having two children — səhvdir"},
 {h:"12. Sual: How often…? — nə qədər tez-tez",
  t:"Bir işi nə qədər tez-tez etdiyini soruşmaq üçün How often işlənir. Ondan sonra adi Present Simple sualı gəlir: How often + do / does + kim + fel. Cavabda tezlik sözü (always, usually, never) və ya ifadə (every day, twice a week) gəlir. once = bir dəfə, twice = iki dəfə, üç və daha çox üçün three times, four times deyilir.",
  ex:[["How often do you go to the gym?","Nə qədər tez-tez idman zalına gedirsən?"],["Twice a week.","Həftədə iki dəfə."],["How often does she call you? — Once a week.","O sənə nə qədər tez-tez zəng edir? — Həftədə bir dəfə."]]}
],
g20: [
 {h:"1. I, you, he, she, it, we, they — işi görən",
  t:"I, you, he, she, it, we, they işi görən adamı (kim?) göstərir. Bu sözlər adətən cümlənin əvvəlində, feldən qabaq durur. Azərbaycanca «o» bir sözdür, ingiliscə isə üç cürdür: kişi üçün he, qadın üçün she, əşya və heyvan üçün it. Özünü başqası ilə birlikdə deyəndə özünü sona qoyursan və I yazırsan: my brother and I.",
  ex:[["She works in Baku.","O Bakıda işləyir."],["My brother and I play football.","Qardaşım və mən futbol oynayırıq."],["I have a cat. It is very small.","Pişiyim var. O çox balacadır."]],
  no:"Me and my brother play — səhvdir"},
 {h:"2. me, him, her, us, them — «məni, mənə»",
  t:"Feldən sonra və ön sözdən (to, with, for, at) sonra I, he, she formaları işlənmir, başqa forma gəlir: me, him, her, us, them. Bu, Azərbaycanca «məni, mənə, onu, ona» kimidir — yəni işin yönəldiyi adam. you və it hər iki yerdə eyni qalır. Ən çox edilən səhv ön sözdən sonra I və ya he yazmaqdır.",
  tbl:[["I","me"],["he","him"],["she","her"],["it","it"],["we","us"],["you","you"],["they","them"]],
  ex:[["Call me tonight.","Bu axşam mənə zəng et."],["I love them.","Mən onları sevirəm."],["Come with us.","Bizimlə gəl."]],
  no:"Give it to I — səhvdir"},
 {h:"3. my, your, his, her, its, our, their — «mənim…»",
  t:"Bu sözlər bir şeyin kimin olduğunu göstərir. Azərbaycanca bunu şəkilçi ilə deyirik: maşınım, evimiz. İngiliscə isə ayrıca söz isimdən ƏVVƏL gəlir, ismin özünə heç nə artırılmır. Bu sözlərdən sonra mütləq isim gəlməlidir.",
  tbl:[["I","my"],["you","your"],["he","his"],["she","her"],["it","its"],["we","our"],["they","their"]],
  ex:[["This is my car.","Bu mənim maşınımdır."],["Their house is big.","Onların evi böyükdür."],["Our teacher is very kind.","Müəllimimiz çox mehribandır."]]},
 {h:"4. his yoxsa her? — «onun» iki cürdür",
  t:"Azərbaycanca «onun» bir sözdür. İngiliscə kişi haqqında his, qadın haqqında her, əşya və heyvan haqqında its deyilir. Seçim sahibin kim olduğundan asılıdır, əşyadan yox.",
  ex:[["Rashad loves his wife.","Rəşad həyat yoldaşını sevir."],["Aysel loves her husband.","Aysel ərini sevir."],["The city is famous for its parks.","Şəhər parkları ilə məşhurdur."]],
  no:"She loves his husband — səhvdir"},
 {h:"5. mine, yours, his, hers, ours, theirs — «mənimki»",
  t:"mine, yours, hers, ours, theirs «mənimki, səninki, onunku» deməkdir. Onlardan sonra isim gəlmir, çünki isim artıq bəllidir və təkrar olunmur. my + isim ilə mine eyni məlumatı verir, sadəcə mine-dan sonra isim yazılmır. his isə hər iki yerdə eyni qalır.",
  tbl:[["my","mine"],["your","yours"],["his","his"],["her","hers"],["our","ours"],["their","theirs"]],
  ex:[["This bag is mine.","Bu çanta mənimkidir."],["Is this pen yours?","Bu qələm səninkidir?"],["Their flat is bigger than ours.","Onların mənzili bizimkindən böyükdür."]],
  no:"Is this your? — səhvdir"},
 {h:"6. Whose? — «kimin?»",
  t:"Bir şeyin kimin olduğunu soruşanda Whose işlənir. Whose-dan sonra isim gələ də bilər, gəlməyə də. Cavabda mine, yours kimi sözlər və ya ad + 's gəlir. Who's (= who is) ilə qarışdırma: səsi eynidir, mənası başqadır.",
  ex:[["Whose phone is this? — It's Leyla's.","Bu kimin telefonudur? — Leylanındır."],["Whose are these keys?","Bu açarlar kimindir?"],["Whose car is that? — It's mine.","O kimin maşınıdır? — Mənimkidir."]]},
 {h:"7. -'s — «Əlinin, qardaşımın»",
  t:"İnsan və heyvan haqqında «Əlinin, qardaşımın» demək üçün ada 's artırılır. Bu, Azərbaycancadakı «-ın, -in» kimidir: sahib birinci, əşya sonra gəlir. -s ilə bitən cəm sözdə yalnız apostrof qoyulur: parents'. -s ilə bitməyən cəmdə yenə 's yazılır: children's.",
  ex:[["This is Ali's car.","Bu Əlinin maşınıdır."],["My parents' house is in Shaki.","Valideynlərimin evi Şəkidədir."],["The children's room is upstairs.","Uşaqların otağı yuxarıdadır."]],
  no:"the car of Ali — səhvdir"},
 {h:"8. its və it's — qarışdırma",
  t:"its və it's eyni səslənir, amma mənaları tam fərqlidir. its «onun» deməkdir və əşyaya və ya heyvana aid olanı göstərir — burada apostrof yoxdur. it's isə it is (və ya it has) sözlərinin qısa formasıdır. Yoxlamaq üçün yerinə it is qoy: məna düzgündürsə, it's yaz.",
  ex:[["The dog is eating its food.","İt yeməyini yeyir."],["It's very cold today.","Bu gün çox soyuqdur."]]},
 {h:"9. myself, yourself… — «özüm, özün»",
  t:"İşi görən adam işi özünə edirsə, myself, yourself kimi sözlər işlənir — Azərbaycanca «özümü, özünü». Bu sözlər həm də «başqası yox, məhz özüm etdim» mənasını vurğulayır. by myself isə «tək, kimsənin köməyi olmadan» deməkdir. Cəmdə sonluq -selves olur: ourselves, themselves.",
  tbl:[["I","myself"],["you","yourself"],["he / she / it","himself / herself / itself"],["we","ourselves"],["they","themselves"]],
  ex:[["He cut himself.","O özünü kəsdi."],["I made this cake myself.","Bu tortu özüm bişirdim."],["She lives by herself.","O tək yaşayır."]]},
 {h:"10. this, that, these, those",
  t:"Yaxında olan şey üçün this (tək) və these (çox) işlənir. Uzaqda olan şey üçün that (tək) və those (çox) işlənir. Bu sözlər isimlə birlikdə də, təkbaşına da işlənə bilər. Çox şey haqqında danışanda isim cəm olur və this / that da dəyişir: these, those.",
  tbl:[["yaxın, tək","this book"],["yaxın, çox","these books"],["uzaq, tək","that car"],["uzaq, çox","those cars"]],
  ex:[["This coffee is hot.","Bu qəhvə istidir."],["Look at those birds!","O quşlara bax!"],["What's that?","O nədir?"]],
  no:"these book — səhvdir"},
 {h:"11. one / ones — sözü təkrar etməmək üçün",
  t:"Eyni ismi ikinci dəfə təkrar etməmək üçün onun yerinə one qoyulur. İsim təkdirsə one, cəmdirsə ones işlənir. one adətən sifətdən və ya the, this, which sözlərindən sonra gəlir. Azərbaycanca bunu «mavisi, yenisi» kimi şəkilçi ilə deyirik.",
  ex:[["I don't like this shirt. I like the blue one.","Bu köynəyi bəyənmirəm. Mavini bəyənirəm."],["These shoes are old. I need new ones.","Bu ayaqqabılar köhnədir. Yenisi lazımdır."],["Which one do you want?","Hansını istəyirsən?"]]}
],
g04: [
 {h:"1. Past Simple — keçmişdə bitmiş iş",
  t:"Past Simple keçmişdə olub BİTMİŞ iş üçün işlənir. Çox vaxt nə vaxt olduğu da deyilir: yesterday, last week, in 2019, two days ago. Azərbaycanca «etdim, getdi, gördük» kimi. Hekayə danışanda hadisələr bir-birinin ardınca Past Simple ilə deyilir.",
  ex:[["I visited my grandmother yesterday.","Dünən nənəmə baş çəkdim."],["We moved to Baku in 2018.","2018-ci ildə Bakıya köçdük."],["I lost my phone two days ago.","İki gün əvvəl telefonumu itirdim."]]},
 {h:"2. Qaydalı fellər: -ed",
  t:"Qaydalı fellərin keçmiş forması -ed ilə düzəlir. Fel e ilə bitirsə, yalnız -d artırılır. Samit + y ilə bitirsə, y → ied olur, amma sait + y olanda (play) sadəcə -ed artırılır. Bir hecalı fel «samit + sait + samit» ilə bitirsə, son hərf ikiləşir: stop → stopped.",
  tbl:[["work","worked"],["live","lived"],["study","studied"],["stop","stopped"],["play","played"]],
  ex:[["She worked late last night.","Dünən gecə gec saata qədər işlədi."],["The bus stopped near my house.","Avtobus evimin yanında dayandı."]]},
 {h:"3. Qaydasız fellər — əzbərlə",
  t:"Bəzi fellər keçmişdə -ed almır, tamam başqa forma alır. Bunlara qaydasız fellər deyilir. Onların ümumi qaydası yoxdur, ona görə hər birini ayrıca əzbərləmək lazımdır. Tam siyahı Murphy kitabının sonundadır (Appendix 2), cədvəldə isə ən çox işlənənlər var.",
  tbl:[["go → went","see → saw"],["buy → bought","think → thought"],["have → had","get → got"],["do → did","make → made"],["come → came","take → took"],["eat → ate","write → wrote"],["say → said","tell → told"],["leave → left","meet → met"],["lose → lost","know → knew"]],
  ex:[["I went to the market.","Bazara getdim."],["She bought a new dress.","O yeni don aldı."]],
  no:"goed / buyed — səhvdir"},
 {h:"4. Bütün şəxslər üçün eyni forma",
  t:"İndiki zamanda he / she / it ilə feldə -s olur, keçmişdə isə olmur. Past Simple-də forma hamı üçün eynidir: I, you, he, she, we, they — hamısı eyni sözü işlədir. Yalnız be fərqlidir: was / were (g01). Bu, keçmiş zamanı asanlaşdırır.",
  ex:[["I went. She went. They went.","Mən getdim. O getdi. Onlar getdi."],["He worked late yesterday.","O dünən gec saata qədər işlədi."],["My parents lived in Ganja.","Valideynlərim Gəncədə yaşayırdı."]],
  no:"She wents / He liveds — səhvdir"},
 {h:"5. Sual və inkar: did / didn't + sadə fel",
  t:"g01-dəki qayda keçmişdə də işləyir: cümlədə was / were yoxdursa, bütün fellərdə sual və inkar did / didn't ilə qurulur. did hamı üçün eynidir. did artıq keçmişi göstərdiyi üçün əsas fel sadə formaya qayıdır: went → go, saw → see. Sual sözü varsa, ən əvvəldə gəlir: Where did you…?",
  ex:[["Did you see the match?","Oyuna baxdın?"],["I didn't sleep well.","Yaxşı yatmadım."],["Where did you buy it?","Onu haradan aldın?"]],
  no:"Did you saw / I didn't slept — səhvdir"},
 {h:"6. was / were ilə cümlələr — did yoxdur",
  t:"Cümlədə was / were varsa, did işlənmir. Sualda was / were «kim»-dən əvvələ keçir. İnkarda ondan sonra not gəlir: wasn't, weren't. Bir cümlədə was və did birlikdə olmur.",
  ex:[["Were you at home?","Evdə idin?"],["It wasn't expensive.","Baha deyildi."],["Where were you last night?","Dünən axşam harada idin?"]],
  no:"Did you were at home? — səhvdir"},
 {h:"7. Past Continuous — «edirdim»",
  t:"Past Continuous keçmişdə müəyyən bir anda davam edən, hələ bitməmiş işi göstərir. Forma: was / were + fel + -ing. was / were «kim»-ə görə seçilir (g01). Azərbaycanca bu «edirdim, gedirdik» formasıdır. Çox vaxt dəqiq vaxtla gəlir: at 9 o'clock, at this time yesterday.",
  tbl:[["I / he / she / it","was working"],["we / you / they","were working"]],
  ex:[["At 9 o'clock I was having dinner.","Saat 9-da şam edirdim."],["What were you doing yesterday at 5?","Dünən saat 5-də nə edirdin?"]]},
 {h:"8. Uzun iş + qısa hadisə: when",
  t:"Keçmişdə bir iş uzun müddət gedirdi (Past Continuous), onun ortasında qısa bir hadisə baş verdi (Past Simple). Qısa hadisə çox vaxt when ilə gəlir. Azərbaycanca: «Sən zəng edəndə (qısa) maşın sürürdüm (uzun)». when hissəsi cümlənin əvvəlində də, sonunda da ola bilər; əvvəldədirsə, ondan sonra vergül qoyulur.",
  ex:[["I was driving when you called.","Sən zəng edəndə maşın sürürdüm."],["When the teacher came in, we were talking.","Müəllim girəndə biz danışırdıq."],["It was raining when we left the house.","Evdən çıxanda yağış yağırdı."]]},
 {h:"9. while — «…-arkən»",
  t:"while «…-arkən, … ərzində» deməkdir və uzun davam edən işi göstərir. Ona görə while-dan sonra çox vaxt Past Continuous gəlir. Qısa hadisə isə Past Simple-də qalır. İki uzun iş eyni vaxtda gedirdisə, ikisi də Continuous ola bilər.",
  ex:[["While I was cooking, the lights went out.","Mən yemək bişirərkən işıqlar söndü."],["Somebody stole my bag while I was sleeping.","Mən yatarkən kimsə çantamı oğurladı."],["While I was cooking, my wife was watching TV.","Mən yemək bişirərkən həyat yoldaşım televizora baxırdı."]]},
 {h:"10. İki qısa hadisə ardıcıl — ikisi də Simple",
  t:"Hadisələr bir-birinin ardınca olubsa — biri bitdi, sonra o biri başladı — hər ikisi Past Simple olur. Continuous yalnız bir iş başqa hadisə zamanı artıq DAVAM edirdisə işlənir. Eyni cümlədə forma dəyişəndə məna da dəyişir, aşağıdakı cədvələ bax.",
  tbl:[["When I arrived, they were having dinner.","Mən gələndə onlar artıq şam edirdilər."],["When I arrived, they had dinner.","Mən gəldim, sonra onlar şam etdilər."]],
  ex:[["When I saw the fire, I called the police.","Yanğını görəndə polisə zəng etdim."],["She opened the door and went out.","O qapını açıb çıxdı."]]},
 {h:"11. used to — «əvvəllər edərdim, indi yox»",
  t:"used to keçmişdə vərdiş olan, amma indi olmayan işi göstərir: «əvvəllər edərdim, indi etmirəm». Forma: used to + sadə fel, hamı üçün eyni. Sual və inkarda did gəlir, ona görə used sözündən d düşür: did … use to, didn't use to. İndiki vərdiş üçün used to işlənmir, onun yerinə usually + Present Simple deyilir.",
  ex:[["I used to smoke, but I stopped.","Əvvəllər siqaret çəkirdim, amma atdım."],["Did you use to play football?","Əvvəllər futbol oynayırdın?"],["We didn't use to have a car.","Əvvəllər maşınımız yox idi."]],
  no:"I use to smoke (təsdiqdə) — səhvdir"},
 {h:"12. «Hal» felləri keçmişdə də -ing almır",
  t:"g03-dəki «hal» felləri siyahısı (know, understand, believe, remember, mean, like, love, hate, prefer, want, need, belong, seem) keçmişdə də eyni qaydaya tabedir. Bu fellər «o anda» mənasında da was / were + -ing almır. Azərbaycanca «bilmirdim», «istəyirdi» deyirik və Continuous kimi səslənir, amma ingiliscə Past Simple işlənir: didn't know, wanted.",
  ex:[["I didn't know the answer.","Cavabı bilmirdim."],["She wanted a new car.","O yeni maşın istəyirdi."],["I didn't understand what he meant.","Onun nə demək istədiyini başa düşmədim."]],
  no:"I was knowing — səhvdir"}
],
g23: [
 {h:"1. Əmr: fel cümlənin əvvəlində",
  t:"Kiməsə nəsə etməsini deyəndə — əmr, təlimat, məsləhət — fel sadə formada cümlənin ən əvvəlinə gəlir. you yazılmır, çünki kimə dediyin onsuz da bəllidir. Bu forma hamı üçün eynidir: bir nəfərə də, çox adama da. Azərbaycanca isə «otur» və «oturun» fərqlidir.",
  ex:[["Sit down.","Otur. / Oturun."],["Open the window, please.","Pəncərəni aç, zəhmət olmasa."],["Be careful!","Ehtiyatlı ol!"]]},
 {h:"2. Qadağa: Don't + fel",
  t:"«Etmə, etməyin» demək üçün felin əvvəlinə Don't qoyulur: Don't + sadə fel. Bu forma da hamı üçün eynidir. Arada to olmur, not da tək işlənmir. Hətta be ilə də Don't işlənir: Don't be late.",
  ex:[["Don't touch it!","Ona toxunma!"],["Don't be late.","Gecikmə."],["Don't worry.","Narahat olma."]],
  no:"Not touch / Don't to touch — səhvdir"},
 {h:"3. please — nəzakət",
  t:"Əmr forması ingiliscə kobud səslənə bilər, xüsusən tanımadığın adama. Ona görə please (zəhmət olmasa) əlavə edilir. please cümlənin əvvəlində və ya sonunda dura bilər; sonda gələndə ondan əvvəl vergül qoyulur. Daha nəzakətli olmaq üçün əmr yerinə sual işlənir: Could you…? (g09).",
  ex:[["Please wait here.","Zəhmət olmasa, burada gözləyin."],["Close the door, please.","Qapını bağla, zəhmət olmasa."],["Could you close the door, please?","Qapını bağlaya bilərsiniz?"]]},
 {h:"4. Let's + fel — «gəl …-aq»",
  t:"Birlikdə nəsə etməyi təklif edəndə Let's + sadə fel işlənir: «gəl …-aq». Let's = let us, amma həmişə qısa formada deyilir. Arada to olmur. İnkar forması Let's not + fel-dir: «…-mayaq».",
  ex:[["Let's go to the cinema.","Gəl kinoya gedək."],["Let's not wait. Let's start.","Gözləməyək. Başlayaq."]],
  no:"Let's to go / Let's don't go — səhvdir"},
 {h:"5. Would you like…? — təklif",
  t:"Kiməsə nəsə təklif edəndə Would you like…? işlənir, mənası «istəyirsən? istərdin?»-dir. Əşya təklif edəndə Would you like + isim gəlir. Bir iş təklif edəndə Would you like + to + fel gəlir. Bu halda to atılmır.",
  ex:[["Would you like some tea?","Çay istəyirsən?"],["Would you like to come with us?","Bizimlə gəlmək istəyirsən?"],["Would you like something to drink?","Nəsə içmək istəyirsən?"]],
  no:"Would you like go? — səhvdir"},
 {h:"6. Do you like? ≠ Would you like?",
  t:"Bu iki sual oxşar görünür, amma mənaları fərqlidir. Do you like…? ümumiyyətlə xoşlayıb-xoşlamadığını soruşur: «sevirsən?». Would you like…? isə indi nəsə təklif edir: «istəyirsən?». Kafedə qonağa həmişə Would you like…? deyilir.",
  ex:[["Do you like coffee? — Yes, I drink it every day.","Qəhvəni xoşlayırsan? — Bəli, hər gün içirəm."],["Would you like a coffee? — Yes, please.","Qəhvə istəyirsən? — Bəli, zəhmət olmasa."]]},
 {h:"7. I'd like — nəzakətli «istəyirəm»",
  t:"Mağazada, kafedə «I want» birbaşa və bir az kobud səslənir. Onun yerinə nəzakətli I'd like (= I would like) deyilir: «istərdim». Arxasından isim gəlirsə, to lazım deyil. Arxasından fel gəlirsə, to + fel lazımdır.",
  ex:[["I'd like a glass of water, please.","Bir stəkan su istərdim."],["I'd like to book a table.","Masa sifariş etmək istərdim."]]},
 {h:"8. Təklifə cavab",
  t:"Təklifi qəbul edəndə Yes, please, imtina edəndə No, thank you deyilir. Dəvəti sevinclə qəbul edəndə I'd love to deyilir. Qısa cavabda «Yes, I would like» demək olmaz, çünki like-dan sonra mütləq nəsə gəlməlidir. Sadəcə Yes, please kifayətdir.",
  ex:[["Would you like some cake? — Yes, please.","Tort istəyirsən? — Bəli, zəhmət olmasa."],["Would you like to come? — I'd love to!","Gəlmək istəyirsən? — Məmnuniyyətlə!"]]},
 {h:"9. Shall I…? / Shall we…? — «…edim? …edək?»",
  t:"Shall I…? kömək təklif edəndə işlənir: «…edim? istəyirsən, …edim?». Shall we…? birlikdə nəsə etməyi təklif edəndə işlənir: «…edək?». Ondan sonra sadə fel gəlir, to yoxdur. Shall we…? mənaca Let's-ə yaxındır, sadəcə sual formasındadır.",
  ex:[["Shall I open the window?","Pəncərəni açım?"],["Shall we take a taxi?","Taksi tutaq?"],["What shall we do tonight?","Bu axşam nə edək?"]]},
 {h:"10. I'd rather + fel — «üstün tuturam»",
  t:"Bir şeyi digərindən çox istədiyini demək üçün I'd rather (= I would rather) işlənir: «üstün tuturam, …-mağı istərdim». Ondan sonra sadə fel gəlir, to yoxdur — bu, would like-dan fərqlidir. İki şeyi müqayisə edəndə than gəlir. than-dan sonra da sadə fel işlənir.",
  ex:[["I'd rather stay at home.","Evdə qalmağı üstün tuturam."],["I'd rather walk than take the bus.","Avtobusa minməkdənsə, piyada getməyi üstün tuturam."]],
  no:"I'd rather to stay — səhvdir"},
 {h:"11. I'd rather not — «istəməzdim»",
  t:"Kimsə sənə nəsə təklif edəndə və sən istəmirsənsə, tək «No» kobud səslənə bilər. Onun yerinə I'd rather not («istəməzdim») deyilir. Bu ifadə tək cavab kimi də işlənir, arxasından fel də gələ bilər: I'd rather not + sadə fel. Burada da to yoxdur.",
  ex:[["Do you want to go out? — I'd rather not.","Çölə çıxmaq istəyirsən? — İstəməzdim."],["I'd rather not talk about it.","Bu barədə danışmamağı üstün tuturam."]]}
],
g05: [
 {h:"1. Gələcək üçün bir neçə forma var",
  t:"Azərbaycanca «edəcəyəm» deyirik. İngiliscə isə forma niyyətdən asılıdır: əvvəlcədən plan, indi verilən qərar, razılaşdırılmış görüş və ya proqnoz. Hər birinin öz forması var.",
  tbl:[["Əvvəlcədən plan","I'm going to study."],["İndi verilən qərar, söz","I'll help you."],["Razılaşdırılmış görüş","I'm meeting Anar at 6."],["Cədvəl (qatar, dərs)","The train leaves at 8."]],
  ex:[["I'm going to visit my aunt on Sunday.","Bazar günü xalama baş çəkəcəyəm (planım var)."],["OK, I'll call you back.","Yaxşı, sənə geri zəng edərəm (indi qərar verdim)."]]},
 {h:"2. be going to — əvvəlcədən plan",
  t:"Bir işi danışmazdan ƏVVƏL düşünüb qərara gəlmisənsə, be going to işlənir. Yəni bu, artıq sənin planın, niyyətindir. Forma: am / is / are + going to + sadə fel. am / is / are «kim»-ə görə seçilir (g01) və atılmır.",
  ex:[["I'm going to start a new course in January.","Yanvarda yeni kursa başlayacağam."],["We are going to buy a flat.","Mənzil alacağıq."],["What are you going to do this weekend?","Bu həftəsonu nə edəcəksən?"]],
  no:"I going to buy — səhvdir (am lazımdır)"},
 {h:"3. going to — görünən əlamət",
  t:"going to-nun ikinci mənası proqnozdur, amma indi GÖRDÜYÜN bir şeyə əsaslanan proqnoz. Göydə qara buludlar görürsən — deməli, yağış yağacaq. Adam büdrəyir — deməli, yıxılacaq. Yəni nəticənin əlaməti artıq gözünün qabağındadır.",
  ex:[["Look at those clouds! It's going to rain.","O buludlara bax! Yağış yağacaq."],["Be careful! You're going to fall.","Ehtiyatlı ol! Yıxılacaqsan."],["She's going to have a baby.","Onun uşağı olacaq."]]},
 {h:"4. going to — sual və inkar",
  t:"going to cümləsində am / is / are var. g01-dəki qaydaya görə, am / is / are varsa, do lazım deyil. Sualda am / is / are «kim»-dən əvvələ keçir, inkarda ondan sonra not gəlir. going to və fel öz yerində qalır.",
  ex:[["Are you going to study tonight?","Bu axşam dərs oxuyacaqsan?"],["She isn't going to buy a car.","O maşın almayacaq."],["When are you going to call him?","Ona nə vaxt zəng edəcəksən?"]],
  no:"Do you going to study? — səhvdir"},
 {h:"5. will — indi verilən qərar",
  t:"Əvvəlcədən plan yoxdursa və qərarı danışarkən, elə o an verirsənsə, will işlənir. Azərbaycanca bunu çox vaxt «alaram, edərəm» kimi deyirik. Qısa forması 'll-dir: I'll, we'll. Plan artıq varsa, will yox, going to işlənir.",
  ex:[["We have no bread. — OK, I'll buy some.","Çörəyimiz yoxdur. — Yaxşı, alaram."],["The phone is ringing. I'll answer it.","Telefon zəng çalır. Mən cavab verərəm."],["I'm cold. — I'll close the window.","Üşüyürəm. — Pəncərəni bağlayaram."]]},
 {h:"6. will — söz, təklif, xahiş",
  t:"will başqa hallarda da işlənir. Söz verəndə: I'll…, I won't… Kömək təklif edəndə: I'll help you. Kimdənsə xahiş edəndə: Will you…? won't həm də «razı olmur, etmək istəmir» mənasında işlənir.",
  ex:[["I won't tell anyone. I promise.","Heç kimə deməyəcəm. Söz verirəm."],["Will you help me, please?","Mənə kömək edərsən?"],["I'll carry your bag.","Çantanı mən daşıyaram."],["My car won't start.","Maşınım işə düşmür."]]},
 {h:"7. will — fikir və proqnoz",
  t:"Gələcək haqqında öz fikrini, təxminini deyəndə will işlənir. Çox vaxt I think, I'm sure, probably sözləri ilə gəlir. «Olmayacaq» fikrini ingiliscə çox vaxt I don't think … will ilə deyirik. Azərbaycanca «məncə, …-mayacaq» deyirik, ingiliscə isə inkar I think-ə keçir.",
  ex:[["I think the exam will be difficult.","Məncə imtahan çətin olacaq."],["I don't think it will rain.","Məncə yağış yağmayacaq."],["She will probably be late.","O, yəqin ki, gecikəcək."]]},
 {h:"8. will — forma",
  t:"will bütün şəxslər üçün eynidir: I will, she will, they will. Ondan sonra sadə fel gəlir: to yoxdur, -s yoxdur. İnkarı won't-dur (= will not). Sualda will «kim»-dən əvvələ keçir, do işlənmir.",
  ex:[["She will come tomorrow.","O sabah gələcək."],["He won't be at work tomorrow.","O sabah işdə olmayacaq."]],
  no:"I will to go / She will comes — səhvdir"},
 {h:"9. Present Continuous — razılaşdırılmış görüş",
  t:"Gələcək görüş, səfər və ya tədbir artıq razılaşdırılıbsa — vaxtı və yeri bəllidir, bilet alınıb — am / is / are + -ing işlənir. Forma «indi» üçün olan Present Continuous ilə eynidir, gələcək mənasını vaxt sözü verir: tomorrow, on Friday, next week. Bu halda going to da düzdür, amma danışıqda Continuous daha çox işlənir.",
  ex:[["I'm meeting the manager at 3 tomorrow.","Sabah saat 3-də menecerlə görüşürəm."],["We're flying to Tbilisi on Friday.","Cümə günü Tbilisiyə uçuruq."],["What are you doing tonight?","Bu axşam nə edirsən? (planın nədir?)"]]},
 {h:"10. Present Simple — cədvəl",
  t:"Qatar, təyyarə, dərs, film, mağazanın açılışı kimi cədvəldə yazılmış vaxtlar üçün Present Simple işlənir. Bu vaxtları sən yox, cədvəl müəyyən edir. Ona görə gələcək olsa da, will yox, Present Simple deyilir. he / she / it ilə -s unutma.",
  ex:[["The train leaves at 6:15 tomorrow.","Qatar sabah 6:15-də yola düşür."],["The film starts at 8.","Film saat 8-də başlayır."],["What time does the shop open tomorrow?","Mağaza sabah saat neçədə açılır?"]]},
 {h:"11. when, if, as soon as + Present Simple",
  t:"when, if, as soon as (…-an kimi), before, after, until sözlərindən sonra gələcək mənası olsa da will işlənmir. Bu hissədə Present Simple işlənir. will yalnız cümlənin o biri, əsas hissəsində olur. Azərbaycanca da «çatanda», «yağsa» deyirik və bu sözlərdə «-acaq» yoxdur — ingiliscə də belədir.",
  ex:[["I'll call you when I get home.","Evə çatanda sənə zəng edəcəm."],["If it rains, we'll stay at home.","Yağış yağsa, evdə qalacağıq."],["I'll text you as soon as I arrive.","Çatan kimi sənə yazacam."]],
  no:"when I will get home / if it will rain — səhvdir"}
],
g19: [
 {h:"1. there is / there are — «… var»",
  t:"Bir yerdə nəyinsə olduğunu demək üçün there is / there are işlənir. Azərbaycanca «Otaqda masa var» deyirik: yer əvvəldə, «var» sonda. İngiliscə isə cümlə there is ilə başlayır, yer adətən sonda gəlir. there burada «orada» demək deyil, sadəcə cümləni başladır.",
  ex:[["There is a cafe near my office.","Ofisimin yaxınlığında kafe var."],["There are three parks in our district.","Rayonumuzda üç park var."]]},
 {h:"2. is yoxsa are?",
  t:"Seçim there-dən sonra gələn ismə görə edilir. Bir şey varsa (tək isim) — there is, qısa forması there's. Çox şey varsa (cəm isim) — there are. Sayılmayan şeylər (su, pul, vaxt) üçün də there is işlənir.",
  tbl:[["bir şey","There is a bank."],["çox şey","There are two banks."],["sayılmayan","There is some milk."]],
  ex:[["There is a bank near here.","Yaxınlıqda bank var."],["There are two banks near here.","Yaxınlıqda iki bank var."]],
  no:"There is two cars — səhvdir"},
 {h:"3. İnkar: there isn't / there aren't / there's no",
  t:"«Yoxdur» demək üçün is / are-dan sonra not əlavə olunur: there isn't, there aren't. Cəm isimlə inkarda çox vaxt any gəlir. İkinci yol: there's no / there are no + isim. Burada not və any lazım deyil, çünki no özü inkardır, ona görə ikisini birlikdə işlətmə.",
  ex:[["There isn't a hospital in the village.","Kənddə xəstəxana yoxdur."],["There aren't any shops here.","Burada mağaza yoxdur."],["There's no milk.","Süd yoxdur."]],
  no:"There isn't no milk. — səhvdir"},
 {h:"4. Sual və qısa cavab",
  t:"Sualda is / are there sözündən əvvələ keçir: Is there…? Are there…? Cəm isimlə sualda çox vaxt any işlənir. Qısa cavabda there is / there are təkrar olunur. «Bəli» cavabında qısaltma olmur (g22).",
  ex:[["Is there a pharmacy near here? — Yes, there is.","Yaxınlıqda aptek var? — Bəli, var."],["Are there any eggs? — No, there aren't.","Yumurta var? — Xeyr, yoxdur."]],
  no:"Yes, there's. — səhvdir"},
 {h:"5. How many … are there?",
  t:"Neçə dənə olduğunu soruşanda How many + cəm isim + are there? işlənir. Sayılmayan şey üçün How much + isim + is there? deyilir. Cavabda there are + say və ya sadəcə say gəlir. Keçmişdə are → were olur.",
  ex:[["How many students are there in your class?","Sinfinizdə neçə tələbə var?"],["How much milk is there? — Not much.","Nə qədər süd var? — Çox deyil."],["How many people were there? — About fifty.","Neçə nəfər var idi? — Təxminən əlli."]]},
 {h:"6. Keçmiş: there was / there were",
  t:"«Var idi» demək üçün there is → there was, there are → there were olur. Sual və inkar qaydaları eynidir: was / were qabağa keçir, inkarda not gəlir. Çox vaxt keçmiş vaxt sözü ilə gəlir: ten years ago, yesterday.",
  ex:[["There was a cinema here ten years ago.","On il əvvəl burada kinoteatr var idi."],["There were a lot of people at the wedding.","Toyda çoxlu adam var idi."],["How many people were there?","Neçə nəfər var idi?"]]},
 {h:"7. Gələcək: there will be",
  t:"Gələcəkdə nəyinsə olacağını demək üçün there will be işlənir. Bu forma tək və cəm üçün eynidir — is / are seçmək lazım deyil. İnkarı there won't be, sualı Will there be…? formasındadır.",
  ex:[["There will be a meeting tomorrow.","Sabah iclas olacaq."],["There will be new buses next year.","Gələn il yeni avtobuslar olacaq."],["Will there be any food at the party?","Məclisdə yemək olacaq?"]]},
 {h:"8. have yoxsa there is?",
  t:"Hər ikisi Azərbaycancaya «var» kimi tərcümə olunur, ona görə tez-tez qarışdırılır. Kiminsə və ya nəyinsə SAHİB olduğunu deyəndə have / has işlənir və cümlə sahiblə başlayır. Bir YERDƏ nəyinsə olduğunu deyəndə there is / are işlənir və yer adətən sonda gəlir. Cümlə yerlə başlayırsa (in my room), ondan sonra have gəlmir.",
  ex:[["My city has a beautiful old mosque.","Şəhərimin gözəl köhnə məscidi var."],["There is a beautiful old mosque in my city.","Şəhərimdə gözəl köhnə məscid var."],["There is a bed in my room.","Otağımda çarpayı var."]],
  no:"In my room have a bed — səhvdir"},
 {h:"9. Əvvəl there, sonra it",
  t:"Bir şeyi ilk dəfə xatırlayanda there is / there are deyirik, çünki dinləyən onu hələ bilmir. Sonra həmin şey haqqında danışanda onu it (tək) və ya they (çox) ilə əvəz edirik. there yalnız «var olmaq» üçündür, şeyi təsvir etmək üçün işlənmir.",
  ex:[["There's a new cafe on our street. It's very nice.","Küçəmizdə yeni kafe var. Çox gözəldir."],["There are two cafes near here. They're both good.","Yaxınlıqda iki kafe var. İkisi də yaxşıdır."],["Is there a bank near here? — Yes, it's next to the station.","Yaxınlıqda bank var? — Bəli, stansiyanın yanındadır."]]},
 {h:"10. it — hava, vaxt, məsafə",
  t:"Azərbaycanca «Soyuqdur», «Saat beşdir» deyirik və «o» sözü lazım olmur. İngiliscə isə cümlədə mütləq «kim» olmalıdır (g02). Ona görə hava, vaxt, tarix və məsafə haqqında danışanda it işlənir. Bu it heç bir əşyanı göstərmir, sadəcə «kim»-in yerini doldurur.",
  ex:[["It's cold today.","Bu gün soyuqdur."],["It's 5 o'clock.","Saat beşdir."],["It's 10 kilometres from here.","Buradan 10 kilometrdir."],["It's raining.","Yağış yağır."]],
  no:"Is cold today — səhvdir"},
 {h:"11. It's + sifət + to …",
  t:"Bir iş haqqında fikir bildirəndə (asandır, çətindir, xoşdur) cümlə çox vaxt It's + sifət + to + fel ilə başlayır. Azərbaycanca «İş tapmaq çətindir» deyirik — işin özü əvvəldə durur. İngiliscə belə də demək olar, amma daha təbii yol it ilə başlamaqdır. it burada sonra gələn to-lu hissəni göstərir.",
  ex:[["It's nice to see you again.","Səni yenidən görmək xoşdur."],["It's difficult to find a job.","İş tapmaq çətindir."],["It's important to sleep well.","Yaxşı yatmaq vacibdir."]]}
],
g06: [
 {h:"1. Sayılan və sayılmayan isimlər",
  t:"Bəzi şeyləri saymaq olur: bir kitab, iki kitab. Bəzilərini saymaq olmur: su, pul, məlumat. İngiliscə bu fərq çox vacibdir, çünki a/an, cəm forması və much/many buna görə seçilir.",
  tbl:[["Sayılan","a book, two books; an apple, apples"],["Sayılmayan","water, money, bread, time, music"]],
  ex:[["I have two brothers.","İki qardaşım var."],["I need some money.","Mənə bir az pul lazımdır."]]},
 {h:"2. Cəm forması: -s, -es, -ies",
  t:"Sayılan isimlər cəmdə -s alır. Söz s, sh, ch, x ilə bitirsə, -es artırılır, çünki belə oxumaq asandır. Samit + y ilə bitirsə, y → ies olur, amma sait + y olanda (day, boy) sadəcə -s artırılır. Azərbaycanca «iki kitab» deyirik və cəm şəkilçisi yoxdur, ingiliscə isə saydan sonra da -s mütləqdir.",
  tbl:[["car","cars"],["bus / box / watch","buses / boxes / watches"],["city / country","cities / countries"]],
  ex:[["There are three buses to the city.","Şəhərə üç avtobus var."],["I visited two cities.","İki şəhərə getdim."]]},
 {h:"3. Qaydasız cəmlər",
  t:"Bəzi isimlər cəmdə -s almır, tamamilə dəyişir. Bunların qaydası yoxdur, ona görə əzbərləmək lazımdır. people özü cəmdir və «insanlar» deməkdir: people are, people have. person sözünün cəmi kimi people işlənir.",
  tbl:[["man","men"],["woman","women"],["child","children"],["person","people"],["foot","feet"],["tooth","teeth"]],
  ex:[["Two women were at the door.","Qapıda iki qadın var idi."],["My children go to school.","Uşaqlarım məktəbə gedir."],["There were a lot of people at the concert.","Konsertdə çoxlu adam var idi."]],
  no:"childs / womans / peoples are — səhvdir"},
 {h:"4. a / an — «bir», ilk dəfə",
  t:"Tək sayılan isimdən əvvəl a/an işlənir: bir şey, hər hansı biri, ilk dəfə xatırlanan. Azərbaycanca çox vaxt bu söz deyilmir, ingiliscə isə mütləqdir. Peşədən əvvəl də işlənir.",
  ex:[["I have a car.","Maşınım var."],["She is a nurse.","O tibb bacısıdır."]],
  no:"She is nurse — səhvdir"},
 {h:"5. a yoxsa an? — səsə bax",
  t:"Söz sait SƏSİ ilə başlayırsa an, samit səsi ilə başlayırsa a işlənir. Burada hərfə yox, oxunuşa baxılır. hour sözündə h oxunmur, ona görə an hour deyilir. university sözü isə «yu» səsi ilə başlayır, ona görə a university deyilir.",
  tbl:[["an","an apple, an hour, an honest man, an umbrella"],["a","a book, a university, a European city"]],
  ex:[["I waited for an hour.","Bir saat gözlədim."],["She studies at a university.","O universitetdə oxuyur."],["He's an engineer.","O mühəndisdir."]]},
 {h:"6. Sayılmayan isimlər: a yox, -s yox",
  t:"Sayılmayan isimlər a/an almır və cəm olmur. Bu siyahıdakı sözlər ingiliscə sayılmır: advice, information, news, money, furniture, bread, homework, luggage, weather, work. «Bir dənə» demək üçün a piece of, a bottle of, a cup of işlənir.",
  ex:[["Can you give me some advice?","Mənə məsləhət verə bilərsən?"],["I have some news for you.","Sənə bir xəbərim var."],["a piece of cake, a bottle of water","bir tikə tort, bir şüşə su"]],
  no:"an advice / informations / a furniture — səhvdir"},
 {h:"7. the — hər ikimiz bilirik",
  t:"Danışan da, dinləyən də HANSI şeydən söhbət getdiyini bilirsə, the işlənir. Bir şey ilk dəfə xatırlananda a / an deyilir, ikinci dəfə isə artıq bəlli olduğu üçün the deyilir. Otaqda bir qapı varsa, «qapını bağla» deyəndə hamı hansı qapı olduğunu bilir — the door. Azərbaycanca bu fərqi çox vaxt şəkilçi göstərir: «lampa aldım» — «lampanı bağla».",
  ex:[["I bought a lamp. The lamp was cheap.","Bir lampa aldım. Lampa ucuz idi."],["Can you close the door?","Qapını bağlaya bilərsən?"],["Where is the car? — In the garage.","Maşın haradadır? — Qarajda."]]},
 {h:"8. the — dünyada tək olan şeylər",
  t:"Dünyada bir dənə olan şeylər həmişə the ilə gəlir: the sun, the moon, the sky, the sea, the internet. Çünki hansı günəşdən danışdığımız hamıya bəllidir. «Ən» bildirən sözlərlə də the işlənir: the best, the biggest. first, last və same sözlərindən əvvəl də the gəlir.",
  ex:[["The sun is very hot today.","Bu gün günəş çox istidir."],["I read it on the internet.","Onu internetdə oxudum."],["He is the best student in the class.","O, sinifdə ən yaxşı tələbədir."]]},
 {h:"9. Ümumi danışanda artikl yoxdur",
  t:"Bir şey haqqında ümumiyyətlə danışanda — bütün itlər, ümumiyyətlə musiqi — artikl işlənmir. Bu halda sayılan isim cəm olur (dogs), sayılmayan isim isə olduğu kimi qalır (music, life). Azərbaycanca da «İtlər mehribandır» deyirik və artikl yoxdur. Konkret şeydən danışanda isə the gəlir: the music in this cafe.",
  ex:[["I like music.","Musiqini sevirəm."],["Dogs are friendly.","İtlər mehribandır."],["Life is beautiful.","Həyat gözəldir."]],
  no:"The life is beautiful — səhvdir"},
 {h:"10. go to work, go home, at home — artiklsız",
  t:"Bəzi hazır birləşmələrdə artikl işlənmir: go to work, go to school, go to bed, at work, at home, go home. Bunları bütöv əzbərlə. Digər yerlərin çoxu isə the ilə gəlir: go to the cinema, the bank, the station, the doctor. home sözündən əvvəl to da işlənmir.",
  ex:[["I go to work by bus.","İşə avtobusla gedirəm."],["I usually go to bed at 11.","Adətən saat 11-də yatıram."],["Let's go to the cinema.","Gəl kinoya gedək."]]},
 {h:"11. some / any",
  t:"some və any «bir az, bir neçə» deməkdir və miqdarı dəqiq demədən işlənir. some təsdiq cümləsində, any sual və inkar cümləsində işlənir. İkisi də həm cəm isimlə, həm də sayılmayan isimlə gəlir. Təklif və xahiş sualında some işlənir, çünki «hə» cavabı gözlənilir.",
  ex:[["There are some apples on the table.","Masanın üstündə bir neçə alma var."],["Are there any shops near here?","Yaxınlıqda mağaza var?"],["Could I have some water?","Bir az su ala bilərəm?"]]},
 {h:"12. much / many / a lot of",
  t:"many sayılan cəm isimlə, much sayılmayan isimlə işlənir. much və many çox vaxt sual və inkar cümləsində gəlir. Təsdiq cümləsində isə a lot of daha təbiidir və hər iki növ isimlə işlənir. Sualda How many…? sayı, How much…? miqdarı və qiyməti soruşur.",
  tbl:[["many","many books, How many people?"],["much","much money, How much time?"],["a lot of","a lot of books, a lot of money"]],
  ex:[["We don't have much time.","Çox vaxtımız yoxdur."],["How many people came?","Neçə nəfər gəldi?"]]},
 {h:"13. a few / a little — «bir az, bir neçə»",
  t:"a few sayılan isimlə (bir neçə), a little sayılmayan isimlə (bir az) işlənir. Hər ikisi müsbət mənadır: az, amma kifayət qədər var. a olmadan few və little «çox az, demək olar ki yoxdur» deməkdir və mənfi məna verir. Sayılan və sayılmayan qaydası much / many ilə eynidir.",
  ex:[["I have a few friends in London.","Londonda bir neçə dostum var."],["There's a little sugar in my tea.","Çayımda bir az şəkər var."],["Few people came.","Çox az adam gəldi."]]}
],
g07: [
 {h:"1. Müqayisə: qısa sifət + -er + than",
  t:"İki şeyi müqayisə edəndə qısa (bir hecalı) sifətə -er artırılır: cheap → cheaper. Ondan sonra than gəlir — «…-dan, …-dən» mənasında. Azərbaycanca sifət dəyişmir («ucuz» — «daha ucuz»), ingiliscə isə sifətin özü dəyişir. than-dan sonra əvəzlik gələndə me, him formaları işlənir.",
  ex:[["The train is faster than the bus.","Qatar avtobusdan sürətlidir."],["My brother is older than me.","Qardaşım məndən böyükdür."]]},
 {h:"2. -er yazılışı",
  t:"-er artırarkən yazılış bir az dəyişə bilər. Sifət e ilə bitirsə, yalnız -r artırılır. Bir hecalı sifət «samit + sait + samit» ilə bitirsə, son hərf ikiləşir. -y ilə bitirsə, y → ier olur. Eyni qaydalar -est üçün də keçərlidir.",
  tbl:[["nice","nicer"],["big / hot / thin","bigger / hotter / thinner"],["easy / happy / busy","easier / happier / busier"]],
  ex:[["Today is hotter than yesterday.","Bu gün dünənkindən istidir."],["This test is easier than the last one.","Bu test əvvəlkindən asandır."]]},
 {h:"3. Uzun sifət: more … than",
  t:"İki və daha çox hecalı sifətlər -er almır, onlardan əvvəl more gəlir: more expensive, more interesting. -y ilə bitən iki hecalı sifətlər istisnadır: onlar -ier alır (easy → easier, happy → happier). Bir sifətdə ikisi birlikdə işlənmir: ya -er, ya more. than isə hər iki halda eynidir.",
  ex:[["This phone is more expensive than that one.","Bu telefon o birindən bahadır."],["The book is more interesting than the film.","Kitab filmdən maraqlıdır."],["Russian is more difficult than English for me.","Mənim üçün rus dili ingilis dilindən çətindir."]],
  no:"more tall / expensiver — səhvdir"},
 {h:"4. Qaydasız sifətlər",
  t:"Bəzi sifətlər qaydaya tabe olmur və tamamilə dəyişir. Ən çox işlənənləri good, bad və far-dır. Bunları əzbərləmək lazımdır, çünki -er və -est ilə düzəlmir. Zərf olan well də eyni dəyişir: better — the best.",
  tbl:[["good","better — the best"],["bad","worse — the worst"],["far","further — the furthest"]],
  ex:[["My English is better than last year.","İngiliscəm keçən ildən yaxşıdır."],["The weather is worse today.","Bu gün hava daha pisdir."],["This is the worst film I've ever seen.","Bu, gördüyüm ən pis filmdir."]],
  no:"gooder / badder — səhvdir"},
 {h:"5. «Ən»: the + -est",
  t:"Bir şeyin qrupdakı hamıdan üstün olduğunu demək üçün qısa sifətə -est artırılır və qabağına the qoyulur. Yazılış qaydaları -er ilə eynidir: big → the biggest, easy → the easiest. the mütləqdir, çünki «ən» yalnız bir şey ola bilər. Azərbaycanca «ən» ayrıca sözdür, ingiliscə isə sifətin özü dəyişir.",
  ex:[["Baku is the biggest city in Azerbaijan.","Bakı Azərbaycanın ən böyük şəhəridir."],["This is the cheapest hotel.","Bu ən ucuz oteldir."],["Who is the oldest person in your family?","Ailənizdə ən yaşlı kimdir?"]]},
 {h:"6. «Ən»: the most + uzun sifət",
  t:"Uzun sifətlərdə (iki və daha çox heca) -est artırılmır, onun yerinə the most gəlir. Qayda -er / more ilə eynidir: qısa sifət -est alır, uzun sifətin qabağına the most gəlir. «Ən» mənasında the mütləqdir. the more isə «ən» demək deyil, o, iki şeyi müqayisə edir.",
  ex:[["This is the most expensive restaurant in town.","Bu, şəhərin ən bahalı restoranıdır."],["She is the most beautiful woman in the world.","O, dünyanın ən gözəl qadınıdır."],["It was the most difficult exam of the year.","Bu, ilin ən çətin imtahanı idi."]],
  no:"the more expensive (ən mənasında) — səhvdir"},
 {h:"7. «Ən»-dən sonra in / of",
  t:"«Ən» deyəndən sonra çox vaxt qrupu və ya yeri göstəririk: «ailədə ən hündür», «ilin ən yaxşı günü». Yer və qrup üçün in işlənir: in the world, in my family, in the class. Vaxt dövrü və say üçün of işlənir: of the year, of my life, of all. Azərbaycanca hər ikisi «-da» və ya «-ın» olur, ona görə diqqət et.",
  ex:[["He is the tallest in our family.","O, ailəmizdə ən hündürdür."],["It was the best day of my life.","Həyatımın ən yaxşı günü idi."],["Baku is the biggest city in the Caucasus.","Bakı Qafqazın ən böyük şəhəridir."]]},
 {h:"8. Fərqin ölçüsü: much, a lot, a bit",
  t:"Fərqin nə qədər olduğunu göstərmək üçün müqayisədən əvvəl söz əlavə olunur. Fərq böyükdürsə much, a lot və ya far, kiçikdirsə a bit və ya a little. very müqayisə ilə işlənmir, o yalnız adi sifətlə gəlir: very cheap, amma much cheaper.",
  ex:[["The metro is much faster.","Metro xeyli sürətlidir."],["She is a bit older than her sister.","O, bacısından bir az böyükdür."],["This flat is a lot bigger than ours.","Bu mənzil bizimkindən xeyli böyükdür."]],
  no:"very cheaper — səhvdir"},
 {h:"9. Bərabərlik: as … as",
  t:"İki şey eyni dərəcədədirsə, as + sifət + as işlənir: «… qədər». Burada sifət dəyişmir: -er və more yoxdur. than da işlənmir, iki dəfə as gəlir. Azərbaycanca «səninki qədər» deyirik.",
  ex:[["My phone is as good as yours.","Mənim telefonum səninki qədər yaxşıdır."],["He is as tall as his father.","O, atası qədər hündürdür."],["Is your car as fast as mine?","Sənin maşının mənimki qədər sürətlidir?"]],
  no:"as old than — səhvdir"},
 {h:"10. not as … as — «… qədər deyil»",
  t:"Bir şey o birindən az dərəcədədirsə, not as + sifət + as deyilir: «… qədər deyil». Mənaca bu, -er / more ilə müqayisəyə əks tərəfdən baxmaqdır. Danışıqda not as … as çox işlənir, çünki daha yumşaq səslənir. Burada da sifət dəyişmir.",
  ex:[["The flat isn't as big as I expected.","Mənzil gözlədiyim qədər böyük deyil."],["Ali is not as tall as his brother.","Əli qardaşı qədər hündür deyil."],["My English isn't as good as yours.","Mənim ingiliscəm səninki qədər yaxşı deyil."]]},
 {h:"11. less / the least — «daha az, ən az»",
  t:"less «daha az» deməkdir və more-un əksidir. the least «ən az» deməkdir və the most-un əksidir. Bu sözlər çox vaxt uzun sifətlərlə işlənir. Qısa sifətlərlə isə adətən not as … as daha təbii səslənir.",
  ex:[["The bus is less comfortable than the train.","Avtobus qatardan az rahatdır."],["This is the least expensive option.","Bu ən ucuz variantdır."]]},
 {h:"12. the same as — «… ilə eyni»",
  t:"İki şey tam eynidirsə, the same as işlənir: «… ilə eyni». the mütləqdir və as-dan sonra müqayisə olunan şey gəlir. Burada than işlənmir. Fərqli şeylər üçün isə different from işlənir.",
  ex:[["My phone is the same as yours.","Mənim telefonum səninki ilə eynidir."],["Her dress is the same as mine.","Onun donu mənimki ilə eynidir."],["My phone is different from yours.","Mənim telefonum səninkindən fərqlidir."]],
  no:"the same than — səhvdir"}
],
g24: [
 {h:"1. Sifət — «necə şey?»",
  t:"Sifət isim haqqında məlumat verir və «necə?» sualına cavab verir: necə adam, necə ev. İsimlə birlikdə gələndə sifət isimdən əvvəl durur, Azərbaycancadakı kimi. İsim cəm olanda sifət dəyişmir, -s almır. Sifət fel haqqında danışmır — bunun üçün zərf lazımdır (3-cü qayda).",
  ex:[["a careful driver","ehtiyatlı sürücü"],["two beautiful houses","iki gözəl ev"],["She has a beautiful voice.","Onun gözəl səsi var."]]},
 {h:"2. Sifət be-dən sonra da gəlir",
  t:"am / is / are / was / were-dən sonra sifət işlənir, zərf yox. Bu fellərdən sonra da sifət gəlir: look (görünmək), feel (hiss etmək), seem (görünmək), sound (səslənmək), taste (dadı olmaq), smell (iyi gəlmək). Səbəb budur: bu fellər işin NECƏ edildiyini yox, adamın və ya şeyin necə OLDUĞUNU göstərir. Ona görə «yorğun görünürsən» cümləsində tired (sifət) işlənir, tiredly yox.",
  ex:[["The soup is hot.","Şorba istidir."],["You look tired.","Yorğun görünürsən."],["This tastes good.","Bunun dadı yaxşıdır."]],
  no:"You look tiredly — səhvdir"},
 {h:"3. Zərf — «necə edir?»",
  t:"Zərf fel haqqında məlumat verir və «necə edir?» sualına cavab verir. Çox vaxt sifətə -ly artırmaqla düzəlir: careful → carefully. Azərbaycanca da bu fərq var: «ehtiyatlı sürücü» (sifət) və «ehtiyatla sürür» (zərf). İş felinin yanında sifət yox, zərf işlənir.",
  ex:[["He drives carefully.","O ehtiyatla sürür."],["She spoke quietly.","O sakitcə danışdı."]],
  no:"He drives careful — səhvdir"},
 {h:"4. -ly yazılışı",
  t:"-ly artırarkən yazılış bir az dəyişə bilər. Sifət -y ilə bitirsə, y → ily olur. -le ilə bitirsə, e düşür və y gəlir: terrible → terribly. Qalan sifətlərə sadəcə -ly artırılır.",
  tbl:[["quick / slow","quickly / slowly"],["easy / happy","easily / happily"],["terrible / possible","terribly / possibly"]],
  ex:[["You can do it easily.","Bunu asanlıqla edə bilərsən."],["I sang terribly.","Dəhşətli oxudum."]]},
 {h:"5. Qaydasız zərflər: well, fast, hard",
  t:"Bəzi zərflər qaydaya tabe deyil. good-un zərfi goodly yox, well-dir. fast, hard, late, early isə dəyişmir: sifət də, zərf də eyni sözdür. Diqqət: hardly «çətinliklə, demək olar ki yox» deməkdir, hard-ın zərfi deyil.",
  tbl:[["good","well"],["fast","fast"],["hard","hard"],["late / early","late / early"]],
  ex:[["She speaks English well.","O ingiliscə yaxşı danışır."],["He works very hard.","O çox çalışır."]],
  no:"He speaks good / He drives fastly — səhvdir"},
 {h:"6. Zərfin yeri",
  t:"Zərf adətən feldən sonra gəlir. Feldən sonra obyekt (nəyi?) varsa, zərf obyektdən də sonra gəlir. Fel ilə obyektin arasına zərf girmir (g02-dəki qayda). Azərbaycanca zərf felin qabağında durur, ingiliscə isə cümlənin sonuna yaxın.",
  ex:[["He speaks English very well.","O ingiliscə çox yaxşı danışır."],["She closed the door quietly.","O qapını sakitcə bağladı."],["I did the test badly.","Testi pis yazdım."]],
  no:"He speaks very well English — səhvdir"},
 {h:"7. very, really, quite",
  t:"very (çox), really (həqiqətən), quite (xeyli, kifayət qədər) sözləri sifətin və ya zərfin gücünü dəyişir. Onlar həmişə sifətdən və ya zərfdən ƏVVƏL gəlir. very fel ilə işlənmir: «çox sevirəm» = I like it very much və ya I really like it. «Çox» sözü ilə ən çox edilən səhv budur.",
  ex:[["It's a very nice day.","Çox gözəl gündür."],["She sings really beautifully.","O həqiqətən gözəl oxuyur."],["I really like this song.","Bu mahnını çox bəyənirəm."]],
  no:"I very like it. — səhvdir"},
 {h:"8. Zərflərlə müqayisə",
  t:"Zərfləri də müqayisə etmək olar. -ly ilə bitən zərflərdə more və most işlənir: more slowly. -ly ilə bitməyən zərflər (fast, hard, early) isə sifət kimi -er alır: faster. well → better, badly → worse olur.",
  ex:[["Please speak more slowly.","Zəhmət olmasa, daha yavaş danış."],["He runs faster than me.","O məndən sürətli qaçır."]]},
 {h:"9. too — «lazım olandan çox»",
  t:"too + sifət «lazım olandan çox» deməkdir və həmişə mənfi məna verir: buna görə problem var, nəsə etmək olmur. very isə sadəcə «çox» deməkdir və problem göstərmir. too-dan sonra sifət gəlir, much yox. too much yalnız isimlə (too much sugar) və ya feldən sonra işlənir.",
  ex:[["This bag is too heavy.","Bu çanta çox ağırdır (qaldıra bilmirəm)."],["It's too expensive.","Bu çox bahadır (ala bilmərəm)."],["I can't sleep. It's too noisy.","Yata bilmirəm. Çox səs-küylüdür."]],
  no:"too much expensive — səhvdir"},
 {h:"10. enough — «kifayət qədər»",
  t:"enough «kifayət qədər» deməkdir. Onun yeri sözün növündən asılıdır: sifətdən SONRA gəlir, isimdən isə ƏVVƏL. Azərbaycanca «kifayət qədər» həmişə əvvəldə durur, ona görə sifətlə səhv edilir. İnkarda «kifayət qədər deyil» mənası verir.",
  tbl:[["sifət + enough","old enough, big enough"],["enough + isim","enough money, enough time"]],
  ex:[["He isn't old enough.","O kifayət qədər böyük deyil."],["We don't have enough money.","Kifayət qədər pulumuz yoxdur."],["Is it warm enough for you?","Sənin üçün kifayət qədər istidir?"]],
  no:"enough old / money enough — səhvdir"},
 {h:"11. too / enough + to + fel",
  t:"too və enough-dan sonra to + fel gələ bilər. Bu hissə nəyin edilə bilmədiyini və ya edilə bildiyini göstərir. too + sifət + to + fel = «… etmək üçün çox …», yəni edə bilmirsən. sifət + enough + to + fel = «… etmək üçün kifayət qədər …», yəni edə bilirsən.",
  ex:[["The tea is too hot to drink.","Çay içmək üçün çox istidir."],["He isn't tall enough to reach the shelf.","Rəfə çatmaq üçün kifayət qədər hündür deyil."],["She's old enough to drive.","O, maşın sürmək üçün kifayət qədər böyükdür."]]},
 {h:"12. -ed və -ing sifətlər",
  t:"-ed ilə bitən sifət insanın HİSS ETDİYİNİ göstərir: bored, interested, tired. -ing ilə bitən sifət isə bu hissi YARADAN şeyi göstərir: boring, interesting, tiring. İnsan haqqında -ing desən, məna dəyişir: I am boring = «mən darıxdırıcı adamam». Ona görə «darıxıram» = I'm bored.",
  ex:[["The film was boring. I was bored.","Film darıxdırıcı idi. Mən darıxdım."],["I'm interested in history. History is interesting.","Tarixlə maraqlanıram. Tarix maraqlıdır."],["The trip was tiring. We were very tired.","Səfər yorucu idi. Biz çox yorulduq."]],
  no:"I am boring (darıxıram mənasında) — səhvdir"}
],
g08: [
 {h:"1. Forma: have / has + V3",
  t:"Present Perfect iki hissədən ibarətdir: have (he / she / it üçün has) və felin üçüncü forması (V3). Qaydalı fellərdə V3 keçmiş forma ilə eynidir: worked, lived. Qaydasız fellərdə V3 ayrıca əzbərlənir (2-ci qayda). Danışıqda have → 've, has → 's qısalır.",
  tbl:[["I / you / we / they","have worked ('ve)"],["he / she / it","has worked ('s)"]],
  ex:[["I have finished my work.","İşimi bitirmişəm."],["She has lived here for a year.","O bir ildir burada yaşayır."],["They've bought a new house.","Onlar yeni ev alıblar."]]},
 {h:"2. Qaydasız fellərin V3 forması",
  t:"Qaydasız fellərin üç forması var: sadə fel, keçmiş forma (V2) və V3. Present Perfect-də həmişə V3 işlənir, V2 yox. Bəzi fellərdə V2 ilə V3 eynidir (bought, made), bəzilərində fərqlidir (went — gone). Cədvəldəki fellər ən çox işlənənlərdir.",
  tbl:[["go","went — gone"],["be","was/were — been"],["see","saw — seen"],["do","did — done"],["eat","ate — eaten"],["write","wrote — written"],["take","took — taken"],["ride","rode — ridden"],["buy / make / lose","bought / made / lost (V2 = V3)"],["know","knew — known"]],
  ex:[["I've seen this film.","Bu filmə baxmışam."],["He has written a book.","O kitab yazıb."],["We have been to Istanbul.","Biz İstanbulda olmuşuq."]],
  no:"has went / have saw — səhvdir"},
 {h:"3. Həyat təcrübəsi — vaxt deyilmir",
  t:"Həyatında nə vaxtsa bir şey etmisənsə, amma NƏ VAXT olduğunu demirsənsə, Present Perfect işlənir. Burada vacib olan vaxt yox, təcrübənin özüdür: etmisən, ya yox. ever (nə vaxtsa, heç) sualda, never (heç vaxt) isə təsdiq formada işlənir. Neçə dəfə etdiyini də demək olar: once, twice, three times.",
  ex:[["I have visited Turkey twice.","Türkiyədə iki dəfə olmuşam."],["Have you ever eaten sushi?","Heç suşi yemisən?"],["I've never ridden a horse.","Heç vaxt ata minməmişəm."]]},
 {h:"4. been yoxsa gone?",
  t:"go felinin iki V3 forması var və mənaları fərqlidir. been to — gedib qayıdıb, yəni orada olub (təcrübə). gone to — gedib və hələ oradadır, qayıtmayıb. Ona görə «heç Parisdə olmusan?» sualında həmişə been işlənir.",
  ex:[["I've been to London.","Londonda olmuşam (qayıtmışam)."],["Ali has gone to the bank.","Əli banka gedib (hələ oradadır)."],["Have you ever been to Paris?","Heç Parisdə olmusan?"]]},
 {h:"5. Yeni hadisə, nəticəsi indi var",
  t:"Bir şey təzəcə olubsa və onun nəticəsi İNDİ görünürsə, Present Perfect işlənir. Məsələn, pul kisəni itirmisən — indi də yoxdur. just (indicə) bu mənanı gücləndirir və have ilə V3-ün arasına girir. Vaxt deyilmir, çünki vacib olan indiki nəticədir.",
  ex:[["I've lost my wallet.","Pul kisəmi itirmişəm (indi yoxdur)."],["She has just finished her homework.","O, ev tapşırığını indicə bitirib."],["The taxi has arrived.","Taksi gəlib."]]},
 {h:"6. already və yet",
  t:"already «artıq» deməkdir: iş gözləniləndən tez olub. O, təsdiq cümlədə have ilə V3-ün arasına gəlir. yet iki mənada işlənir: inkarda «hələ» (hələ etməmişəm), sualda «artıq» (artıq etmisən?). yet həmişə cümlənin sonunda gəlir.",
  ex:[["I've already eaten.","Artıq yemişəm."],["I haven't finished yet.","Hələ bitirməmişəm."],["Have you finished yet?","Artıq bitirmisən?"]]},
 {h:"7. still — «hələ də»",
  t:"still «hələ də» deməkdir və bir şeyin gözləniləndən uzun davam etdiyini göstərir. Adi feldən əvvəl, am / is / are-dan sonra gəlir (g02-dəki tezlik sözləri kimi). İnkarda still köməkçidən əvvəl gəlir: I still haven't… Bu, yet-dən güclüdür və narazılıq bildirə bilər.",
  ex:[["It's 2 o'clock and he is still sleeping.","Saat ikidir, o hələ də yatır."],["I still live with my parents.","Hələ də valideynlərimlə yaşayıram."],["I still haven't finished my report.","Hələ də hesabatımı bitirməmişəm."]]},
 {h:"8. İndiyə qədər davam edir: How long?",
  t:"Keçmişdə başlayıb İNDİ də davam edən vəziyyət üçün Present Perfect işlənir. Azərbaycanca burada indiki zaman deyirik: «üç ildir burada yaşayıram». İngiliscə isə Present Simple yox, have + V3 lazımdır, çünki iş keçmişdən indiyə qədər uzanır. Müddəti soruşmaq üçün How long have you…? işlənir.",
  ex:[["I've lived here for three years.","Üç ildir burada yaşayıram."],["How long have you known him?","Onu nə vaxtdan tanıyırsan?"],["We've been married for ten years.","On ildir evliyik."]],
  no:"I live here for three years — səhvdir"},
 {h:"9. for, since, ago",
  t:"for, since və ago üçü də vaxtla bağlıdır, amma fərqli işlənir. for + müddət: nə qədər vaxt (for two hours). since + başlanğıc nöqtə: nə vaxtdan (since Monday, since 2020). for və since çox vaxt Present Perfect ilə gəlir. ago isə «əvvəl» deməkdir, keçmişdəki bir anı göstərir və Past Simple ilə işlənir.",
  tbl:[["for","for ten minutes, for three years"],["since","since 9 o'clock, since 2019, since I was a child"],["ago (Past Simple)","two days ago, a year ago"]],
  ex:[["She has worked here since 2020.","O, 2020-dən burada işləyir."],["They got married five years ago.","Onlar beş il əvvəl evləndilər."]]},
 {h:"10. Vaxt bəllidirsə — Past Simple",
  t:"Keçmiş vaxt deyilibsə və ya bəllidirsə (yesterday, last week, in 2019, ago, when I was a child), Present Perfect işlənmir, Past Simple işlənir. Çünki Present Perfect keçmişi indiyə bağlayır, bitmiş vaxt isə indiyə bağlı deyil. Azərbaycanca «görmüşəm» və «gördüm» bəzən eyni mənada işlənir, ingiliscə isə fərq ciddidir. When…? sualı da həmişə Past Simple ilə olur.",
  ex:[["I saw him yesterday.","Onu dünən gördüm."],["When did you buy your car?","Maşınını nə vaxt almısan?"]],
  no:"I have seen him yesterday — səhvdir"},
 {h:"11. Sual və inkar",
  t:"Present Perfect cümləsində köməkçi söz — have / has — var. g01-dəki qaydaya görə, köməkçi varsa, do / does / did lazım deyil. Sualda have / has «kim»-dən əvvələ keçir, inkarda haven't / hasn't olur. V3 öz yerində qalır.",
  ex:[["Have you seen this film?","Bu filmə baxmısan?"],["She hasn't called me.","O mənə zəng etməyib."],["Has he called you yet?","O sənə artıq zəng edib?"]],
  no:"Do you have seen this film? / She hasn't call me. — səhvdir"},
 {h:"12. Söhbət: əvvəl Perfect, sonra Simple",
  t:"Söhbət çox vaxt təcrübə sualı ilə başlayır: Have you ever…? Burada vaxt deyilmir, ona görə Present Perfect işlənir. Cavab «bəli» olanda detallar gəlir: nə vaxt, harada, necə. Vaxt artıq bəlli olduğu üçün detallar Past Simple ilə deyilir.",
  ex:[["Have you ever been to London? — Yes, I went there in 2023.","Londonda olmusan? — Bəli, 2023-də getdim."],["Have you ever lost your passport? — Yes, I lost it last summer.","Heç pasportunu itirmisən? — Bəli, keçən yay itirdim."],["Have you seen the new film? — Yes, I saw it on Friday.","Yeni filmə baxmısan? — Bəli, cümə günü baxdım."]]}
],
g09: [
 {h:"1. Modal fellər necə işləyir",
  t:"can, could, must, should, might, will modal fellər adlanır. Onların üç ümumi qaydası var. Birincisi, onlardan sonra sadə fel gəlir, to yoxdur. İkincisi, he / she / it ilə -s almırlar. Üçüncüsü, sual və inkarda do / does / did işlənmir: modal özü qabağa keçir və ya özünə not alır.",
  ex:[["She can speak French.","O fransızca danışa bilir."],["Can you help me?","Mənə kömək edə bilərsən?"],["You shouldn't worry.","Narahat olmamalısan."]],
  no:"can to swim / She cans / Do you can — səhvdir"},
 {h:"2. can / can't — bacarıq və imkan",
  t:"can iki əsas mənada işlənir: bacarmaq (üzə bilirəm) və imkanı olmaq (sabah gələ bilərəm). Forma hamı üçün eynidir: I can, she can. İnkarı can't və ya tam forma cannot-dur (bitişik yazılır). Sualda can «kim»-dən əvvələ keçir.",
  ex:[["I can swim.","Üzə bilirəm."],["We can't come tomorrow.","Sabah gələ bilmərik."],["Can you speak Russian? — Yes, I can.","Rusca danışa bilirsən? — Bəli."]]},
 {h:"3. could / couldn't — keçmişdə bacarıq",
  t:"could can-ın keçmiş formasıdır. Keçmişdə bir şeyi bacardığını və ya bacarmadığını demək üçün işlənir. İnkarı couldn't-dur. could həm də nəzakətli xahişdə işlənir (4-cü qayda), orada keçmiş mənası yoxdur.",
  ex:[["When I was five, I could read.","Beş yaşımda oxuya bilirdim."],["I couldn't sleep last night.","Dünən gecə yata bilmədim."],["Could you swim when you were a child?","Uşaq olanda üzə bilirdin?"]]},
 {h:"4. Can I…? Could you…? — icazə və xahiş",
  t:"İcazə istəmək üçün Can I…? işlənir: «… edə bilərəm?». Kimdənsə xahiş etmək üçün Can you…? və ya Could you…? işlənir. could daha nəzakətlidir, tanımadığın adama və rəsmi yerdə onu işlət. Burada could keçmiş mənası vermir.",
  ex:[["Can I use your phone?","Telefonundan istifadə edə bilərəm?"],["Could you open the window, please?","Pəncərəni aça bilərsiniz?"]]},
 {h:"5. must — çox vacib",
  t:"must danışanın özünün çox vacib saydığı işi bildirir: «mütləq etməliyəm». Yazılı qaydalarda, bildirişlərdə və qanunlarda da must işlənir. must-dan sonra sadə fel gəlir, to yoxdur. Kənar məcburiyyət (iş, qayda) üçün danışıqda daha çox have to işlənir (7-ci qayda).",
  ex:[["I must call my mother.","Anama mütləq zəng etməliyəm."],["You must wear a seatbelt.","Təhlükəsizlik kəmərini taxmalısan."],["Passengers must show their tickets.","Sərnişinlər biletlərini göstərməlidir."]]},
 {h:"6. mustn't — olmaz, qadağandır",
  t:"mustn't (= must not) «etmək olmaz, qadağandır» deməkdir. Bu, «lazım deyil» demək deyil — çox güclü qadağadır. Qaydalarda və ciddi xəbərdarlıqda işlənir. Azərbaycanca «…-mamalısan, olmaz» kimi deyirik.",
  ex:[["You mustn't use your phone in the exam.","İmtahanda telefondan istifadə etmək olmaz."],["You mustn't tell anyone.","Heç kimə deməməlisən."],["You mustn't park here.","Burada maşın saxlamaq olmaz."]]},
 {h:"7. have to — məcburiyyət (qayda, iş)",
  t:"have to kənar məcburiyyəti bildirir: iş, qanun, cədvəl, başqasının qərarı. he / she / it ilə has to işlənir. Bu, modal fel deyil, adi feldir: sual və inkarda do / does / did lazımdır. Keçmişdə had to olur (9-cu qayda).",
  ex:[["I have to work on Saturdays.","Şənbə günləri işləməliyəm."],["She has to wear a uniform.","O forma geyinməlidir."],["Do you have to get up early?","Tez durmalısan?"]]},
 {h:"8. don't have to — lazım deyil",
  t:"don't have to «lazım deyil, məcburi deyil» deməkdir: istəsən edərsən, istəməsən yox. mustn't isə «olmaz, qadağandır» deməkdir. İngiliscə bu iki forma oxşar görünür, amma mənaları tam fərqlidir. he / she / it ilə doesn't have to işlənir.",
  tbl:[["mustn't","olmaz, qadağandır"],["don't have to","lazım deyil, seçim səndədir"]],
  ex:[["You don't have to pay. It's free.","Pul ödəmək lazım deyil. Pulsuzdur."],["We don't have to get up early tomorrow.","Sabah tez durmağımız lazım deyil."]],
  no:"You mustn't pay — it's free (lazım deyil mənasında) — səhvdir"},
 {h:"9. had to — keçmişdə məcburiyyət",
  t:"must-un keçmiş forması yoxdur. Keçmişdə «məcbur idim, etməli oldum» demək üçün had to işlənir. had to hamı üçün eynidir. Sual və inkarda did gəlir: Did you have to…?, I didn't have to…",
  ex:[["I had to work late yesterday.","Dünən gec saata qədər işləməli oldum."],["Did you have to wait long?","Çox gözləməli oldun?"],["We didn't have to pay for the tickets.","Biletlər üçün pul ödəmək lazım olmadı."]],
  no:"I musted — səhvdir"},
 {h:"10. should — məsləhət",
  t:"should məsləhət vermək və fikir bildirmək üçün işlənir: «…-malısan, yaxşı olar». must-dan yumşaqdır: məcburiyyət yox, tövsiyədir. İnkarı shouldn't-dur. Kiminsə fikrini soruşanda Should I…? işlənir.",
  ex:[["You should see a doctor.","Həkimə getməlisən."],["You shouldn't eat so much sugar.","Bu qədər şəkər yeməməlisən."],["Should I call her?","Ona zəng edim?"]]},
 {h:"11. might / may — bəlkə",
  t:"might və may «bəlkə, ola bilər» deməkdir: bir şeyin ola biləcəyini deyirsən, amma əmin deyilsən. Bu mənada ikisi demək olar ki eynidir. Onlardan sonra sadə fel gəlir. İnkarı might not / may not-dur: «bəlkə … -maz».",
  ex:[["Take an umbrella. It might rain.","Çətir götür. Bəlkə yağış yağar."],["I might not come to the party.","Bəlkə məclisə gəlmədim."],["She may be at home now.","O, bəlkə də indi evdədir."]]},
 {h:"12. Qısa xülasə",
  t:"Hansı modal feli seçəcəyin nə demək istədiyindən asılıdır. Əvvəlcə özündən soruş: bu bacarıqdır, xahişdir, məcburiyyətdir, məsləhətdir, yoxsa ehtimal? Sonra cədvəldən uyğun sözü seç. Ən çox qarışdırılan cüt mustn't və don't have to-dur.",
  tbl:[["bacarıq","can / could"],["xahiş, icazə","can / could"],["çox vacib, qayda","must / have to"],["olmaz","mustn't"],["lazım deyil","don't have to"],["məsləhət","should"],["bəlkə","might / may"]],
  ex:[["You should rest, but you don't have to stay in bed.","İstirahət etməlisən, amma yataqda qalmağın lazım deyil."],["You must stop smoking. You mustn't smoke here.","Siqareti atmalısan. Burada siqaret çəkmək olmaz."],["It might rain, so you should take an umbrella.","Bəlkə yağış yağar, ona görə çətir götürməlisən."]]}
],
g25: [
 {h:"1. some- / any- / no- / every- sözləri",
  t:"some, any, no, every sözlərinə -body (və ya -one), -thing, -where artırılır və yeni sözlər düzəlir. -body / -one adam bildirir (kimsə), -thing şey bildirir (nəsə), -where yer bildirir (haradasa). somebody və someone eyni mənadır. Hansı başlanğıcın seçiləcəyi isə cümlənin təsdiq, sual və ya inkar olmasından asılıdır.",
  tbl:[["-body / -one (adam)","somebody, anybody, nobody, everybody"],["-thing (şey)","something, anything, nothing, everything"],["-where (yer)","somewhere, anywhere, nowhere, everywhere"]],
  ex:[["Somebody called.","Kimsə zəng etdi."],["Everything is ready.","Hər şey hazırdır."]]},
 {h:"2. somebody, something, somewhere — təsdiqdə",
  t:"Təsdiq cümləsində «kimsə, nəsə, haradasa» some- ilə deyilir. Bu sözlər adam, şey və ya yer bəlli olmayanda işlənir. Təklif və xahiş sualında da some- işlənir, çünki «hə» cavabı gözlənilir.",
  ex:[["There's somebody at the door.","Qapıda kimsə var."],["I want to eat something.","Nəsə yemək istəyirəm."],["Would you like something to drink?","Nəsə içmək istəyirsən?"]]},
 {h:"3. anybody, anything, anywhere — sual və inkarda",
  t:"Sualda və not olan cümlədə any- işlənir. Sualda bu sözlər «kimsə, nəsə» mənasını, inkarda isə «heç kim, heç nə, heç yer» mənasını verir. Azərbaycanca inkarda «heç» sözü əlavə edirik, ingiliscə isə any- formaları kifayət edir. any- təsdiq cümləsində də işlənə bilər, onda mənası «hər hansı, fərq etməz» olur.",
  ex:[["Is there anything in the box?","Qutuda nəsə var?"],["I didn't see anybody.","Heç kimi görmədim."],["I can't find my keys anywhere.","Açarlarımı heç yerdə tapa bilmirəm."]]},
 {h:"4. nobody, nothing, nowhere — ikiqat inkar yoxdur",
  t:"Azərbaycanca «Heç kim gəlmədi» deyirik — iki inkar var. İngiliscə nobody, nothing özü inkardır, ona görə fel TƏSDİQDƏ qalır. Ya not + any-, ya da no- — ikisi birlikdə yox.",
  tbl:[["Heç kim gəlmədi.","Nobody came."],["Heç nə etmədim.","I didn't do anything. / I did nothing."]],
  ex:[["Nobody called me today.","Bu gün heç kim zəng etmədi."],["What did you do? — Nothing.","Nə etdin? — Heç nə."]],
  no:"Nobody didn't come / I didn't do nothing — səhvdir"},
 {h:"5. no + isim, none — isimsiz",
  t:"no + isim «heç bir» deməkdir və özü inkardır, ona görə fel təsdiqdə qalır. İsim yoxdursa, no tək işlənmir — onun yerinə none gəlir. none «heç biri, heç nə» deməkdir və çox vaxt qısa cavabda işlənir.",
  ex:[["There are no chairs in the room.","Otaqda heç bir stul yoxdur."],["How many eggs are there? — None.","Neçə yumurta var? — Heç biri."],["I have no time today.","Bu gün heç vaxtım yoxdur."]]},
 {h:"6. everybody, everything — tək fel",
  t:"everybody «hamı» deməkdir və mənaca çox adamdır. Amma ingiliscə o, TƏK sayılır: is, has, feldə -s. Bu qayda -body, -one və -thing ilə bitən bütün sözlərə aiddir: somebody, nobody, everything, nothing. Azərbaycanca «hamı gəldilər» də deyə bilərik, ingiliscə isə yalnız tək forma düzdür.",
  ex:[["Everybody is here.","Hamı buradadır."],["Everything was perfect.","Hər şey əla idi."],["Everybody knows him.","Onu hamı tanıyır."]],
  no:"Everybody are — səhvdir"},
 {h:"7. every + tək isim",
  t:"every «hər» deməkdir və ondan sonra həmişə tək isim gəlir. Fel də tək olur: is, has, -s. Mənaca every hamını əhatə edir, amma qrammatik olaraq tək sayılır — everybody kimi. every day, every week ifadələri vərdiş göstərir və cümlənin sonunda gəlir (g02).",
  ex:[["Every student has a book.","Hər tələbənin kitabı var."],["I walk to work every day.","Hər gün işə piyada gedirəm."]],
  no:"every students — səhvdir"},
 {h:"8. all — «bütün, hamısı»",
  t:"all «bütün, hamısı» deməkdir. Ondan sonra cəm isim (all students) və ya all the + isim (all the students) gəlir. all + vaxt sözü bir dövrün hamısını göstərir: all day = bütün gün. every day isə «hər gün» deməkdir — mənaları fərqlidir.",
  ex:[["All the students passed the exam.","Bütün tələbələr imtahandan keçdi."],["I spent all day at home.","Bütün günü evdə keçirdim."],["All my friends live in Baku.","Bütün dostlarım Bakıda yaşayır."]]},
 {h:"9. both — «ikisi də»",
  t:"both «ikisi də» deməkdir və yalnız iki adam və ya iki şey haqqında işlənir. both-dan sonra fel cəm olur. Əvəzliklə both of us / both of them, isimlə both my brothers və ya both of my brothers deyilir. both adi feldən əvvəl, am / is / are-dan sonra da gələ bilər.",
  ex:[["Both of my brothers live abroad.","Qardaşlarımın ikisi də xaricdə yaşayır."],["Both of us are tired.","İkimiz də yorğunuq."]]},
 {h:"10. either — «hər hansı biri» (iki şeydən)",
  t:"either iki şeydən danışanda işlənir. Təsdiqdə və sualda «hansı olsa, fərq etməz» deməkdir. İnkarda (not … either) «heç biri» mənasını verir. either of + cəm isim də işlənir: either of them.",
  ex:[["Tea or coffee? — Either. I don't mind.","Çay, yoxsa qəhvə? — Fərq etməz."],["You can take either bus.","İki avtobusdan istədiyinə minə bilərsən."],["I don't like either of them.","Onların heç birini bəyənmirəm."]]},
 {h:"11. neither — «heç biri» (iki şeydən)",
  t:"neither «heç biri» deməkdir və iki şey haqqında işlənir. neither özü inkardır, ona görə fel təsdiq formada qalır, not əlavə olunmur. neither of + cəm isim işlənəndə fel adətən tək formada gəlir, danışıqda cəm də eşidilir. İkidən çox şey üçün none işlənir.",
  ex:[["Neither of my parents speaks English.","Valideynlərimin heç biri ingiliscə danışmır."],["Neither of my two sisters is married.","İki bacımın heç biri evli deyil."]]}
],
g21: [
 {h:"1. Sual sözləri",
  t:"Sual sözləri sualın ən əvvəlində durur və nəyi soruşduğunu göstərir. how başqa sözlərlə birləşib yeni sual sözləri düzəldir: how many, how old, how long. Sual sözündən sonra adi sual sırası gəlir (2-ci qayda). Cədvəldə ən çox işlənənlər var.",
  tbl:[["what","nə?"],["where","harada? hara?"],["when","nə vaxt?"],["who","kim? kimi?"],["why","niyə?"],["which","hansı? (az seçimdən)"],["whose","kimin?"],["how","necə?"],["how many / how much","neçə? / nə qədər?"],["how old / how long / how often / how far","neçə yaş / nə qədər vaxt / nə qədər tez-tez / nə qədər uzaq"]],
  ex:[["Whose bag is this?","Bu kimin çantasıdır?"],["How often do you cook?","Nə qədər tez-tez yemək bişirirsən?"],["Why are you late?","Niyə gecikmisən?"]]},
 {h:"2. Sıra: sual sözü + köməkçi + kim + fel",
  t:"Sual sözü olan bütün suallarda sıra eynidir: sual sözü → köməkçi söz → kim → əsas fel. Köməkçi söz zamandan asılıdır: do / does / did, am / is / are, was / were, have / has, will, can. Köməkçi həmişə «kim»-dən əvvəl gəlir. Cümlədə köməkçi yoxdursa, do / does / did əlavə olunur (g01).",
  ex:[["Where do you work?","Harada işləyirsən?"],["What are you doing?","Nə edirsən?"],["Where have you been?","Harada olmusan?"],["What can I do?","Nə edə bilərəm?"]],
  no:"Where you work? / What you are doing? — səhvdir"},
 {h:"3. «Kim etdi?» — işi görəni soruşanda do yoxdur",
  t:"who və ya what İŞİ GÖRƏNİ soruşursa, cümlə adi sıradadır və do / does / did işlənmir. Burada who özü «kim» yerində durur, ona görə köməkçiyə ehtiyac yoxdur. Fel öz formasında qalır: keçmişdə called, happened; indiki zamanda isə -s ilə: works, lives. Azərbaycanca «Sənə kim zəng etdi?» — bu sual işi görəni soruşur.",
  ex:[["Who called you?","Sənə kim zəng etdi?"],["What happened?","Nə oldu?"],["Who lives in this house?","Bu evdə kim yaşayır?"]],
  no:"Who did call you? / What did happen? — səhvdir"},
 {h:"4. «Kimə, kimi, nəyi?» — do lazımdır",
  t:"who işi görəni yox, işin yönəldiyi adamı soruşursa (kimi? kimə? kimlə?), adi sual qaydası işləyir. Yəni do / does / did lazımdır və «kim» yerində başqa söz (you, she) durur. what üçün də eyni qayda var: «Nə oldu?» işi görəni soruşur — do yoxdur; «Nə aldın?» isə səni soruşur — did var. Cədvəldə iki sualın fərqinə bax.",
  tbl:[["Who called you?","Sənə KİM zəng etdi?"],["Who did you call?","Sən KİMƏ zəng etdin?"]],
  ex:[["Who did you meet at the party?","Məclisdə kimlə tanış oldun?"],["What did you buy?","Nə aldın?"],["Who does she live with?","O kimlə yaşayır?"]]},
 {h:"5. Ön söz sualın sonunda",
  t:"Azərbaycanca «Kimlə danışırsan?», «Haralısan?» deyirik — şəkilçi sual sözünə yapışır. İngiliscə isə ön söz (to, from, for, at, about, with) çox vaxt sualın SONUNA keçir. Sual sözü əvvəldə qalır, ön söz isə felin arxasından gəlir. Danışıqda bu, ən təbii formadır.",
  ex:[["Where are you from?","Haralısan?"],["Who are you talking to?","Kimlə danışırsan?"],["What are you looking at?","Nəyə baxırsan?"],["Who is this present for?","Bu hədiyyə kimə görədir?"]]},
 {h:"6. What … like? — «necədir?»",
  t:"Bir şeyin və ya adamın necə olduğunu, təsvirini soruşmaq üçün What … like? işlənir. Burada like «xoşlamaq» deyil, «kimi, necə» deməkdir. Ona görə cavabda I like yox, təsvir gəlir. Sıra belədir: What + is / was + kim + like?",
  ex:[["What is your new flat like? — It's small but nice.","Yeni mənzilin necədir? — Kiçik, amma gözəldir."],["What was the weather like?","Hava necə idi?"]],
  no:"How is the weather like? — səhvdir (What is the weather like? və ya How is the weather?)"},
 {h:"7. What yoxsa Which?",
  t:"which seçim az və bəlli olanda işlənir: bu ikisindən, bu üçündən hansı? what isə seçim çox və ya açıq olanda işlənir. Hər ikisi Azərbaycancaya «hansı» kimi tərcümə olunur, ona görə qarışdırılır. which of + cəm isim də işlənir: which of these.",
  ex:[["Which bus goes to the centre — the 5 or the 12?","Mərkəzə hansı avtobus gedir — 5, yoxsa 12?"],["What music do you like?","Hansı musiqini sevirsən?"],["Which is your car — the red one or the white one?","Sənin maşının hansıdır — qırmızı, yoxsa ağ?"]]},
 {h:"8. What + isim, How + sifət",
  t:"what çox vaxt isimlə birləşir və «hansı, nə cür» mənası verir: what time, what colour, what kind of. how isə sifət və ya zərflə birləşir və «nə qədər» mənası verir: how old, how big, how far, how often. Azərbaycanca hər ikisi «neçə», «nə qədər» ola bilər. Qayda sadədir: arxasından isim gəlirsə — what, sifət gəlirsə — how.",
  ex:[["What time does the shop open?","Mağaza saat neçədə açılır?"],["How far is the airport?","Hava limanı nə qədər uzaqdır?"],["What colour is your car?","Maşının hansı rəngdədir?"]]},
 {h:"9. How long does it take?",
  t:"Bir işin nə qədər vaxt apardığını soruşmaq üçün How long does it take (to …)? işlənir. Burada it «kim» yerində durur, take isə «vaxt aparmaq» deməkdir. Cavab It takes + vaxt formasında olur. Keçmişdə How long did it take…? deyilir.",
  ex:[["How long does it take to get to the airport?","Hava limanına getmək nə qədər vaxt aparır?"],["It takes about 30 minutes.","Təxminən 30 dəqiqə çəkir."]]},
 {h:"10. Dolayı sual — sıra adi cümlə kimidir",
  t:"Nəzakətli soruşanda sual Do you know…? və ya Can you tell me…? ilə başlayır. Ondan sonrakı hissə sual sırası ilə yox, adi cümlə sırası ilə gəlir: sual sözü + kim + fel. do / does / did burada işlənmir. Bu forma küçədə yol soruşanda və rəsmi yerlərdə çox faydalıdır.",
  tbl:[["Where is the station?","Do you know where the station is?"],["What time does the film start?","Can you tell me what time the film starts?"]],
  ex:[["Do you know where the station is?","Stansiyanın harada olduğunu bilirsən?"],["Can you tell me what time the film starts?","Filmin saat neçədə başladığını deyə bilərsən?"]],
  no:"Do you know where is the station? — səhvdir"},
 {h:"11. I don't know what… / I wonder where…",
  t:"Cümlənin içində sual sözü gələndə (I don't know where…, I wonder what…, I'm not sure when…) sual sırası işlənmir. Sual sözündən sonra adi cümlə sırası gəlir: kim + fel. do / does / did də işlənmir. Bu, dolayı sual qaydası ilə eynidir (10-cu qayda).",
  ex:[["I don't know what he wants.","Onun nə istədiyini bilmirəm."],["I don't know where she lives.","Onun harada yaşadığını bilmirəm."],["I wonder what time it is.","Görəsən, saat neçədir."]],
  no:"I don't know where does she live — səhvdir"},
 {h:"12. Do you know if…? — bəli/xeyr sualı",
  t:"Sual sözü olmayan sualı (bəli / xeyr sualı) dolayı soruşanda if işlənir. if burada «…-ıb-…-madığını» mənasını verir. if-dən sonra yenə adi cümlə sırası gəlir, do / does / did işlənmir. if əvəzinə whether də işlənə bilər.",
  ex:[["Is the bank open? → Do you know if the bank is open?","Bank açıqdır? → Bankın açıq olub-olmadığını bilirsən?"],["Do you know if Ali is at home?","Əlinin evdə olub-olmadığını bilirsən?"],["Can you tell me if this bus goes to the airport?","Bu avtobusun hava limanına gedib-getmədiyini deyə bilərsən?"]]}
],
g22: [
 {h:"1. Qısa cavab: Yes, I do / No, she isn't",
  t:"İngiliscə tək «Yes» və ya «No» quru, bəzən kobud səslənir. Ona görə qısa cavab verilir: Yes / No + kim + köməkçi söz. Köməkçini sualın birinci sözündən götür. Əsas fel cavabda təkrarlanmır.",
  ex:[["Do you like coffee? — Yes, I do.","Qəhvəni sevirsən? — Bəli."],["Is she married? — No, she isn't.","O evlidir? — Xeyr."],["Did you see it? — Yes, I did.","Onu gördün? — Bəli."],["Can you swim? — No, I can't.","Üzə bilirsən? — Xeyr."]],
  no:"Yes, I like. — səhvdir"},
 {h:"2. «Bəli» cavabında qısaltma olmur",
  t:"Qısa «bəli» cavabı köməkçi sözlə bitir. Belə cümlənin sonunda I'm, she's, they've kimi qısaltma işlənmir, çünki sonda gələn köməkçi vurğu ilə tam deyilir. «Xeyr» cavabında isə qısaltma normaldır, çünki sonda not gəlir: isn't, aren't, haven't.",
  ex:[["Are you ready? — Yes, I am.","Hazırsan? — Bəli."],["Have you finished? — Yes, I have.","Bitirmisən? — Bəli."],["Is it far? — No, it isn't.","Uzaqdır? — Xeyr."]],
  no:"Yes, I'm. / Yes, she's. — səhvdir"},
 {h:"3. Köməkçi sözü necə seçim?",
  t:"Qısa cavabda, «mən də» cümləsində və quyruq sualında köməkçi söz eyni qaydayla seçilir. Cümlədə köməkçi (am / is / are, was / were, can, will, have) varsa, onu götür. Cümlədə köməkçi yoxdursa, do / does / did işlət. Zaman da eyni qalmalıdır: keçmiş cümləyə keçmiş köməkçi.",
  tbl:[["am / is / are, was / were","am, is, are, was, were"],["can, will, should …","can, will, should …"],["have / has + V3","have, has"],["başqa hər şey (adi fel)","do / does / did"]],
  ex:[["Is he a doctor? — Yes, he is.","O həkimdir? — Bəli."],["She has finished. — So have I.","O bitirib. — Mən də."]]},
 {h:"4. Feli təkrar etməmək üçün köməkçi",
  t:"Bir cümlədə eyni feli iki dəfə deməmək üçün ikinci dəfə yalnız köməkçi söz işlənir. Köməkçi 3-cü qaydaya görə seçilir: birinci hissədə nə varsa, onu təkrar et. Azərbaycanca feli təkrar edirik («sevmirəm, amma o sevir»), ingiliscə isə əsas fel atılır. Bu, xüsusən but ilə qurulan cümlələrdə çox işlənir.",
  ex:[["I don't like fish, but my wife does.","Mən balığı sevmirəm, amma həyat yoldaşım sevir."],["She can't drive, but I can.","O maşın sürə bilmir, amma mən bilirəm."],["He didn't come, but his wife did.","O gəlmədi, amma həyat yoldaşı gəldi."]]},
 {h:"5. I think so / I hope so / I don't think so",
  t:"Bütün cavabı təkrar etməmək üçün so işlənir: I think so = «məncə, hə», I hope so = «ümid edirəm, hə». İnkar üçün I don't think so deyilir — «məncə, yox». Ümidin inkarı isə I hope not-dur, I don't hope so deyilmir.",
  ex:[["Is the shop open? — I think so.","Mağaza açıqdır? — Məncə, hə."],["Will it rain? — I don't think so.","Yağış yağacaq? — Məncə, yox."],["Will you pass? — I hope so.","Keçəcəksən? — Ümid edirəm."]],
  no:"I don't hope so. — səhvdir (I hope not)"},
 {h:"6. too və either — «də» sonda",
  t:"too və either «də» mənasını verir və cümlənin sonunda gəlir. Təsdiq cümləsində too işlənir: «mən də». İnkar cümləsində isə either işlənir: «mən də …-mirəm». Azərbaycanca hər ikisində «da / də» deyirik, ona görə ingiliscə cümlənin inkar olub-olmadığına bax.",
  ex:[["I'm tired, and my sister is tired too.","Mən yorğunam, bacım da yorğundur."],["I'm not hungry, and Ali isn't hungry either.","Mən ac deyiləm, Əli də ac deyil."]],
  no:"I'm not hungry too — səhvdir"},
 {h:"7. So am I / So do I — «Mən də»",
  t:"Kiminsə təsdiq cümləsinə «mən də» demək üçün So + köməkçi + I işlənir. Burada sıra suala bənzəyir: köməkçi «kim»-dən əvvəl gəlir. Köməkçi 3-cü qaydaya görə seçilir: birinci cümlədə am varsa — am, can varsa — can, adi fel varsa — do / does / did. Azərbaycanca «Mən də» iki sözdür, ingiliscə isə üç söz lazımdır.",
  ex:[["I'm hungry. — So am I.","Acmışam. — Mən də."],["I live in Baku. — So do I.","Bakıda yaşayıram. — Mən də."],["I went to the cinema. — So did I.","Kinoya getdim. — Mən də."],["I can swim. — So can I.","Üzə bilirəm. — Mən də."]],
  no:"I'm tired. — So do I. — səhvdir"},
 {h:"8. Neither am I / Neither do I — «Mən də yox»",
  t:"Kiminsə inkar cümləsinə «mən də (etmirəm)» demək üçün Neither + köməkçi + I işlənir. Burada köməkçi TƏSDİQ formasındadır, çünki neither özü inkardır. Azərbaycanca hər iki halda «Mən də» deyirik, ona görə So yoxsa Neither seçmək üçün birinci cümləyə bax: təsdiqdirsə So, inkardırsa Neither. Danışıqda Neither yerinə Nor da işlənir.",
  ex:[["I don't smoke. — Neither do I.","Siqaret çəkmirəm. — Mən də."],["I've never been to Paris. — Neither have I.","Heç Parisdə olmamışam. — Mən də."],["I didn't like the film. — Neither did I.","Filmi bəyənmədim. — Mən də."]],
  no:"Neither I do / Neither don't I — səhvdir"},
 {h:"9. Maraq bildirən qısa sual: Are you? Do you?",
  t:"Söhbətdə maraq və ya təəccüb bildirmək üçün qısa sual verilir: köməkçi + kim. Azərbaycanca bunu «Elə?», «Doğrudan?» deyirik. Köməkçi 3-cü qaydaya görə seçilir: təsdiqə təsdiq, inkara inkar sualı verilir. Bu sual söhbəti davam etdirir və maraqla qulaq asdığını göstərir.",
  ex:[["I live in Ganja. — Do you? I live there too!","Gəncədə yaşayıram. — Elə? Mən də orada yaşayıram!"],["I'm not hungry. — Aren't you?","Ac deyiləm. — Elə?"],["I've been to China. — Have you? When?","Çində olmuşam. — Elə? Nə vaxt?"]]},
 {h:"10. Quyruq sual: …, isn't it?",
  t:"Razılıq gözləyəndə cümlənin sonuna qısa sual əlavə olunur (Azərbaycanca «elə deyilmi?»). Təsdiq cümləyə inkar quyruq, inkar cümləyə təsdiq quyruq gəlir. Köməkçi 3-cü qaydaya görə seçilir.",
  tbl:[["It's cold,","isn't it?"],["You live in Baku,","don't you?"],["She can't drive,","can she?"],["He doesn't smoke,","does he?"]],
  ex:[["It's cold, isn't it?","Soyuqdur, elə deyilmi?"],["You live in Baku, don't you?","Bakıda yaşayırsan, elə deyilmi?"],["He doesn't smoke, does he?","O siqaret çəkmir, elə deyilmi?"]],
  no:"You like music, isn't it? — səhvdir"},
 {h:"11. Quyruqda «kim» əvəzliklə",
  t:"Quyruq sualda ad təkrar olunmur, onun yerinə əvəzlik işlənir: kişi üçün he, qadın üçün she, əşya üçün it, çox adam və ya şey üçün they. Köməkçi də birinci hissəyə uyğun seçilir. Cümlə I am ilə başlayırsa, quyruq aren't I? olur.",
  ex:[["Leyla is a teacher, isn't she?","Leyla müəllimdir, elə deyilmi?"],["The film wasn't good, was it?","Film yaxşı deyildi, elə deyilmi?"],["Your parents live in Ganja, don't they?","Valideynlərin Gəncədə yaşayır, elə deyilmi?"],["I'm late, aren't I?","Gecikmişəm, elə deyilmi?"]]}
],
g10: [
 {h:"1. İki fel yan-yana gələndə",
  t:"Azərbaycanca «oxumağı sevirəm», «getmək istəyirəm» deyirik. İngiliscə ikinci fel üç formada ola bilər: sadə (go), to + fel (to go), -ing (going). Hansının gələcəyini BİRİNCİ fel müəyyən edir.",
  tbl:[["modal, do/does/did, let, make + …","sadə fel: can go, let me go"],["want, need, decide … + …","to + fel: want to go"],["enjoy, finish, mind … + …","-ing: enjoy going"]],
  ex:[["I can go.","Gedə bilərəm."],["I want to go.","Getmək istəyirəm."],["I enjoy going there.","Ora getməyi xoşlayıram."]]},
 {h:"2. Sadə fel: modal və do/does/did-dən sonra",
  t:"Modal fellərdən (can, must, should, will, might) və do / does / did-dən sonra ikinci fel sadə formada gəlir. to yoxdur, -s yoxdur, -ing yoxdur. Bunu g01 və g09-dan artıq bilirsən. Bu qaydanın istisnası yoxdur.",
  ex:[["I can't come.","Gələ bilmirəm."],["Did you see it?","Onu gördün?"],["She doesn't like it.","O bunu sevmir."]]},
 {h:"3. -ing gələn fellər",
  t:"Bu siyahıdakı fellərdən sonra ikinci fel HƏMİŞƏ -ing formasında gəlir: enjoy, finish, mind, stop, avoid, keep, practise, suggest, give up. Burada to + fel işlənmir. Bu fellərin ümumi qaydası yoxdur, ona görə siyahını əzbərləmək lazımdır. Azərbaycanca bu yerdə «-mağı» deyirik («bişirməyi xoşlayıram»), ingiliscə isə -ing.",
  ex:[["I enjoy cooking.","Yemək bişirməyi xoşlayıram."],["She finished working at 10.","O, işi saat 10-da bitirdi."],["Would you mind opening the window?","Pəncərəni açmağınız mümkündür?"],["Stop talking, please.","Danışmağı dayandırın, zəhmət olmasa."]],
  no:"I enjoy to cook — səhvdir"},
 {h:"4. to + fel gələn fellər",
  t:"Bu siyahıdakı fellərdən sonra ikinci fel to + fel formasında gəlir: want, need, decide, hope, plan, learn, agree, promise, forget, offer, refuse, would like. Burada -ing işlənmir. Bu fellərin çoxu gələcəyə yönəlmiş istək, plan və ya qərar bildirir. Azərbaycanca çox vaxt «-maq» deyirik: «almaq istəyirəm».",
  ex:[["I want to buy a new car.","Yeni maşın almaq istəyirəm."],["We decided to rent a flat.","Mənzil kirayələməyə qərar verdik."],["I hope to see you soon.","Səni tezliklə görməyə ümid edirəm."],["She agreed to help me.","O mənə kömək etməyə razı oldu."]],
  no:"I decided learning — səhvdir"},
 {h:"5. like, love, hate, start — ikisi də olar",
  t:"like, love, hate, prefer, start, begin fellərindən sonra həm -ing, həm də to + fel düzdür, məna demək olar ki dəyişmir. Amma would like (istərdim), would love və would prefer-dən sonra yalnız to + fel gəlir. Səbəb budur: would like «indi istəyirəm» deməkdir, like isə «ümumiyyətlə xoşlayıram».",
  ex:[["I like reading. / I like to read.","Oxumağı xoşlayıram."],["It started raining. / It started to rain.","Yağış yağmağa başladı."],["I'd like to read this book.","Bu kitabı oxumaq istərdim."]]},
 {h:"6. Ön sözdən sonra -ing",
  t:"Ön sözdən (in, at, of, about, for, before, after, without) sonra fel gələndə həmişə -ing formasında olur. to + fel və ya sadə fel burada işlənmir. Azərbaycanca bu yerlərdə «-maqdan, -mağa, -dığı üçün» deyirik. Bu qayda sifət + ön söz birləşmələrində də işləyir: good at, interested in, tired of.",
  ex:[["He's good at cooking.","O, yemək bişirməyi bacarır."],["I'm interested in learning Spanish.","İspan dilini öyrənməklə maraqlanıram."],["Thank you for helping me.","Mənə kömək etdiyin üçün sağ ol."],["I'm tired of waiting.","Gözləməkdən yoruldum."],["I'm thinking about changing my job.","İşimi dəyişmək haqqında düşünürəm."]],
  no:"good at cook / thank you for help me — səhvdir"},
 {h:"7. -ing cümlənin əvvəlində",
  t:"Bir işin özündən danışanda -ing forması isim kimi işlənir və cümlənin əvvəlində, «kim» yerində dura bilər. Azərbaycanca bu «-maq» formasıdır: «gəzmək faydalıdır». Bu halda fel tək olur: is, takes. to + fel ilə başlamaq da mümkündür, amma -ing daha təbiidir.",
  ex:[["Walking is good for your health.","Piyada gəzmək sağlamlıq üçün faydalıdır."],["Learning English takes time.","İngilis dilini öyrənmək vaxt aparır."],["Smoking is bad for you.","Siqaret çəkmək zərərlidir."]]},
 {h:"8. Məqsəd: to + fel = «… üçün»",
  t:"Bir işi NİYƏ, hansı məqsədlə etdiyini demək üçün to + fel işlənir. Azərbaycanca bu, «almaq üçün», «öyrənmək üçün» mənasıdır. for + fel bu mənada işlənmir. for-dan sonra isə isim gələ bilər: for a coffee, for work.",
  ex:[["I went to the bank to get some money.","Pul götürmək üçün banka getdim."],["I came to Baku to learn English.","İngilis dili öyrənmək üçün Bakıya gəldim."]],
  no:"I went to the bank for get money — səhvdir"},
 {h:"9. want / ask / tell + adam + to + fel",
  t:"Başqasının nəsə etməsini istəyəndə want + adam + to + fel işlənir. ask (xahiş etmək) və tell (demək, tapşırmaq) də eyni quruluşla işlənir. Adam me, him, her formasında gəlir (g20). Azərbaycanca «etməyimi istəyir» deyirik, amma ingiliscə burada that + cümlə işlənmir.",
  ex:[["My boss wants me to finish the report.","Müdirim hesabatı bitirməyimi istəyir."],["He asked me to call him.","Ona zəng etməyimi xahiş etdi."],["The doctor told me not to drink coffee.","Həkim mənə qəhvə içməməyi dedi."]],
  no:"She wants that I help her — səhvdir"},
 {h:"10. «…-mamağı»: not to + fel",
  t:"to + fel formasını inkar etmək üçün not to-dan əvvəl gəlir: not to go. Azərbaycanca bu «getməməyə, gecikməməyi» deməkdir. Burada don't işlənmir. not əsas felə yox, to-lu hissəyə aiddir.",
  ex:[["I decided not to go.","Getməməyə qərar verdim."],["She told me not to be late.","O mənə gecikməməyi dedi."],["Try not to worry.","Narahat olmamağa çalış."]],
  no:"She told me don't be late. — səhvdir (not to be late)"},
 {h:"11. let və make + adam + sadə fel",
  t:"let «icazə vermək», make isə «məcbur etmək, …-dırmaq» deməkdir. Bu fellərdən sonra əvvəl adam, sonra sadə fel gəlir — to yoxdur. Azərbaycanca make çox vaxt «ağlatdı, güldürdü» kimi şəkilçi ilə deyilir. Diqqət: let ilə let's (təklif) fərqlidir.",
  ex:[["My parents let me go out.","Valideynlərim çölə çıxmağıma icazə verdilər."],["The film made me cry.","Film məni ağlatdı."],["My boss made me work late.","Müdirim məni gec saata qədər işləməyə məcbur etdi."]],
  no:"made me to cry — səhvdir"},
 {h:"12. Sifət + to + fel",
  t:"Sifət bir işin necə olduğunu (asan, çətin, xoş, vacib) və ya insanın bu iş barədə hissini (şad, hazır) bildirirsə, ondan sonra gələn fel to + fel formasında olur. Azərbaycanca «öyrənmək asandır», «kömək etməyə şadam» deyirik. It's + sifət + to + fel quruluşu g19-da da var.",
  ex:[["It's easy to learn.","Öyrənmək asandır."],["I'm happy to help.","Kömək etməyə şadam."],["I'm ready to start.","Başlamağa hazıram."]]}
],
g26: [
 {h:"1. Bu beş fel çox işlənir",
  t:"go, get, do, make, have ingilis dilinin ən çox işlənən felləridir. Onlar başqa sözlərlə hazır birləşmələr düzəldir. Bu birləşmələri tərcümə ilə yox, bütöv əzbərləmək lazımdır.",
  tbl:[["go","go home, go shopping, go for a walk"],["get","get up, get a job, get tired, get home"],["do","do homework, do the shopping"],["make","make a mistake, make tea"],["have","have breakfast, have a shower"]],
  ex:[["I get up at 7 and have breakfast.","Saat 7-də durub səhər yeməyi yeyirəm."],["Then I do my homework.","Sonra ev tapşırığımı edirəm."]]},
 {h:"2. go to + yer, go home",
  t:"Bir yerə getmək üçün go to + yer işlənir. Amma home sözündən əvvəl to işlənmir: go home. Tətilə getmək go on holiday, işgüzar səfərə getmək go on a business trip deyilir. Keçmişdə go → went olur.",
  ex:[["I go to the gym on Mondays.","Bazar ertəsi idman zalına gedirəm."],["Let's go home.","Gəl evə gedək."],["We're going on holiday next week.","Gələn həftə tətilə gedirik."]],
  no:"go to home — səhvdir"},
 {h:"3. go + -ing — idman və əyləncə",
  t:"Bəzi idman və əyləncə fəaliyyətləri üçün go + -ing işlənir: go shopping, go swimming, go running, go fishing, go skiing. Bu birləşmələrdə arada to və ya the yoxdur. Azərbaycanca «üzməyə getmək» deyirik və «-mağa» to kimi görünür, amma ingiliscə to yazılmır. Keçmişdə go → went olur.",
  ex:[["We go swimming every Sunday.","Hər bazar günü üzməyə gedirik."],["She went shopping yesterday.","O dünən alış-verişə getdi."],["Do you want to go running tomorrow?","Sabah qaçmağa getmək istəyirsən?"]],
  no:"go to swimming — səhvdir"},
 {h:"4. go for a … — gəzinti, qəhvə",
  t:"go for a + isim qısa müddətlik fəaliyyət üçün işlənir: go for a walk (gəzintiyə çıxmaq), go for a run (qaçışa çıxmaq), go for a drive (maşınla gəzməyə çıxmaq), go for a coffee (qəhvə içməyə getmək). Burada a mütləqdir. Mənası «bir az … etməyə çıxmaq»-dır. Bu birləşmələri bütöv yadda saxla.",
  ex:[["Let's go for a walk.","Gəl gəzintiyə çıxaq."],["We went for a drive along the sea.","Dəniz boyunca maşınla gəzməyə çıxdıq."],["Shall we go for a coffee after work?","İşdən sonra qəhvə içməyə gedək?"]]},
 {h:"5. do — iş, vəzifə, ümumi fəaliyyət",
  t:"do ümumiyyətlə «iş görmək» deməkdir: ev işləri, dərs, tapşırıq, idman. Nəticədə yeni bir şey yaranmırsa, çox vaxt do işlənir. Bu birləşmələri əzbərlə: do homework, do the shopping, do the washing, do the cleaning, do exercise, do a course, do your best, do a job. What do you do? sualı «Nə işləyirsən?» deməkdir.",
  ex:[["I need to do my homework.","Ev tapşırığımı etməliyəm."],["Who does the shopping in your family?","Ailənizdə alış-verişi kim edir?"],["What do you do? — I'm an engineer.","Nə işləyirsən? — Mühəndisəm."]]},
 {h:"6. make — düzəltmək, yaratmaq",
  t:"make bir şey yaratmaq, hazırlamaq deməkdir: nəticədə yeni bir şey əmələ gəlir (çay, tort, səs-küy, qərar). Bu birləşmələri əzbərlə: make tea, make a cake, make dinner, make a mistake, make a decision, make money, make friends, make a noise, make a phone call, make plans. «Səhv etmək» ingiliscə həmişə make a mistake-dir, do yox. Azərbaycanca hər ikisi «etmək» olduğu üçün ən çox bu cüt qarışdırılır.",
  ex:[["Can you make a cup of tea?","Bir stəkan çay dəmləyə bilərsən?"],["I made a mistake.","Səhv etdim."],["He makes a lot of money.","O çox pul qazanır."]],
  no:"do a mistake / make homework — səhvdir"},
 {h:"7. have — «yemək, etmək» mənasında",
  t:"have «sahib olmaq» mənasından başqa, bəzi gündəlik işlər üçün də işlənir: have breakfast / lunch / dinner, have a shower, have a rest, have a party, have a good time, have a look. Bu mənada have «etmək, yemək, keçirmək» deməkdir. Belə have adi iş felidir və -ing ala bilər. Sual və inkarda do / does / did lazımdır, have got isə burada işlənmir.",
  ex:[["I always have a shower in the morning.","Səhər həmişə duş qəbul edirəm."],["We had a great time.","Çox gözəl vaxt keçirdik."],["What time do you have lunch?","Saat neçədə nahar edirsən?"]]},
 {h:"8. have got — «var» (Britaniya)",
  t:"Danışıqda «var» üçün have got / has got də işlənir, xüsusən Britaniyada. Mənası have / has ilə eynidir. Sual Have you got…?, inkar haven't got formasındadır. Burada do işlənmir, çünki have köməkçi rolundadır. Keçmişdə isə had got yox, sadəcə had işlənir.",
  ex:[["I've got a new phone.","Yeni telefonum var."],["Have you got a pen?","Qələmin var?"],["She hasn't got a car.","Onun maşını yoxdur."]]},
 {h:"9. get + isim = almaq, əldə etmək",
  t:"get + isim çox vaxt «almaq, tapmaq, qəbul etmək» deməkdir. Danışıqda buy, receive, find yerinə tez-tez get işlənir. Keçmişdə get → got olur. Dəqiq mənanı cümlənin qalanı göstərir: get a job = iş tapmaq, get a message = mesaj almaq.",
  ex:[["She got a new job.","O yeni iş tapdı."],["Did you get my message?","Mesajımı aldın?"],["I'll get some bread on the way home.","Evə gedərkən çörək alaram."]]},
 {h:"10. get + sifət = «olmaq» (dəyişmək)",
  t:"Bir vəziyyətin dəyişdiyini — əvvəl belə deyildi, indi belə olur — demək üçün get + sifət işlənir. Azərbaycanca bunu çox vaxt bir fel ilə deyirik: «yorulmaq, acmaq, qaralmaq». Ən çox işlənənlər: get tired, get hungry, get cold, get dark, get better, get worse. get married «evlənmək» deməkdir; be married isə «evli olmaq» vəziyyətidir.",
  ex:[["It's getting dark.","Qaranlıq düşür."],["I'm getting hungry.","Acıram."],["They got married last year.","Onlar keçən il evləndilər."]],
  no:"She is married last year. — səhvdir (She got married last year.)"},
 {h:"11. get + yer = çatmaq; get up, get on/off",
  t:"get + yer «çatmaq» deməkdir: get home, get to work. home sözündən əvvəl to yoxdur. get up yerdən durmaq deməkdir. Nəqliyyatda avtobus, qatar, təyyarə üçün get on / get off, maşın və taksi üçün get in / get out of işlənir.",
  ex:[["What time did you get home?","Evə saat neçədə çatdın?"],["I get up at 7.","Saat 7-də dururam."],["Get off the bus at the next stop.","Növbəti dayanacaqda avtobusdan düş."]]}
],
g11: [
 {h:"1. Ön söz şəkilçinin yerini tutur",
  t:"Azərbaycanca «evdə, saat beşdə, Bakıya» deyirik — şəkilçi sözün sonuna yapışır. İngiliscə isə ayrıca kiçik söz (ön söz) sözdən ƏVVƏL gəlir: at home, at five, to Baku. Hər şəkilçinin ingiliscə bir dəqiq qarşılığı yoxdur: «-da» bəzən in, bəzən on, bəzən at olur. Ona görə seçim aşağıdakı qaydalarla edilir.",
  ex:[["at home","evdə"],["in Baku","Bakıda"],["to Baku","Bakıya"]]},
 {h:"2. Vaxt: at, on, in",
  t:"Vaxt üçün üç əsas ön söz var və seçim vaxtın ölçüsündən asılıdır. at dəqiq vaxt, saat üçündür. on gün və tarix üçündür. in daha uzun dövr üçündür: ay, il, fəsil və günün hissələri (in the morning). İstisnalar: at night, at the weekend.",
  tbl:[["at","at 5 o'clock, at night, at noon, at the weekend"],["on","on Monday, on 5 May, on my birthday"],["in","in May, in 2020, in summer, in the morning, in the evening"]],
  ex:[["The lesson starts at 9 on Monday.","Dərs bazar ertəsi saat 9-da başlayır."],["I was born in 1996.","1996-cı ildə doğulmuşam."]],
  no:"in Monday / on 2020 — səhvdir"},
 {h:"3. Bu sözlərdən əvvəl ön söz yoxdur",
  t:"last, next, this, every, yesterday, tomorrow, today sözləri özləri vaxtı göstərir. Ona görə bu sözlərdən əvvəl at / on / in işlənmir. Azərbaycanca da «gələn həftə», «keçən il» deyirik və şəkilçi yoxdur. in the morning kimi ifadələrdə this gələndə də in düşür: this morning.",
  ex:[["I'll call you next week.","Gələn həftə sənə zəng edəcəm."],["We met last Friday.","Keçən cümə görüşdük."],["I saw her this morning.","Onu bu səhər gördüm."]],
  no:"on next week / in last year — səhvdir"},
 {h:"4. from … to, until, for, since",
  t:"from … to «…-dan …-a qədər» deməkdir və başlanğıcla sonu birlikdə göstərir. until «…-a qədər» deməkdir və yalnız bitmə anını göstərir. for və since-i g08-dən bilirsən: for + müddət, since + başlanğıc. by isə «ən gec …-a qədər» deməkdir.",
  ex:[["The shop is open from 9 to 6.","Mağaza 9-dan 6-ya qədər açıqdır."],["I'll wait until 5.","Saat 5-ə qədər gözləyəcəm."]]},
 {h:"5. during, while, before, after",
  t:"during «… ərzində, … zamanı» deməkdir və ondan sonra isim gəlir. while da «…-arkən» deməkdir, amma ondan sonra tam cümlə (kim + fel) gəlir. before (əvvəl) və after (sonra) sözlərindən sonra həm isim, həm də -ing gələ bilər. Azərbaycanca bunların hamısı şəkilçidir, ona görə ingiliscə arxadan nəyin gəldiyinə bax: isim, yoxsa cümlə.",
  ex:[["I fell asleep during the film.","Film zamanı yuxuya getdim."],["I fell asleep while I was watching TV.","Televizora baxarkən yuxuya getdim."],["Wash your hands before eating.","Yeməkdən əvvəl əllərini yu."]],
  no:"during I was watching — səhvdir"},
 {h:"6. Yer: in — içində",
  t:"in bir şeyin İÇİNDƏ olduğunu göstərir: otağın, qutunun, çantanın içində. Şəhər və ölkə də «içində olmaq» kimi düşünülür: in Baku, in Azerbaijan. Sərhədi olan sahələr üçün də in işlənir: in the park, in the garden. Minik maşını və taksi üçün də in deyilir: in the car.",
  ex:[["The keys are in my bag.","Açarlar çantamdadır."],["She lives in Baku.","O Bakıda yaşayır."],["The children are playing in the garden.","Uşaqlar bağda oynayır."]]},
 {h:"7. Yer: on — üstündə, səthində",
  t:"on bir şeyin SƏTHİNDƏ, üstündə olduğunu göstərir: masanın üstündə, divarda, yerdə. Mərtəbə üçün də on işlənir: on the second floor. İçində ayaq üstə dura bildiyin böyük nəqliyyat — avtobus, qatar, təyyarə — üçün də on deyilir. Minik maşını üçün isə in.",
  ex:[["Your phone is on the table.","Telefonun masanın üstündədir."],["There's a picture on the wall.","Divarda şəkil var."],["I'm on the bus.","Avtobusdayam."]]},
 {h:"8. Yer: at — nöqtə, məkan",
  t:"at bir NÖQTƏNİ göstərir: dayanacaq, qapı, masa. Həm də bir işin görüldüyü yeri göstərir: at work, at school, at home, at a party, at the airport. Burada vacib olan binanın içi yox, orada nə etdiyindir. Ünvanda ev nömrəsi ilə də at işlənir.",
  ex:[["Wait for me at the bus stop.","Məni avtobus dayanacağında gözlə."],["She's at work.","O işdədir."],["I'll meet you at the station.","Səninlə stansiyada görüşərəm."]]},
 {h:"9. Hərəkət: to — «-a, -ə»",
  t:"Bir yerə getməyi göstərmək üçün go to, come to işlənir. home sözündən əvvəl to yoxdur. arrive isə to almır: arrive in + şəhər / ölkə, arrive at + bina / yer. Azərbaycanca «Bakıya çatdıq» deyirik, ona görə arrive to səhvi çox edilir.",
  ex:[["We went to Ganja.","Gəncəyə getdik."],["We arrived in Baku at night.","Gecə Bakıya çatdıq."],["We arrived at the airport at 5.","Saat 5-də hava limanına çatdıq."]],
  no:"arrive to Baku — səhvdir"},
 {h:"10. Yer bildirən digər ön sözlər",
  t:"Bu ön sözlər əşyanın harada durduğunu dəqiq göstərir. Azərbaycanca bunları «yanında, arasında, altında» kimi şəkilçili sözlərlə deyirik. İngiliscə isə ön söz həmişə yer bildirən sözdən əvvəl gəlir. between iki şeyin arasında işlənir və and ilə gəlir: between A and B. in front of və next to bir neçə sözdən ibarətdir, amma bir ön söz kimi işlənir.",
  tbl:[["next to","yanında"],["between","arasında (iki şeyin)"],["opposite","qarşısında (üz-üzə)"],["in front of","qabağında"],["behind","arxasında"],["under","altında"],["above / over","yuxarısında"],["near","yaxınlığında"]],
  ex:[["The cinema is between the bank and the post office.","Kinoteatr bankla poçtun arasındadır."],["The cat is under the table.","Pişik masanın altındadır."],["There's a pharmacy opposite the bank.","Bankın qarşısında aptek var."]]},
 {h:"11. Hərəkət istiqaməti",
  t:"Bu ön sözlər yerdə durmağı yox, hərəkətin İSTİQAMƏTİNİ göstərir. Ona görə onlar hərəkət bildirən feldən (go, come, walk, run, drive) sonra gəlir. Azərbaycanca bunu çox vaxt «içəri, keçib, boyunca» kimi sözlərlə deyirik. into = içəri girmək, out of = içəridən çölə çıxmaq.",
  tbl:[["into / out of","içəri / çölə"],["up / down","yuxarı / aşağı"],["across","o tərəfə (keçib)"],["through","içindən keçib"],["along","boyunca"],["over","üstündən"]],
  ex:[["The train goes through a long tunnel.","Qatar uzun tuneldən keçir."],["He walked across the street.","O küçəni keçdi."],["She came into the room.","O otağa girdi."]]},
 {h:"12. by, with, on, about",
  t:"by + nəqliyyat (artiklsız): by bus, by car, by train; amma on foot (piyada). by + müəllif: a book by Nizami. with = ilə (birlikdə, alət). about = haqqında. on TV, on the phone.",
  ex:[["I go to work by bus.","İşə avtobusla gedirəm."],["We went there on foot.","Ora piyada getdik."],["I cut it with a knife.","Onu bıçaqla kəsdim."],["a film about the war","müharibə haqqında film"]],
  no:"with bus — səhvdir"},
 {h:"13. Sifət + ön söz — bütöv əzbərlə",
  t:"Bəzi sifətlərdən sonra müəyyən ön söz gəlir və bu ön söz sifətin özünə bağlıdır. Azərbaycanca şəkilçi fərqli ola bilər: «itlərdən qorxur» — afraid of. Ona görə birləşməni bütöv yadda saxla: sifət + ön söz. Ön sözdən sonra fel gələrsə, o, -ing alır (g10).",
  tbl:[["afraid of","…-dan qorxmaq"],["good at","…-ı bacarmaq"],["interested in","…-la maraqlanmaq"],["married to","…-la evli"],["different from","…-dan fərqli"],["tired of","…-dan yorulmaq"],["proud of","…-la fəxr etmək"],["famous for","…-la məşhur"]],
  ex:[["She's afraid of dogs.","O itlərdən qorxur."],["He is married to my cousin.","O mənim əmim qızı ilə evlidir."],["I'm good at cooking.","Yemək bişirməyi bacarıram."]]},
 {h:"14. Fel + ön söz — bütöv əzbərlə",
  t:"Bəzi fellər müəyyən ön sözlə işlənir və bu ön söz felin hissəsi sayılır. Ön söz düşsə və ya başqası qoyulsa, cümlə səhv olur. Azərbaycanca «məni gözlə» deyirik və ön söz yoxdur, ingiliscə isə wait for me deyilir. Cədvəldəki birləşmələri bütöv əzbərlə.",
  tbl:[["listen to","qulaq asmaq"],["look at","baxmaq"],["wait for","gözləmək"],["look for","axtarmaq"],["talk to / about","danışmaq (kimlə / nə haqda)"],["think about","düşünmək"],["depend on","asılı olmaq"],["pay for","ödəmək (nəyə görə)"],["belong to","aid olmaq"]],
  ex:[["Listen to me!","Mənə qulaq as!"],["I'm waiting for the bus.","Avtobusu gözləyirəm."],["It depends on the weather.","Havadan asılıdır."]],
  no:"listen me / wait the bus — səhvdir"}
],
g27: [
 {h:"1. Phrasal verb nədir?",
  t:"Bəzi fellər in, out, up, down, on, off, away, back kimi kiçik sözlə birləşir və birlikdə bir məna verir. Bu birləşməyə phrasal verb deyilir. Bəzən mənası asan anlaşılır (sit down = otur), bəzən tamam yeni olur (give up = tərk etmək). Lüğətdə bu birləşmələr ayrıca söz kimi verilir.",
  ex:[["Sit down, please.","Oturun, zəhmət olmasa."],["My father gave up smoking.","Atam siqareti atdı."],["Please turn off your phones.","Zəhmət olmasa, telefonlarınızı söndürün."]]},
 {h:"2. Yer və hərəkət bildirənlər",
  t:"Bu birləşmələrin mənası hərəkətin istiqamətindən aydındır. Kiçik söz hərəkətin hara olduğunu göstərir: in — içəri, out — çölə, down — aşağı, up — yuxarı, back — geri. Ona görə bunları başa düşmək asandır. Bu cədvəldəki birləşmələrin çoxu obyektsiz işlənir.",
  tbl:[["come in / go out","içəri gəlmək / çölə çıxmaq"],["sit down / stand up","oturmaq / ayağa qalxmaq"],["come back / go back","qayıtmaq"],["go away","getmək, uzaqlaşmaq"],["get on / get off","(avtobusa) minmək / düşmək"]],
  ex:[["Come in!","İçəri gəl!"],["Please come back soon.","Tezliklə qayıt."],["She stood up and went out.","O ayağa qalxıb çölə çıxdı."]]},
 {h:"3. Gündəlik həyat",
  t:"Bu phrasal verb-lər gündəlik həyatda, səhərdən axşama qədər çox işlənir. wake up (oyanmaq) ilə get up (yerdən durmaq) fərqlidir: əvvəl oyanırsan, sonra durursan. put on paltar üçün «geyinmək», turn on cihaz üçün «yandırmaq» deməkdir. Bunların çoxunun əksi də phrasal verb-dir: put on — take off, turn on — turn off.",
  tbl:[["wake up","oyanmaq"],["get up","yerdən durmaq"],["grow up","böyümək"],["put on / take off","geyinmək / soyunmaq"],["turn on / turn off","yandırmaq / söndürmək"],["try on","(paltarı) geyinib yoxlamaq"]],
  ex:[["I woke up at 7.","Saat 7-də oyandım."],["Turn off the light.","İşığı söndür."],["I grew up in Lankaran.","Lənkəranda böyümüşəm."]]},
 {h:"4. Yeni mənalı phrasal verb-lər",
  t:"Bu phrasal verb-lərin mənasını iki sözdən təxmin etmək çətindir. Məsələn, give (vermək) + up (yuxarı) birlikdə «tərk etmək» deməkdir. Ona görə onları yeni söz kimi, bütöv əzbərlə. Ən yaxşı yol hər birini bir cümlə ilə yadda saxlamaqdır.",
  tbl:[["give up","tərk etmək, əl çəkmək"],["find out","öyrənmək, aşkar etmək"],["look after","qayğısına qalmaq"],["look for","axtarmaq"],["break down","(maşın) xarab olmaq"],["run out of","qurtarmaq (bir şey bitmək)"],["throw away","atmaq (zibilə)"],["fill in","(anketi, formu) doldurmaq"]],
  ex:[["Who looks after your children?","Uşaqlarına kim baxır?"],["We've run out of milk.","Südümüz qurtarıb."],["Our car broke down.","Maşınımız xarab oldu."]]},
 {h:"5. Söz sırası: put on your shoes = put your shoes on",
  t:"Obyekt alan phrasal verb-lərin çoxunda obyekt (isim) kiçik sözdən əvvəl də, sonra da gələ bilər. İkisi də düzdür və mənası eynidir. look for, look after, look at birləşmələri isə ayrılmır (7-ci qayda). Obyekt it, them kimi əvəzlikdirsə, qayda dəyişir (6-cı qayda).",
  ex:[["Put on your coat. / Put your coat on.","Paltonu gey."],["Turn off the TV. / Turn the TV off.","Televizoru söndür."],["Take off your shoes. / Take your shoes off.","Ayaqqabılarını çıxar."]]},
 {h:"6. it / them — həmişə ortada",
  t:"Obyekt it, them, him, her olanda o, fel ilə kiçik sözün ARASINA girir. Əvəzlik sona keçə bilməz. Səbəb budur: qısa əvəzlik vurğusuzdur və fellə birlikdə deyilir. Bu qayda 5-ci qaydadakı ayrıla bilən birləşmələrə aiddir.",
  ex:[["Put it on.","Onu gey."],["Turn it off.","Onu söndür."],["Can I try them on?","Onları geyinib yoxlaya bilərəm?"]],
  no:"Put on it / Turn off it — səhvdir"},
 {h:"7. look for, look after, look at — ayrılmır",
  t:"look for, look after, look at, wait for, listen to birləşmələrində ikinci söz ön sözdür. Ön söz həmişə öz isminin qabağında durur, ona görə obyekt — hətta it və them də — həmişə sondadır. Fel ilə ön sözün arasına heç nə girmir. Bu, 6-cı qaydanın əksidir.",
  ex:[["I'm looking for my keys. I'm looking for them.","Açarlarımı axtarıram. Onları axtarıram."],["Can you look after my bag? — Yes, I'll look after it.","Çantama göz qoya bilərsən? — Bəli, ona baxaram."],["Look at this photo. Look at it!","Bu şəklə bax. Ona bax!"]],
  no:"I'm looking them for. — səhvdir"},
 {h:"8. Keçmişdə fel hissəsi dəyişir",
  t:"Zaman dəyişəndə yalnız fel hissəsi dəyişir, kiçik söz eyni qalır. Felin özü qaydasızdırsa, qaydasız forması işlənir: woke up, got up, gave up. Kiçik sözə heç vaxt -ed və ya -s artırılmır. Sual və inkarda did / does qaydası adi fellərdəki kimidir.",
  tbl:[["wake up","woke up"],["get up","got up"],["give up","gave up"],["break down","broke down"],["put on","put on"]],
  ex:[["I got up late today.","Bu gün gec durdum."],["He gave up smoking last year.","O, keçən il siqareti atdı."]],
  no:"waked up — səhvdir"},
 {h:"9. Üç hissəli birləşmələr",
  t:"Bəzi phrasal verb-lər üç hissədən ibarətdir: fel + kiçik söz + ön söz. Məsələn: run out of, look forward to, get on with. Bu birləşmələr ayrılmır: obyekt həmişə sonda gəlir. Hər birini bütöv bir söz kimi əzbərlə.",
  ex:[["We've run out of sugar.","Şəkərimiz qurtarıb."],["I'm looking forward to the holiday.","Tətili səbirsizliklə gözləyirəm."],["I get on well with my colleagues.","İş yoldaşlarımla yaxşı yola gedirəm."]]},
 {h:"10. give up və look forward to + -ing",
  t:"Phrasal verb-dən sonra fel gələndə, o, -ing formasında olur. look forward to-da to ön sözdür, to + fel deyil. Ona görə ondan sonra da -ing gəlir, sadə fel yox. Bu ifadə rəsmi məktubların sonunda çox işlənir.",
  ex:[["She gave up eating sugar.","O şəkər yeməyi tərk etdi."],["I look forward to seeing you.","Səni görməyi səbirsizliklə gözləyirəm."],["I look forward to hearing from you.","Cavabınızı gözləyirəm."]],
  no:"look forward to see — səhvdir"}
],
g12: [
 {h:"1. Passiv nə vaxt lazımdır?",
  t:"Adi cümlədə işi görən öndədir: They built the bridge. Bəzən işi kimin gördüyü bilinmir və ya vacib deyil — diqqət əşyadadır. Onda passiv işlənir: The bridge was built. Azərbaycanca bu «-ıl, -il, -ın» şəkilçisidir: tikildi, satılır, edilib.",
  ex:[["They built this bridge in 1990. → This bridge was built in 1990.","Bu körpünü 1990-da tikdilər. → Bu körpü 1990-da tikildi."],["Somebody stole my car. → My car was stolen.","Kimsə maşınımı oğurladı. → Maşınım oğurlandı."]]},
 {h:"2. Forma: be + V3",
  t:"Passivin düsturu bütün zamanlarda eynidir: be + felin üçüncü forması (V3). Zamanı be sözü göstərir: is, was, has been, will be. V3 isə heç vaxt dəyişmir. Ona görə passiv qurmaq üçün iki şey bilmək lazımdır: be-nin düz forması və felin V3-ü.",
  tbl:[["indi (adətən)","is / are + V3"],["keçmiş","was / were + V3"],["indi gedir","is / are being + V3"],["Present Perfect","has / have been + V3"],["gələcək","will be + V3"],["modal","can / must / should be + V3"]],
  ex:[["The room is cleaned every day.","Otaq hər gün təmizlənir."],["The room was cleaned yesterday.","Otaq dünən təmizləndi."],["The room will be cleaned tomorrow.","Otaq sabah təmizlənəcək."]]},
 {h:"3. Present Simple passiv: is / are + V3",
  t:"Adətən, həmişə edilən iş və ümumi fakt üçün Present Simple passiv işlənir: is / are + V3. Tək şey haqqında is, çox şey haqqında are. Azərbaycanca bu «-ılır, -ilir, -unur» formasıdır: danışılır, təmizlənir. Kim tərəfindən edildiyi çox vaxt deyilmir, çünki vacib deyil.",
  ex:[["English is spoken in many countries.","İngilis dili bir çox ölkədə danışılır."],["These cars are made in Germany.","Bu maşınlar Almaniyada istehsal olunur."],["The room is cleaned every day.","Otaq hər gün təmizlənir."]]},
 {h:"4. Past Simple passiv: was / were + V3",
  t:"Keçmişdə edilmiş iş üçün was / were + V3 işlənir. Tək şey üçün was, çox şey üçün were. Azərbaycanca bu «-ıldı, -ildi» formasıdır: oğurlandı, göndərildi, tikildi. Tarixdən, binalardan, ixtiralardan danışanda çox işlənir.",
  ex:[["My bike was stolen last night.","Velosipedim dünən gecə oğurlandı."],["The letters were sent yesterday.","Məktublar dünən göndərildi."],["The Maiden Tower was built many centuries ago.","Qız qalası çox əsrlər əvvəl tikilib."]]},
 {h:"5. by — «… tərəfindən»",
  t:"İşi kimin gördüyünü demək vacibdirsə, by + adam işlənir: «… tərəfindən». by hissəsi cümlənin sonunda gəlir. Kimin etdiyi bəlli deyilsə və ya vacib deyilsə, by hissəsi yazılmır. Passiv cümlələrin çoxunda by olmur.",
  ex:[["This book was written by a famous writer.","Bu kitab məşhur yazıçı tərəfindən yazılıb."],["The cake was made by my sister.","Tortu bacım bişirib."],["The museum is visited by thousands of tourists every year.","Muzeyə hər il minlərlə turist gəlir."]],
  no:"made from my sister — səhvdir"},
 {h:"6. Sual və inkar — be ilə",
  t:"Passiv cümlədə köməkçi söz be-dir (is, are, was, were). g01-dəki qaydaya görə, am / is / are / was / were varsa, do / does / did lazım deyil. Sualda is / was «kim»-dən əvvələ keçir, inkarda ondan sonra not gəlir. V3 öz yerində qalır.",
  ex:[["Was this cake made by your mother?","Bu tortu anan bişirib?"],["Smoking isn't allowed here.","Burada siqaret çəkmək olmaz."],["The email wasn't sent.","E-poçt göndərilmədi."]],
  no:"Did this cake made…? — səhvdir"},
 {h:"7. İndi gedir: is / are being + V3",
  t:"İş indi, danışdığın anda edilirsə, is / are being + V3 işlənir. Bu, Present Continuous-un passiv formasıdır: being «indi gedir» mənasını verir. Azərbaycanca «təmir olunur (indi)» deyirik. Keçmişdə was / were being + V3 olur.",
  ex:[["My car is being repaired.","Maşınım indi təmir olunur."],["The road is being repaired, so we have to wait.","Yol təmir olunur, ona görə gözləməliyik."],["Our flat is being cleaned at the moment.","Mənzilimiz indi təmizlənir."]]},
 {h:"8. Present Perfect passiv: has / have been + V3",
  t:"Bir iş təzəcə edilibsə və nəticəsi indi görünürsə, has / have been + V3 işlənir. Bu, Present Perfect-in passiv formasıdır (g08). Tək şey üçün has been, çox şey üçün have been. Xəbərlərdə və elanlarda çox işlənir.",
  ex:[["All the tickets have been sold.","Bütün biletlər satılıb."],["The report has been finished.","Hesabat bitirilib."],["My wallet has been stolen!","Pul kisəm oğurlanıb!"]]},
 {h:"9. Gələcək və modal: will be / must be + V3",
  t:"will, can, must, should, might sözlərindən sonra passivdə be + V3 gəlir. Modal feldən sonra fel sadə formada olmalıdır (g09), ona görə is / are yox, be yazılır. Gələcək üçün will be + V3, məcburiyyət üçün must be + V3 işlənir. Bu forma qaydalarda və bildirişlərdə çox işlənir.",
  ex:[["The results will be announced next week.","Nəticələr gələn həftə elan ediləcək."],["The windows must be cleaned.","Pəncərələr təmizlənməlidir."],["This medicine can be bought without a prescription.","Bu dərmanı reseptsiz almaq olar."]]},
 {h:"10. was born — «doğulmuşam»",
  t:"«Doğulmaq» ingiliscə həmişə passiv formadadır: be born. Ona görə «doğuldum» = I was born — was mütləqdir. Tək born demək olmaz, çünki born felin V3 formasıdır və tək işlənmir. Sual da was / were ilə qurulur.",
  ex:[["I was born in Ganja.","Gəncədə doğulmuşam."],["Where were you born?","Harada doğulmusan?"],["My daughter was born in 2015.","Qızım 2015-ci ildə doğulub."]],
  no:"I born in 1995 — səhvdir"},
 {h:"11. Hər fel passiv olmur",
  t:"Passiv yalnız obyekti (nəyi? kimi?) olan fellərdən düzəlir, çünki passivdə həmin obyekt cümlənin əvvəlinə keçir. Felin obyekti yoxdursa (happen — baş vermək, arrive — çatmaq, die — ölmək, sleep — yatmaq), passiv olmur. Belə fellər həmişə adi formada işlənir. Azərbaycanca «baş verildi» demədiyimiz kimi, ingiliscə də was happened deyilmir.",
  ex:[["The accident happened at 8 pm.","Qəza axşam saat 8-də baş verdi."],["The train arrived late.","Qatar gec gəldi."],["He died in 1990.","O, 1990-cı ildə vəfat edib."]],
  no:"The accident was happened — səhvdir"},
 {h:"12. IELTS Task 1: prosesin təsviri",
  t:"Prosesi — bir şeyin necə hazırlandığını — təsvir edəndə adamlardan yox, mərhələlərdən danışılır. Ona görə IELTS Task 1-də proses təsvirində passiv çox işlənir. Mərhələləri First, Then, After that, Finally sözləri ilə bağla. Burada əsas forma Present Simple passivdir: is / are + V3.",
  ex:[["First, the tea leaves are picked.","Əvvəlcə çay yarpaqları dərilir."],["Then they are dried in the sun.","Sonra günəşdə qurudulur."],["Finally, the tea is packed and sold.","Sonda çay qablaşdırılıb satılır."]]}
],
g13: [
 {h:"1. Təsvir edən ikinci cümlə",
  t:"Bir adamı və ya əşyanı daha dəqiq təsvir etmək üçün onun arxasından kiçik cümlə gəlir. Azərbaycanca bu, sözün ƏVVƏLİNDƏ olur: «qonşuda yaşayan qadın». İngiliscə isə SONRA: the woman who lives next door.",
  tbl:[["qonşuda yaşayan qadın","the woman who lives next door"],["mənə verdiyin kitab","the book that you gave me"]],
  ex:[["The woman who lives next door is a doctor.","Qonşuda yaşayan qadın həkimdir."],["I lost the book that you gave me.","Mənə verdiyin kitabı itirdim."]]},
 {h:"2. who — insan üçün",
  t:"Təsvir olunan insandırsa, who işlənir. who insanın adından dərhal sonra gəlir, ondan sonra fel və ya başqa «kim» gəlir. Azərbaycanca bu, «zəng edən adam», «dürüst olan insanlar» kimi «-an, -ən» formasıdır. who-dan sonra felin tək və ya cəm olması təsvir olunan sözə görə seçilir.",
  ex:[["The man who called you is my uncle.","Sənə zəng edən adam mənim əmimdir."],["I like people who are honest.","Dürüst insanları sevirəm."],["Do you know the girl who is talking to Ali?","Əli ilə danışan qızı tanıyırsan?"]]},
 {h:"3. which — əşya və heyvan üçün",
  t:"Təsvir olunan əşya və ya heyvandırsa, which işlənir. İnsan üçün which işlənmir — bu, çox edilən səhvdir. which də sözün dərhal arxasından gəlir. Danışıqda which yerinə çox vaxt that deyilir (4-cü qayda).",
  ex:[["A dictionary is a book which explains words.","Lüğət sözləri izah edən kitabdır."],["The film which we watched was boring.","Baxdığımız film darıxdırıcı idi."],["I have a cat which sleeps all day.","Bütün günü yatan bir pişiyim var."]],
  no:"the man which lives here — səhvdir"},
 {h:"4. that — hər ikisi üçün",
  t:"Danışıqda who və which yerinə çox vaxt that işlənir. that həm insan, həm əşya üçün düzdür. Amma vergüllü əlavə məlumatda that işlənmir (11-ci qayda). Yazıda insanlar üçün who daha çox işlənir.",
  ex:[["The bus that goes to the airport leaves every hour.","Hava limanına gedən avtobus hər saat yola düşür."],["I have a friend that lives in Paris.","Parisdə yaşayan bir dostum var."],["Where is the money that was on the table?","Masanın üstündə olan pul haradadır?"]]},
 {h:"5. where — yer üçün",
  t:"Təsvir olunan söz yerdirsə (şəhər, ev, kənd, otel) və orada nəsə baş verirsə, where işlənir. where-dən sonra tam cümlə gəlir: kim + fel. Azərbaycanca bu, «doğulduğu kənd», «yaşadığım şəhər» kimidir. where işlənəndə ön söz (in, at) yazılmır (10-cu qayda).",
  ex:[["This is the village where my father was born.","Bu, atamın doğulduğu kənddir."],["Baku is a city where you can see old and new buildings.","Bakı köhnə və yeni binaları görə biləcəyin şəhərdir."],["I know a restaurant where the food is very good.","Yeməyi çox yaxşı olan bir restoran tanıyıram."]]},
 {h:"6. whose — «kimin, onun»",
  t:"whose sahibliyi göstərir: «atası pilot olan oğlan», «maşını oğurlanan adam». Azərbaycanca bu, «onun …-ı olan» mənasıdır. whose-dan sonra həmişə isim gəlir. who + his / her birlikdə işlənmir, whose bu ikisinin yerini tutur.",
  ex:[["That's the man whose car was stolen.","Bu, maşını oğurlanan adamdır."],["The boy whose father is a pilot is my neighbour.","Atası pilot olan oğlan qonşumdur."],["I met a woman whose son studies with mine.","Oğlu mənim oğlumla oxuyan bir qadınla tanış oldum."]],
  no:"the girl who her mother — səhvdir"},
 {h:"7. when — vaxt üçün",
  t:"Təsvir olunan söz vaxtdırsa (gün, il, an), when işlənir. when əvəzinə that də işlənə bilər, ya da tamamilə atıla bilər. Azərbaycanca bu, «tanış olduğumuz gün», «doğulduğum il» kimidir. Bu when sual sözü deyil, cümlədə vaxtı təsvir edir.",
  ex:[["I'll never forget the day when I met you.","Səninlə tanış olduğum günü heç vaxt unutmaram."],["2010 was the year when we moved to Baku.","2010-cu il Bakıya köçdüyümüz il idi."],["Do you remember the time when we got lost?","Yolu azdığımız vaxtı xatırlayırsan?"]]},
 {h:"8. Təkrar əvəzlik olmur",
  t:"who, which, that artıq adamı və ya əşyanı göstərir və onun yerini tutur. Ona görə cümlədə həmin şeyi ikinci dəfə it, him, he, her ilə təkrar etmək olmaz. Azərbaycanca da belə təkrar etmirik: «oxuduğum kitab» deyirik, «onu oxuduğum kitab» demirik. Bu səhv xüsusən uzun cümlələrdə edilir.",
  ex:[["The book which I read was great.","Oxuduğum kitab əla idi."],["I have a friend who speaks French.","Fransızca danışan dostum var."]],
  no:"The book which I read it / a friend who he speaks — səhvdir"},
 {h:"9. who/which/that-i atmaq olar — amma həmişə yox",
  t:"who / which / that-dan sonra başqa bir «kim» (I, you, we, my brother) gəlirsə, bu sözü atmaq olar. Bu halda who / which / that işin yönəldiyi şeyi göstərir. Əgər who / which / that-ın özü işi görürsə — yəni ondan sonra dərhal fel gəlirsə — atmaq olmaz. Danışıqda bu sözü atmaq çox yayılıb.",
  tbl:[["the car (that) I bought","atmaq olar — sonra I gəlir"],["the man who lives here","atmaq olmaz — who işi görür"]],
  ex:[["This is the car I bought last year.","Bu, keçən il aldığım maşındır."],["The people we met were very friendly.","Tanış olduğumuz adamlar çox mehriban idilər."],["Is this the book you wanted?","İstədiyin kitab budurmu?"]]},
 {h:"10. Ön söz sonda: the hotel we stayed at",
  t:"Felin özünə bağlı ön söz varsa (stay at, live in, talk to, look for), bu ön söz cümlənin sonunda, felin yanında qalır. Azərbaycanca ön söz yoxdur, şəkilçi var: «qaldığımız otel». where işlənəndə isə ön söz yazılmır, çünki where özü «-da» mənasını verir. Ya where, ya da ön söz — ikisi birlikdə yox.",
  ex:[["This is the hotel we stayed at.","Bu, qaldığımız oteldir."],["This is the town where I live.","Bu, yaşadığım şəhərdir."],["Who is the man you were talking to?","Danışdığın adam kimdir?"]],
  no:"the town where I live in — səhvdir"},
 {h:"11. Vergüllü əlavə məlumat",
  t:"Adam və ya əşya artıq bəllidirsə və sən sadəcə ƏLAVƏ məlumat verirsənsə, bu hissə vergüllər arasına alınır. Bu məlumatı çıxarsan, cümlə yenə tam və aydın qalır. Belə hissədə that işlənmir və who / which atıla bilməz. Bu forma daha çox yazıda işlənir.",
  ex:[["My sister, who lives in London, is a nurse.","Londonda yaşayan bacım tibb bacısıdır."],["Baku, which is on the Caspian Sea, is my home town.","Xəzər sahilində olan Bakı mənim doğma şəhərimdir."]],
  no:"My brother, that lives in Ganja, … — səhvdir"}
],
g14: [
 {h:"1. Şərt cümləsinin iki hissəsi",
  t:"if «əgər, …-sa» deməkdir. Şərt cümləsi iki hissədən ibarətdir: şərt (if hissəsi) və nəticə. if hissəsi cümlənin əvvəlində də, sonunda da ola bilər, məna dəyişmir. Əvvəldə gələndə ondan sonra vergül qoyulur; sonda gələndə vergül lazım deyil.",
  ex:[["If it rains, we'll stay at home.","Yağış yağsa, evdə qalacağıq."],["We'll stay at home if it rains.","Yağış yağsa, evdə qalacağıq."]]},
 {h:"2. Dörd növ şərt",
  t:"Şərt cümləsinin növü onun nə qədər real olduğundan asılıdır. Hər növün öz zaman cütü var: if hissəsində bir forma, nəticə hissəsində başqa forma. Cədvəldə dörd növün hamısı var, aşağıdakı qaydalarda hər biri ayrıca izah olunur. Ən çox 1-ci və 2-ci növ işlənir.",
  tbl:[["0 — həmişə doğru","if + Present, Present"],["1 — real gələcək","if + Present, will + fel"],["2 — xəyali indi/gələcək","if + Past, would + fel"],["3 — keçmiş, dəyişmək olmaz","if + had + V3, would have + V3"]],
  ex:[["If I have time, I'll help you.","Vaxtım olsa, sənə kömək edərəm."],["If I had time, I would help you.","Vaxtım olsaydı, sənə kömək edərdim."]]},
 {h:"3. 0-cı növ — həmişə belədir",
  t:"Elmi fakt və həmişə eyni nəticə verən hallar üçün hər iki hissədə Present Simple işlənir. Bu növdə if «nə vaxt ki» mənasındadır və onu when ilə əvəz etmək olar. will burada işlənmir, çünki söhbət gələcəkdən yox, həmişə doğru olan şeydən gedir. Təlimatlarda da bu forma işlənir.",
  ex:[["If you heat ice, it melts.","Buzu qızdırsan, əriyir."],["If you mix red and blue, you get purple.","Qırmızı ilə mavini qarışdırsan, bənövşəyi alınır."],["If I drink coffee at night, I can't sleep.","Gecə qəhvə içsəm, yata bilmirəm."]]},
 {h:"4. 1-ci növ — real gələcək",
  t:"Şərtin baş verməsi mümkündürsə və real gələcəkdən danışırsansa, 1-ci növ işlənir: if + Present Simple, nəticədə will + fel. Azərbaycanca «yağsa, qalacağıq» deyirik. Nəticə hissəsində will əvəzinə can, might, should və ya əmr də ola bilər. if hissəsi əvvəldə gələndə ondan sonra vergül qoyulur.",
  ex:[["If it is sunny tomorrow, we'll go to the beach.","Sabah günəşli olsa, çimərliyə gedəcəyik."],["If you are hungry, there's soup in the fridge.","Acsansa, soyuducuda şorba var."],["If he calls, tell him I'm busy.","Zəng etsə, de ki, məşğulam."]]},
 {h:"5. if hissəsində will və would olmur",
  t:"Azərbaycanca «yağış yağacaqsa» deyə bilərik, ingiliscə isə if hissəsində will və would işlənmir. Gələcək mənası olsa da, if-dən sonra Present Simple qalır (g05-dəki qayda). will yalnız nəticə hissəsində olur. Bu, if ilə ən çox edilən səhvdir.",
  ex:[["If I see him, I'll tell him.","Onu görsəm, deyərəm."],["If the weather is good tomorrow, we'll have a picnic.","Sabah hava yaxşı olsa, piknik edəcəyik."],["I'll be very happy if you come.","Gəlsən, çox şad olaram."]],
  no:"If it will rain / If I would have — səhvdir"},
 {h:"6. unless = if … not",
  t:"unless «…-mazsa, …-məsə» deməkdir, yəni if … not. Özündə inkar olduğu üçün ondan sonra not işlənmir. unless-dən sonra da gələcək mənasında Present Simple gəlir, will yox. Çox vaxt if … not ilə unless eyni mənanı verir.",
  ex:[["Unless you hurry, you'll miss the bus.","Tələsməsən, avtobusa çatmayacaqsan."],["You won't pass unless you study.","Oxumasan, keçməyəcəksən."],["I'll be there at 8 unless the bus is late.","Avtobus gecikməsə, saat 8-də orada olacam."]],
  no:"Unless you don't study — səhvdir"},
 {h:"7. 2-ci növ — xəyal, real deyil",
  t:"İndi və ya gələcəkdə real olmayan, xəyali vəziyyət üçün: if + Past Simple, nəticədə would + fel. Keçmiş forma burada keçmişi yox, «real deyil»i göstərir. Azərbaycanca «olsaydı, edərdim».",
  ex:[["If I had more money, I would buy a flat.","Daha çox pulum olsaydı, mənzil alardım."],["If she worked harder, she would get a better job.","Daha çox çalışsaydı, daha yaxşı iş tapardı."]]},
 {h:"8. If I were you — məsləhət",
  t:"2-ci növdə be üçün bütün şəxslərdə were işlənir: if I were, if he were. «Mən sənin yerində olsaydım» = If I were you — məsləhət vermək üçün çox işlənir. Danışıqda If I was da eşidilir, amma imtahanda were daha təhlükəsizdir. Nəticə hissəsində would + fel gəlir.",
  ex:[["If I were you, I would see a doctor.","Sənin yerində olsaydım, həkimə gedərdim."],["I wouldn't buy that car if I were you.","Sənin yerində olsaydım, o maşını almazdım."],["If he were here, he would help us.","O burada olsaydı, bizə kömək edərdi."]],
  no:"If I am you, I would… — səhvdir"},
 {h:"9. would — forma və sual",
  t:"would bütün şəxslər üçün eynidir: I would, she would. Qısa forması 'd, inkarı wouldn't-dur. Sualda would «kim»-dən əvvələ keçir. Nəticə hissəsində would əvəzinə could (bacarardım) və might (bəlkə) də ola bilər.",
  ex:[["What would you do if you lost your phone?","Telefonunu itirsəydin, nə edərdin?"],["If I had more time, I could help you.","Daha çox vaxtım olsaydı, sənə kömək edə bilərdim."]]},
 {h:"10. 1-ci yoxsa 2-ci növ?",
  t:"1-ci və 2-ci növ arasındakı fərq ehtimaldadır. Şey mümkündürsə, real ola bilərsə — 1-ci növ. Real deyilsə və ya ehtimalı çox azdırsa — 2-ci növ. Eyni şərt danışanın fikrinə görə hər iki növdə ola bilər.",
  ex:[["If I get the job, I'll have a party.","İşə qəbul olunsam, məclis quracağam (mümkündür)."],["If I won a million, I would travel.","Milyon udsaydım, səyahət edərdim (xəyaldır)."]]},
 {h:"11. 3-cü növ — keçmişdə olmayan şərt",
  t:"3-cü növ keçmişdə OLMAYAN bir şeydən danışır: «bilsəydim» — amma bilmədim. Forma: if + had + V3, nəticədə would have + V3. Keçmişi dəyişmək mümkün olmadığı üçün bu növ çox vaxt təəssüf və ya tənqid bildirir. Azərbaycanca 2-ci və 3-cü növ eyni səslənə bilər («olsaydı»), ingiliscə isə vaxta bax: indi — 2-ci növ, keçmiş — 3-cü növ.",
  ex:[["If I had known, I would have helped you.","Bilsəydim, sənə kömək edərdim (amma bilmədim)."],["If we hadn't missed the bus, we wouldn't have been late.","Avtobusu qaçırmasaydıq, gecikməzdik."]],
  no:"If I had known, I would come — səhvdir"},
 {h:"12. when yoxsa if?",
  t:"when və if Azərbaycancaya «…-anda» və «…-sa» kimi tərcümə olunur. when mütləq olacaq şey üçün işlənir: «nə vaxt ki». if isə bəlkə olacaq, bəlkə olmayacaq şey üçün işlənir. İkisindən sonra da gələcək mənasında Present Simple gəlir, will yox.",
  ex:[["I'll call you when I get home.","Evə çatanda zəng edəcəm (mütləq çatacağam)."],["I'll call you if I have time.","Vaxtım olsa, zəng edəcəm (bəlkə olmayacaq)."]]}
],
g15: [
 {h:"1. Başqasının sözünü ötürmək",
  t:"Birinin dediyini iki yolla çatdırmaq olar. Birinci yol: sözləri dırnaq içində eynən təkrar etmək. İkinci yol: öz cümlənlə ötürmək — buna dolayı nitq (reported speech) deyilir. İkinci yolda zaman, əvəzlik və bəzi vaxt sözləri dəyişir. Azərbaycanca bunu «…dığını dedi» formasında deyirik.",
  ex:[["«I'm tired.» → She said she was tired.","«Yorğunam.» → Yorğun olduğunu dedi."],["«I live in Baku.» → He said he lived in Baku.","«Bakıda yaşayıram.» → Bakıda yaşadığını dedi."]]},
 {h:"2. say yoxsa tell?",
  t:"say və tell ikisi də «demək» deməkdir, amma quruluşları fərqlidir. tell-dən sonra HƏMİŞƏ kimə dediyin gəlir: tell me, told him. say-dan sonra adam gəlmir; adamı demək istəsən, say to me deyilir. tell-dən sonra to işlənmir.",
  tbl:[["said","She said (that) she was ill."],["told + adam","She told me (that) she was ill."]],
  ex:[["She said that she was ill.","O, xəstə olduğunu dedi."],["She told me that she was ill.","O mənə xəstə olduğunu dedi."]],
  no:"She said me / She told to me — səhvdir"},
 {h:"3. that — atmaq olar",
  t:"said və told-dan sonra that yazmaq da, yazmamaq da olar. Məna dəyişmir. Danışıqda that çox vaxt atılır, rəsmi yazıda isə yazılır. that-dan sonra tam cümlə gəlir: kim + fel.",
  ex:[["He said that he was hungry. / He said he was hungry.","Ac olduğunu dedi."],["She told me that she was tired. / She told me she was tired.","O mənə yorğun olduğunu dedi."]]},
 {h:"4. Zaman bir addım geri gedir",
  t:"Danışılan an artıq keçmişdədir, ona görə said / told ilə ötürülən cümlənin zamanı da çox vaxt bir addım keçmişə gedir. İndiki zaman keçmişə, will → would, can → could olur. Cədvəldə hər forma və onun dəyişmiş forması var. Azərbaycanca bu dəyişiklik yoxdur, ona görə ingiliscə xüsusi diqqət lazımdır.",
  tbl:[["am / is","was"],["are","were"],["work / works","worked"],["will","would"],["can","could"],["have / has + V3","had + V3"],["went (Past Simple)","went və ya had gone"]],
  ex:[["«I will call you.» → He said he would call me.","«Sənə zəng edəcəm.» → Mənə zəng edəcəyini dedi."],["«I can swim.» → She said she could swim.","«Üzə bilirəm.» → Üzə bildiyini dedi."],["«I have finished.» → He said he had finished.","«Bitirmişəm.» → Bitirdiyini dedi."]]},
 {h:"5. had + V3 nədir?",
  t:"had + V3 «daha əvvəl olmuşdu» deməkdir (g17-də ətraflı). Dolayı nitqdə o, have / has + V3 formasının yerinə işlənir. Past Simple də ötürüləndə çox vaxt had + V3 olur, amma dəyişməmək də olar. V3-ü g08-dən bilirsən.",
  ex:[["«I have lost my key.» → He said he had lost his key.","«Açarımı itirmişəm.» → Açarını itirdiyini dedi."],["«I've never been to Paris.» → She said she had never been to Paris.","«Heç Parisdə olmamışam.» → Heç vaxt Parisdə olmadığını dedi."]]},
 {h:"6. Əvəzliklər dəyişir",
  t:"Sözü başqa adam ötürdüyü üçün I, my, you kimi sözlər məntiqə görə dəyişir. Danışan özü haqqında I deyibsə, sən onu he / she ilə ötürürsən. Sənə you deyibsə, sən me yazırsan. my → his / her, our → their olur.",
  ex:[["«My car is broken,» he said. → He said his car was broken.","«Maşınım xarabdır.» → Maşınının xarab olduğunu dedi."],["«I'll help you,» she said. → She said she would help me.","«Sənə kömək edərəm.» → Mənə kömək edəcəyini dedi."]]},
 {h:"7. Yer və vaxt sözləri",
  t:"Söz başqa gün və ya başqa yerdə ötürülürsə, here, today, tomorrow kimi yer və vaxt sözləri də dəyişir. Çünki ötürən adam üçün «bu gün» artıq başqa gündür. Eyni gün ötürürsənsə, bu sözlər dəyişməyə bilər. Cədvəldə ən çox işlənən dəyişikliklər var.",
  tbl:[["here","there"],["today","that day"],["tomorrow","the next day"],["yesterday","the day before"]],
  ex:[["«I'll come tomorrow.» → He said he would come the next day.","«Sabah gələcəm.» → Ertəsi gün gələcəyini dedi."],["«I'm busy today.» → She said she was busy that day.","«Bu gün məşğulam.» → O gün məşğul olduğunu dedi."],["«I saw him yesterday.» → He said he had seen him the day before.","«Onu dünən gördüm.» → Onu bir gün əvvəl gördüyünü dedi."]]},
 {h:"8. Hələ də doğrudursa, dəyişməmək olar",
  t:"Deyilən şey indi də doğrudursa, zamanı dəyişməmək də olar. Məsələn, o hələ də Bakıda yaşayırsa, lives da düzdür. Amma imtahanda dəyişdirmək daha təhlükəsizdir. Deyilən şey artıq doğru deyilsə, zaman mütləq dəyişir.",
  ex:[["He said he lives in Baku. / He said he lived in Baku.","Bakıda yaşadığını dedi."],["She said the shop opens at 9. / She said the shop opened at 9.","Mağazanın saat 9-da açıldığını dedi."]]},
 {h:"9. «Bəli/xeyr» sualını ötürmək: asked if",
  t:"Sual sözü olmayan sualı (bəli / xeyr sualı) ötürəndə asked + if (və ya whether) işlənir. Sonra adi cümlə sırası gəlir: kim + fel. do / does / did işlənmir və sonda sual işarəsi qoyulmur. Zaman yenə bir addım keçmişə gedir.",
  ex:[["«Do you speak English?» → She asked me if I spoke English.","«İngiliscə danışırsan?» → İngiliscə danışıb-danışmadığımı soruşdu."],["«Are you hungry?» → She asked me if I was hungry.","«Acsan?» → Ac olub-olmadığımı soruşdu."]],
  no:"She asked me do I speak — səhvdir"},
 {h:"10. Sual sözü ilə sualı ötürmək",
  t:"where, what, when ilə sual ötürəndə sual sözü qalır, amma ondan sonra adi cümlə sırası gəlir: kim + fel. Yəni do / does / did düşür, is / are də «kim»-dən sonraya keçir. Bu, g21-dəki dolayı sual qaydası ilə eynidir. Zaman yenə bir addım keçmişə gedir.",
  ex:[["«Where do you work?» → He asked me where I worked.","«Harada işləyirsən?» → Harada işlədiyimi soruşdu."],["«What time is it?» → She asked me what time it was.","«Saat neçədir?» → Saatın neçə olduğunu soruşdu."],["«Why did you leave?» → He asked me why I had left.","«Niyə getdin?» → Niyə getdiyimi soruşdu."]],
  no:"He asked me where did I work — səhvdir"},
 {h:"11. Əmr və xahişi ötürmək: told / asked + to",
  t:"Əmr ötürəndə told + adam + to + fel, xahiş ötürəndə asked + adam + to + fel işlənir. Qadağa üçün not to + fel gəlir. Burada zaman dəyişmir, çünki to + fel formasında zaman yoxdur. Azərbaycanca bunu «…mağı dedi», «…məyimi xahiş etdi» kimi deyirik.",
  ex:[["«Close the door.» → She told me to close the door.","«Qapını bağla.» → Mənə qapını bağlamağı dedi."],["«Please help me.» → He asked me to help him.","«Kömək et.» → Ona kömək etməyimi xahiş etdi."],["«Don't be late.» → My boss told me not to be late.","«Gecikmə.» → Müdirim gecikməməyimi dedi."]],
  no:"told me don't be late — səhvdir"}
],
g16: [
 {h:"1. and, but, or, so — iki cümləni bağlayır",
  t:"and, but, or, so iki tam cümləni birləşdirir və onların ARASINDA durur. and = və (əlavə), but = amma (ziddiyyət), or = və ya (seçim), so = ona görə (nəticə). but və so-dan əvvəl çox vaxt vergül qoyulur. Bu sözlərlə yeni cümlə başlamaq danışıqda olur, amma rəsmi yazıda yaxşı sayılmır.",
  ex:[["I was tired, so I went to bed early.","Yorğun idim, ona görə tez yatdım."],["I like tea, but my wife prefers coffee.","Mən çayı sevirəm, amma həyat yoldaşım qəhvəni üstün tutur."]]},
 {h:"2. because yoxsa so?",
  t:"because səbəbi göstərir və «niyə?» sualına cavab verir. so isə nəticəni göstərir: «nə oldu?». Eyni fikri iki cür demək olar: because ilə səbəb ikinci hissədə, so ilə nəticə ikinci hissədə gəlir. Azərbaycanca bunlar «çünki» və «ona görə» sözlərinə uyğundur.",
  tbl:[["səbəb","I stayed at home because I was ill."],["nəticə","I was ill, so I stayed at home."]],
  ex:[["I stayed at home because I was ill.","Xəstə olduğum üçün evdə qaldım."],["I was ill, so I stayed at home.","Xəstə idim, ona görə evdə qaldım."]]},
 {h:"3. because + cümlə, because of + isim",
  t:"because-dan sonra tam cümlə (kim + fel) gəlir. because of-dan sonra isə yalnız isim gəlir, fel yox. Azərbaycanca «yağış yağdığı üçün» və «yağışa görə» fərqini xatırla. İkisini qarışdırma: because + cümlə, because of + isim.",
  ex:[["The match was cancelled because it was raining.","Yağış yağdığı üçün oyun ləğv olundu."],["The match was cancelled because of the rain.","Yağış səbəbindən oyun ləğv olundu."],["I couldn't sleep because of the noise.","Səs-küyə görə yata bilmədim."]],
  no:"because of it was raining / because the rain — səhvdir"},
 {h:"4. however — «lakin» (yeni cümlənin əvvəlində)",
  t:"however but kimi ziddiyyət bildirir, amma daha rəsmidir. O, iki cümləni birləşdirmir — yeni cümləni başlayır. Ondan əvvəl nöqtə, sonra vergül qoyulur. IELTS yazısında but əvəzinə çox işlənir.",
  ex:[["The hotel was expensive. However, the rooms were small.","Otel baha idi. Lakin otaqlar kiçik idi."],["I wanted to go. However, I was too tired.","Getmək istəyirdim. Lakin çox yorğun idim."]]},
 {h:"5. although / even though — «baxmayaraq ki»",
  t:"although + tam cümlə. Azərbaycanca «Baxmayaraq ki…, amma…» deyirik, ingiliscə isə although ilə but BİRLİKDƏ işlənmir — biri kifayətdir. even though daha güclüdür, though danışıqda işlənir.",
  ex:[["Although it was late, we continued working.","Gec olmasına baxmayaraq, işləməyə davam etdik."],["He didn't get the job although he had a lot of experience.","Çox təcrübəsi olsa da, işə qəbul olunmadı."]],
  no:"Although it was late, but we continued — səhvdir"},
 {h:"6. despite / in spite of + isim və ya -ing",
  t:"despite və in spite of «…-a baxmayaraq» deməkdir və mənaca although-a yaxındır. Fərq quruluşdadır: onlardan sonra tam cümlə yox, isim və ya -ing gəlir. despite-dan sonra of yoxdur, in spite of-da isə of mütləqdir. Tam cümlə işlətmək istəyirsənsə, although seç.",
  ex:[["Despite the rain, we went for a walk.","Yağışa baxmayaraq, gəzintiyə çıxdıq."],["In spite of being tired, she went to work.","Yorğun olmasına baxmayaraq, işə getdi."]],
  no:"Despite it was cold / despite of — səhvdir"},
 {h:"7. therefore, as a result — rəsmi «ona görə»",
  t:"therefore və as a result so-nun rəsmi variantlarıdır və nəticəni göstərir. Onlar yeni cümlənin əvvəlində gəlir və arxasından vergül qoyulur. IELTS yazısında so əvəzinə bunları işlətmək daha yaxşıdır. as a result of + isim isə «… nəticəsində» deməkdir.",
  ex:[["She studied very hard. As a result, she passed the exam.","O çox çalışdı. Nəticədə imtahandan keçdi."],["Prices went up. Therefore, people bought less.","Qiymətlər qalxdı. Ona görə insanlar az aldı."]]},
 {h:"8. whereas / while — ziddiyyət",
  t:"whereas və while iki fərqli şeyi müqayisə edəndə işlənir: «…, halbuki …», «…, … isə». Bu sözlər iki tam cümləni birləşdirir. Azərbaycanca bu mənanı çox vaxt «isə» sözü ilə veririk. whereas daha rəsmidir və IELTS yazısında müqayisə üçün çox faydalıdır.",
  ex:[["I like tea, whereas my wife prefers coffee.","Mən çayı sevirəm, həyat yoldaşım isə qəhvəni üstün tutur."],["My brother loves sport, while I hate it.","Qardaşım idmanı sevir, mən isə nifrət edirəm."]]},
 {h:"9. also, in addition, moreover — əlavə fikir",
  t:"Yeni fikir əlavə edəndə also, in addition, moreover işlənir. also «həmçinin» deməkdir və cümlənin ortasında, adi feldən əvvəl (am / is / are-dan sonra) gəlir. In addition, və Moreover, daha rəsmidir: yeni cümlənin əvvəlində, vergüllə gəlir. Danışıqda also və too daha çox işlənir.",
  ex:[["Cars cause pollution. In addition, they make cities noisy.","Maşınlar çirklənmə yaradır. Bundan əlavə, şəhərləri səs-küylü edir."],["She also speaks French.","O həmçinin fransızca danışır."]]},
 {h:"10. for example, such as — nümunə",
  t:"Nümunə gətirmək üçün for example və such as işlənir. For example adətən yeni cümlənin əvvəlində gəlir və arxasından vergül qoyulur. such as isə cümlənin içində işlənir və ondan sonra bir neçə isim sadalanır. such as-dan sonra tam cümlə gəlmir.",
  ex:[["Big cities have many problems, such as traffic and pollution.","Böyük şəhərlərin tıxac və çirklənmə kimi çox problemi var."],["Many students work. For example, my cousin works in a cafe.","Çox tələbə işləyir. Məsələn, əmim oğlu kafedə işləyir."]]},
 {h:"11. Məqsəd: to + fel, so that",
  t:"Bir işi NƏ ÜÇÜN etdiyini demək üçün to + fel işlənir (g10). Məqsəd hissəsində başqa «kim» və ya can / could lazımdırsa, so that + cümlə işlənir. so that-dan sonra çox vaxt can (indi) və ya could (keçmiş) gəlir. for + fel ilə məqsəd bildirilmir.",
  ex:[["I'm saving money to buy a car.","Maşın almaq üçün pul yığıram."],["I left early so that I could catch the train.","Qatara çatmaq üçün tez çıxdım."],["I'll write it down so that I don't forget.","Unutmamaq üçün onu yazacam."]],
  no:"for buy a car — səhvdir"},
 {h:"12. Zaman bağlayıcıları: when, while, during, before, after",
  t:"when və while-dan sonra cümlə gəlir, during-dən sonra isim. before və after-dən sonra cümlə, isim və ya -ing ola bilər. Gələcək mənasında when-dən sonra Present Simple (g05).",
  ex:[["During the lesson, my phone rang.","Dərs zamanı telefonum zəng çaldı."],["I'll call you when I arrive.","Çatanda sənə zəng edəcəm."],["After finishing work, I went to the gym.","İşi bitirdikdən sonra idman zalına getdim."]]}
],
g17: [
 {h:"1. Present Perfect Continuous — «… vaxtdır edirəm»",
  t:"Keçmişdə başlayıb indiyə qədər davam edən iş üçün işlənir, xüsusən nə qədər vaxt getdiyini deyəndə. Forma: have / has + been + fel-ing. Azərbaycanca indiki zamanla deyirik: «bir saatdır gözləyirəm».",
  tbl:[["I / you / we / they","have been waiting ('ve been)"],["he / she / it","has been waiting ('s been)"]],
  ex:[["I've been waiting for an hour.","Bir saatdır gözləyirəm."],["She has been studying for three hours.","O, üç saatdır dərs oxuyur."]],
  no:"I am waiting for an hour — səhvdir"},
 {h:"2. How long have you been …?",
  t:"Bir işin nə qədər vaxtdır davam etdiyini soruşanda How long + have / has + kim + been + -ing işlənir. Cavabda for (müddət) və ya since (başlanğıc) gəlir (g08). Azərbaycanca «neçə vaxtdır…?» deyirik və indiki zaman işlədirik. İngiliscə isə burada Present Simple və ya Present Continuous səhvdir.",
  ex:[["How long have you been learning English?","Neçə vaxtdır ingiliscə öyrənirsən?"],["We have been living here since 2019.","2019-dan burada yaşayırıq."],["She's been working here for six months.","O altı aydır burada işləyir."]],
  no:"How long are you learning English? — səhvdir"},
 {h:"3. Təzəcə bitib, izi görünür",
  t:"İş indicə dayanıbsa və onun izi, nəticəsi görünürsə, yenə have / has been + -ing işlənir. Məsələn, küçə yaşdır — demək, yağış yağırdı. Gözlər qırmızıdır — demək, ağlayıb. Burada vacib olan prosesin özüdür, onun izini isə indi görürük.",
  ex:[["It has been raining. The streets are wet.","Yağış yağıb. Küçələr yaşdır."],["Your eyes are red. Have you been crying?","Gözlərin qırmızıdır. Ağlamısan?"],["I'm tired because I've been working all day.","Yorğunam, çünki bütün günü işləmişəm."]]},
 {h:"4. have done yoxsa have been doing?",
  t:"Nəticə, say (neçə dənə) və ya bitmiş iş vacibdirsə, have + V3 işlənir. Prosesin özü və onun müddəti vacibdirsə, have been + -ing işlənir. Say varsa (three emails, two books), Continuous işlənmir, çünki say bitmiş nəticəni göstərir. Azərbaycanca hər ikisi çox vaxt eyni tərcümə olunur.",
  tbl:[["have + V3 (nəticə, say)","I've written three emails."],["have been + -ing (müddət)","I've been writing emails all morning."]],
  ex:[["I've written three emails.","Üç məktub yazmışam."],["I've been writing emails all morning.","Bütün səhər məktub yazıram."]],
  no:"I've been writing three emails — səhvdir"},
 {h:"5. «Hal» felləri -ing almır",
  t:"g03-dəki «hal» felləri siyahısı (know, understand, believe, remember, mean, like, love, hate, prefer, want, need, belong, seem) burada da -ing almır. Ona görə bu fellərlə müddət deyəndə have been + -ing yox, have + V3 işlənir. Azərbaycanca «on ildir tanıyıram» deyirik — ingiliscə I've known. have «sahib olmaq» mənasında da belədir.",
  ex:[["I've known him for ten years.","Onu on ildir tanıyıram."],["I've had this car for five years.","Bu maşın beş ildir məndədir."],["How long have you known your wife?","Həyat yoldaşını nə vaxtdan tanıyırsan?"]],
  no:"I have been knowing — səhvdir"},
 {h:"6. Past Perfect — «artıq etmişdi»",
  t:"Keçmişdə iki hadisə var və biri o birindən DAHA ƏVVƏL olubsa, daha əvvəlki hadisə üçün had + V3 işlənir. had bütün şəxslər üçün eynidir. Azərbaycanca «getmişdi, başlamışdı».",
  ex:[["When I arrived, the film had already started.","Mən çatanda film artıq başlamışdı."],["By the time we got to the station, the train had left.","Stansiyaya çatanda qatar getmişdi."]]},
 {h:"7. Fərqə bax: started yoxsa had started?",
  t:"Keçmişdə iki hadisə ardıcıl və ya eyni vaxtda olubsa, ikisi də Past Simple olur. Bir hadisə o biri baş verəndə ARTIQ bitmişdisə, daha əvvəlki hadisə üçün had + V3 işlənir. Bir sözün dəyişməsi bütün mənanı dəyişir. Cədvəldəki iki cümləni müqayisə et.",
  tbl:[["When I arrived, the film started.","Mən gəldim, sonra film başladı."],["When I arrived, the film had started.","Film mən gəlməmişdən əvvəl başlamışdı."]],
  ex:[["When I arrived, the film had started.","Mən çatanda film artıq başlamışdı."],["When I arrived, the film started.","Mən çatanda film başladı."]]},
 {h:"8. never / already / just + Past Perfect",
  t:"Keçmişdəki bir andan ƏVVƏLKİ təcrübəni demək üçün had never, had already, had just işlənir. Bu, Present Perfect-dəki never / already / just-ın keçmiş variantıdır. Yəni «o vaxta qədər heç vaxt …-mamışdı». Çox vaxt because ilə səbəb kimi gəlir.",
  ex:[["She was nervous because she had never flown before.","Əsəbi idi, çünki əvvəl heç vaxt təyyarəyə minməmişdi."],["I didn't recognise him because he had changed a lot.","Onu tanımadım, çünki çox dəyişmişdi."],["The film had just started when we arrived.","Biz çatanda film təzəcə başlamışdı."]]},
 {h:"9. after, before, by the time + Past Perfect",
  t:"after, before və by the time (…-anda artıq) sözləri hadisələrin ardıcıllığını göstərir. Daha əvvəl olan iş had + V3 ilə gəlir. after və before ilə sıra artıq aydın olduğu üçün Past Simple də düzdür. by the time ilə isə had + V3 demək olar ki həmişə lazımdır.",
  ex:[["After she had finished work, she went to the gym.","İşi bitirdikdən sonra idman zalına getdi."],["By the time I woke up, my wife had left.","Mən oyananda həyat yoldaşım artıq getmişdi."]]},
 {h:"10. Sual və inkar",
  t:"Past Perfect-də köməkçi söz had-dır. g01-dəki qaydaya görə, köməkçi varsa, do / did lazım deyil. Sualda had «kim»-dən əvvələ keçir, inkarda hadn't (had not) olur. Qısa forması 'd-dir: I'd, she'd.",
  ex:[["Had you ever eaten sushi before that day?","O günə qədər heç suşi yemişdin?"],["I hadn't seen the film.","Filmə baxmamışdım."],["Why hadn't you told me?","Niyə mənə deməmişdin?"]]},
 {h:"11. Past Perfect-i harada görmüsən",
  t:"had + V3 formasını sən artıq iki mövzuda görmüsən: g14-də (3-cü növ şərt) və g15-də (dolayı nitq). Hamısında məna eynidir: keçmişdəki bir andan daha əvvəl olan iş. Bu formanı tanımaq oxuduğun mətnlərdə hadisələrin sırasını anlamağa kömək edir.",
  ex:[["If I had known, I would have helped.","Bilsəydim, kömək edərdim."],["He said he had lost his key.","Açarını itirdiyini dedi."]]}
],
g18: [
 {h:"1. Hər cümlədə «kim + fel» olmalıdır",
  t:"İngilis cümləsi kim (subyekt) və feldən ibarətdir. Bunlardan biri yoxdursa, cümlə yarımçıqdır. Bir nöqtədən o biri nöqtəyə qədər ən azı bir «kim + fel» cütü olmalıdır.",
  ex:[["The city is beautiful.","Şəhər gözəldir."],["It is raining.","Yağış yağır."],["My brother works in a bank.","Qardaşım bankda işləyir."]],
  no:"Is beautiful. / The city beautiful. — səhvdir"},
 {h:"2. Böyük hərf",
  t:"Böyük hərflə yazılanlar: cümlənin ilk sözü, I (mən), insan adları, şəhər və ölkə adları, dillər və millətlər (English, Azerbaijani), həftənin günləri və aylar. Fəsillər (summer, winter) isə kiçik hərflə yazılır. Azərbaycancadan fərqli olaraq, dillər, millətlər, günlər və aylar ingiliscə həmişə böyük hərflə başlayır. I sözü cümlənin ortasında da böyük yazılır.",
  ex:[["I live in Baku and speak Azerbaijani and English.","Bakıda yaşayıram, azərbaycanca və ingiliscə danışıram."],["We met on Monday, 5 May.","5 May, bazar ertəsi tanış olduq."]],
  no:"i live in baku / on monday — səhvdir"},
 {h:"3. İki tam cümlə yalnız vergüllə birləşmir",
  t:"Azərbaycanca iki tam cümləni vergüllə birləşdirmək normaldır. İngiliscə isə bu, səhv sayılır. İki tam cümləni ayırmaq üçün ya nöqtə qoy, ya da and, but, so, because kimi bağlayıcı əlavə et. Vergül tək başına iki cümləni bağlaya bilmir.",
  tbl:[["Səhv","I was tired, I went home."],["Düz","I was tired. I went home."],["Düz","I was tired, so I went home."]],
  ex:[["I was tired, so I went home.","Yorğun idim, ona görə evə getdim."],["I was tired. I went home.","Yorğun idim. Evə getdim."]]},
 {h:"4. when / because / if hissəsi: əvvəldə vergül, sonda yox",
  t:"when, if, because, although ilə başlayan hissə cümlənin əvvəlində gələndə, ondan sonra vergül qoyulur. Bu hissə cümlənin sonunda gələndə isə vergül lazım deyil. Vergül oxucuya bu hissənin harada bitdiyini göstərir. Azərbaycanca da belə hissədən sonra vergül qoyuruq.",
  ex:[["When I arrived, the shop was closed.","Mən çatanda mağaza bağlı idi."],["The shop was closed when I arrived.","Mən çatanda mağaza bağlı idi."],["If you need help, call me.","Köməyə ehtiyacın olsa, mənə zəng et."]]},
 {h:"5. Yarımçıq hissə tək cümlə ola bilməz",
  t:"because, when, although, if ilə başlayan hissə təkbaşına cümlə deyil — o, əsas cümləyə bağlıdır. Ona görə onu nöqtə ilə ayırıb ayrıca yazmaq olmaz. Ya əsas cümlənin əvvəlinə, ya da sonuna birləşdir. Danışıqda sual-cavabda tək Because… demək olar, amma yazıda yox.",
  ex:[["Because I was hungry, I made a sandwich.","Ac olduğum üçün sendviç hazırladım."],["Although it was raining, we went out.","Yağış yağsa da, çölə çıxdıq."],["I stayed at home because I was ill.","Xəstə olduğum üçün evdə qaldım."]],
  no:"I stayed at home. Because I was ill. — səhvdir"},
 {h:"6. However, For example — əvvəldə, vergüllə",
  t:"However, Therefore, For example, In addition sözləri yeni cümlənin əvvəlində durur və arxasından vergül gəlir. Onlardan əvvəl nöqtə olur, vergül yox. Bu sözlər iki cümləni and kimi bağlamır, sadəcə mənanı əlaqələndirir. Ona görə iki tam cümləni vergül + however ilə birləşdirmək səhvdir.",
  ex:[["The flat is small. However, it is very cheap.","Mənzil kiçikdir. Lakin çox ucuzdur."],["For example, many students work part-time.","Məsələn, çox tələbə yarımştat işləyir."]],
  no:"The flat is small, however it is cheap — səhvdir"},
 {h:"7. Siyahıda vergül",
  t:"Üç və daha çox şeyi sadalayanda aralarına vergül qoyulur. Sonuncudan əvvəl vergül yerinə and (və ya or) gəlir. Azərbaycanca da belədir: «çörək, süd və yumurta». İki şey olanda vergül lazım deyil, yalnız and yazılır.",
  ex:[["I bought bread, milk and eggs.","Çörək, süd və yumurta aldım."],["We visited Shaki, Gabala and Guba.","Şəki, Qəbələ və Qubaya getdik."],["I like tea and coffee.","Çayı da, qəhvəni də sevirəm."]]},
 {h:"8. Vergüllü who/which (g13)",
  t:"Əlavə məlumat verən who / which hissəsi iki vergülün arasına alınır: biri əvvəldə, biri sonda. Bu hissə cümlənin ortasındadırsa, ikinci vergülü unutma. Sonda gəlirsə, ikinci vergül yerinə nöqtə qoyulur. Ətraflı qayda g13-dədir.",
  ex:[["My father, who is a doctor, works in Baku.","Həkim olan atam Bakıda işləyir."],["I visited Shaki, which is famous for its sweets.","Şirniyyatları ilə məşhur olan Şəkiyə getdim."],["My sister, who lives in London, is coming next week.","Londonda yaşayan bacım gələn həftə gəlir."]]},
 {h:"9. Apostrof: it's / its və qısaltmalar",
  t:"Apostrof (') iki halda işlənir. Birincisi, qısaltmada düşən hərfin yerinə: it's = it is, don't = do not. İkincisi, sahiblikdə: Ali's car. its («onun» — əşya, heyvan) sahiblik bildirsə də apostrofsuz yazılır.",
  ex:[["It's a good idea.","Bu yaxşı fikirdir."],["The city is famous for its old buildings.","Şəhər köhnə binaları ilə məşhurdur."]],
  no:"Its a good idea / it's tail — səhvdir"},
 {h:"10. Akademik yazıda qısaltma yoxdur",
  t:"IELTS Writing rəsmi yazıdır. Orada don't, can't, it's kimi qısaltmalar yazılmır, tam forma işlənir. Danışıqda və dostuna məktubda isə qısaltmalar normaldır. cannot bitişik yazılır.",
  tbl:[["don't","do not"],["can't","cannot"],["won't","will not"],["it's","it is"]],
  ex:[["Many people do not have enough time.","Çox insanın kifayət qədər vaxtı yoxdur."],["It is not easy to find a good job.","Yaxşı iş tapmaq asan deyil."],["Children cannot learn without practice.","Uşaqlar təcrübəsiz öyrənə bilməz."]]},
 {h:"11. Ötürülən sualın sonunda sual işarəsi yoxdur",
  t:"I asked…, I don't know… ilə başlayan cümlədə sual adi cümləyə çevrilir (g15, g21). Sual sırası olmadığı üçün sonda nöqtə qoyulur. Yalnız bütün cümlə özü sualdırsa (Can you tell me…?), sonda sual işarəsi gəlir. I don't know… isə sual deyil, ona görə nöqtə ilə bitir.",
  ex:[["I asked him where he lived.","Ondan harada yaşadığını soruşdum."],["I don't know what time it starts.","Saat neçədə başladığını bilmirəm."],["Can you tell me where the station is?","Stansiyanın harada olduğunu deyə bilərsən?"]]},
 {h:"12. Yaxşı akademik abzas",
  t:"Yaxşı abzasda bir əsas fikir olur. Əvvəl əsas fikri de, sonra səbəb ver, sonra nümunə gətir. Bu sıra oxucunun fikrini izləməsini asanlaşdırır. Cümlələr çox uzun olmasın: təxminən 15–25 söz.",
  ex:[["Learning a foreign language is very useful.","Xarici dil öyrənmək çox faydalıdır. (əsas fikir)"],["This is because it helps people find better jobs.","Bu, insanlara daha yaxşı iş tapmağa kömək edir. (səbəb)"],["For example, many companies in Baku need staff who speak English.","Məsələn, Bakıda bir çox şirkətə ingiliscə bilən işçi lazımdır. (nümunə)"]]}
],
};
GRAM.forEach(g=>{if(GRAM_EXPL[g.id])g.expl=GRAM_EXPL[g.id];});
